void CLoadCombCtrl::GetAashtoLrfdD08Factor(CString& sDc1Fac, CString& sDc2Fac, CString& sDd1Fac, CString& sDd2Fac, 
                                           CString& sDw1Fac, CString& sDw2Fac, CString& sEh1Fac, CString& sEh2Fac, CString& sEv1Fac, CString& sEv2Fac, 
                                           CString& sEs1Fac, CString& sEs2Fac, CString& sEl1Fac, CString& sEl2Fac, CString& sPs1Fac, CString& sPs2Fac, 
                                           CString& sCr1Fac, CString& sCr2Fac, CString& sSh1Fac, CString& sSh2Fac, 
                                           double& dDc1, double& dDc2, double& dDd1, double& dDd2, double& dDw1, double& dDw2, 
                                           double& dEh1, double& dEh2, double& dEv1, double& dEv2, double& dEs1, double& dEs2, 
                                           double& dEl1, double& dEl2, double& dPs1, double& dPs2, double& dCr1, double& dCr2, 
                                           double& dSh1, double& dSh2, int nStrType)
{  
    double dAshLr08Dc[2], dAshLr08Dd[2], dAshLr08Dw[2], dAshLr08Eh[2], dAshLr08Ev[2], dAshLr08Es[2], dAshLr08El[2];
    double dAshLr08Ps[2], dAshLr08Cr[2], dAshLr08Sh[2];
    // Initialize
    for(int i = 0; i < 2; i++)
    {
        dAshLr08Dc[i] = 0.;
        dAshLr08Dd[i] = 0.;
        dAshLr08Dw[i] = 0.;
        dAshLr08Eh[i] = 0.;
        dAshLr08Ev[i] = 0.;
        dAshLr08Es[i] = 0.;
        dAshLr08El[i] = 0.;

        dAshLr08Ps[i] = 0.;
        dAshLr08Cr[i] = 0.;
        dAshLr08Sh[i] = 0.;
    }
    // Assign global variable to local variable
    for(int i = 0; i < 2; i++)
    {
        dAshLr08Dc[i] = m_dAshLr08Dc[i] * m_dAshLr08Modifier;
        dAshLr08Dd[i] = m_dAshLr08Dd[i] * m_dAshLr08Modifier;
        dAshLr08Dw[i] = m_dAshLr08Dw[i] * m_dAshLr08Modifier;
        dAshLr08Eh[i] = m_dAshLr08Eh[i] * m_dAshLr08Modifier;
        dAshLr08Ev[i] = m_dAshLr08Ev[i] * m_dAshLr08Modifier;
        dAshLr08Es[i] = m_dAshLr08Es[i] * m_dAshLr08Modifier;
        dAshLr08El[i] = m_dAshLr08El[i] * m_dAshLr08Modifier;

        dAshLr08Ps[i] = m_dAshLr08Ps[i] * m_dAshLr08Modifier;
        dAshLr08Cr[i] = m_dAshLr08Cr[i] * m_dAshLr08Modifier;
        dAshLr08Sh[i] = m_dAshLr08Sh[i] * m_dAshLr08Modifier;
    }

    dDc1 = dAshLr08Dc[0];  sDc1Fac.Format(_T("%.2f"), dAshLr08Dc[0]);
    dDc2 = dAshLr08Dc[1];  sDc2Fac.Format(_T("%.2f"), dAshLr08Dc[1]);
    dDd1 = dAshLr08Dd[0];  sDd1Fac.Format(_T("%.2f"), dAshLr08Dd[0]);
    dDd2 = dAshLr08Dd[1];  sDd2Fac.Format(_T("%.2f"), dAshLr08Dd[1]);
    dDw1 = dAshLr08Dw[0];  sDw1Fac.Format(_T("%.2f"), dAshLr08Dw[0]);
    dDw2 = dAshLr08Dw[1];  sDw2Fac.Format(_T("%.2f"), dAshLr08Dw[1]);
    dEh1 = dAshLr08Eh[0];  sEh1Fac.Format(_T("%.2f"), dAshLr08Eh[0]);
    dEh2 = dAshLr08Eh[1];  sEh2Fac.Format(_T("%.2f"), dAshLr08Eh[1]);
    dEv1 = dAshLr08Ev[0];  sEv1Fac.Format(_T("%.2f"), dAshLr08Ev[0]);
    dEv2 = dAshLr08Ev[1];  sEv2Fac.Format(_T("%.2f"), dAshLr08Ev[1]);
    dEs1 = dAshLr08Es[0];  sEs1Fac.Format(_T("%.2f"), dAshLr08Es[0]);
    dEs2 = dAshLr08Es[1];  sEs2Fac.Format(_T("%.2f"), dAshLr08Es[1]);  
    dEl1 = dAshLr08El[0];  sEl1Fac.Format(_T("%.2f"), dAshLr08El[0]);
    dEl2 = dAshLr08El[1];  sEl2Fac.Format(_T("%.2f"), dAshLr08El[1]);  
    dPs1 = dAshLr08Ps[0];  sPs1Fac.Format(_T("%.2f"), dAshLr08Ps[0]);
    dPs2 = dAshLr08Ps[1];  sPs2Fac.Format(_T("%.2f"), dAshLr08Ps[1]);
    dCr1 = dAshLr08Cr[0];  sCr1Fac.Format(_T("%.2f"), dAshLr08Cr[0]);
    dCr2 = dAshLr08Cr[1];  sCr2Fac.Format(_T("%.2f"), dAshLr08Cr[1]);
    dSh1 = dAshLr08Sh[0];  sSh1Fac.Format(_T("%.2f"), dAshLr08Sh[0]);
    dSh2 = dAshLr08Sh[1];  sSh2Fac.Format(_T("%.2f"), dAshLr08Sh[1]);
}


void CLoadCombCtrl::Set_CvlAashtoLrfd08Str(ArINT& arDcLoad, ArINT& arDdLoad, ArINT& arDwLoad, ArINT& arEhLoad, 
                                           ArINT& arEvLoad, ArINT& arEsLoad, ArINT& arElLoad, ArINT& arLLoad, ArINT& arIlLoad, ArINT& arCfLoad, 
                                           ArINT& arBrkLoad,ArINT& arCrlLoad, ArINT& arLsLoad, ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arBLoad,
                                           ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arWLoad, ArINT& arWlLoad, ArINT& arFrLoad, ArINT& arTLoad, 
                                           ArINT& arCrLoad, ArINT& arShLoad, ArINT& arStlLoad, ArUNT& arSmLoad, ArINT& arCSLoad, ArINT& arPsLoad, int nStrType)
{
    if((nStrType == 1 || nStrType == 2) && m_nLCount==0 && m_nCrlCount==0 && m_nLsCount==0 &&  
        m_nStlCount==0 && m_nSmCount==0 && m_nConstLoad==0) return;
    if(nStrType == 2 && m_nLCount==0 && m_nCrlCount==0 && m_nLsCount==0 && (m_nStlCount > 0 || m_nSmCount > 0) && m_nConstLoad==0) return;
    if(nStrType == 3 && m_nWCount == 0) return;
    if(nStrType == 4 && m_nDcCount==0 && m_nDwCount==0 && m_nEhCount==0 && m_nEvCount==0 && 
        m_nEsCount==0 && m_nWpCount==0 && m_nFpCount==0 && m_nBCount==0 &&  m_nSfCount==0 && 
        m_nWprCount==0 && m_nFrCount==0 && m_nTCount==0 && m_nCrCount==0 && m_nShCount==0 && m_nPsCount==0 && m_nConstLoad==0) return;
    if(nStrType == 5 && m_nWCount == 0) return;
    if(nStrType == 5 && m_nWCount > 0  && m_nLCount==0 && m_nCrlCount==0 && m_nLsCount==0 && m_nConstLoad==0) return;

    // Load Factor
    double dModifier = m_dAshLr08Modifier;
    double dLFactor = 0, dCfFactor = 0, dWFactor = 0;
    double dWpFactor = 1.0 * dModifier, dWlFactor = 1.0 * dModifier; 
    double dFrFactor = 1.0 * dModifier, dTFactor = 1.2 * dModifier;
    double dStlFactor = m_dAshLr08Stl * dModifier;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strTitle;
    if     (nStrType == 1) {dLFactor = dCfFactor = 1.75 * dModifier; strTitle = _T("Strength-I:");}
    else if(nStrType == 2) {dLFactor = dCfFactor = 1.35 * dModifier; strTitle = _T("Strength-II:");}
    else if(nStrType == 3) {dWFactor = 1.4 * dModifier; strTitle = _T("Strength-III:");}
    else if(nStrType == 4) {strTitle = _T("Strength-IV:");}
    else if(nStrType == 5) {dLFactor = dCfFactor = 1.35 * dModifier; dWFactor = 0.4 * dModifier; strTitle = _T("Strength-V:");}
    if(m_bAshLr08CulvertChk == TRUE) dLFactor = 2.0 * dModifier;  // Metal Box CulvertÀÎ °æ¿ì
    if(m_nAshLr08Deform == 1) dTFactor = 0.5 * dModifier;         

    CString sLFactor, sCfFactor, sWpFactor, sWFactor, sWlFactor, sFrFactor, sTFactor, sStlFactor, sPSSFactor;
    sLFactor.Format(_T("%.2f"), dLFactor);
    sCfFactor.Format(_T("%.2f"), dCfFactor);
    sWpFactor.Format(_T("%.2f"), dWpFactor);
    sWFactor.Format(_T("%.2f"), dWFactor);
    sWlFactor.Format(_T("%.2f"), dWlFactor);
    sFrFactor.Format(_T("%.2f"), dFrFactor);
    sTFactor.Format(_T("%.2f"), dTFactor);
    sStlFactor.Format(_T("%.2f"), dStlFactor);
    sPSSFactor.Format(_T("%.2f"), dPSS);

    CString sDcFac[2], sDdFac[2], sDwFac[2], sEhFac[2], sEvFac[2], sEsFac[2], sElFac[2], sPsFac[2], sCrFac[2], sShFac[2];
    double dDcFac[2], dDdFac[2], dDwFac[2], dEhFac[2], dEvFac[2], dEsFac[2], dElFac[2], dPsFac[2], dCrFac[2], dShFac[2];
    GetAashtoLrfdD08Factor(sDcFac[0], sDcFac[1], sDdFac[0], sDdFac[1], sDwFac[0], sDwFac[1], sEhFac[0], sEhFac[1], 
        sEvFac[0], sEvFac[1], sEsFac[0], sEsFac[1], sElFac[0], sElFac[1], sPsFac[0], sPsFac[1], sCrFac[0], sCrFac[1], 
        sShFac[0], sShFac[1], dDcFac[0], dDcFac[1], dDdFac[0], dDdFac[1], dDwFac[0], dDwFac[1], dEhFac[0], dEhFac[1], 
        dEvFac[0], dEvFac[1], dEsFac[0], dEsFac[1], dElFac[0], dElFac[1], dPsFac[0], dPsFac[1], dCrFac[0], dCrFac[1], 
        dShFac[0], dShFac[1], nStrType);  

    if(nStrType == 4) 
    {
        if(sDcFac[0] == _T("1.25")) sDcFac[0] = _T("1.50");
        if(sDcFac[1] == _T("1.25")) sDcFac[1] = _T("1.50");
        if(dDcFac[0] == 1.25) dDcFac[0] = 1.50;
        if(dDcFac[1] == 1.25) dDcFac[1] = 1.50;
    }

    int nAshLr08DcNum = m_nAshLr08DcNum;     
    int nAshLr08DdNum = m_nAshLr08DdNum;     // DDÀÇ °³¼ö´Â º¯ÇÔ¾øÀ½
    int nAshLr08DwNum = m_nAshLr08DwNum;
    int nAshLr08EhNum = m_nAshLr08EhNum;
    int nAshLr08ElNum = m_nAshLr08ElNum;
    int nAshLr08EvNum = m_nAshLr08EvNum;
    int nAshLr08EsNum = m_nAshLr08EsNum;  

    int nAshLr08CrNum = m_nAshLr08CrNum;
    int nAshLr08ShNum = m_nAshLr08ShNum;

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nWLCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1;
    int nSmCountTemp = max(m_nSmCount, 1);
    int nBrkCountTemp = max(m_nBrkCount, 1);
    int nTCountTemp = max(m_nTCount, 1);

    int LoadCaseNo;
    T_LCOM_D rData;

    for(int nDc = 0; nDc < nAshLr08DcNum; nDc++) {
        for(int nDd = 0; nDd < nAshLr08DdNum; nDd++) {
            for(int nDw = 0; nDw < nAshLr08DwNum; nDw++) {
                for(int nEh = 0; nEh < nAshLr08EhNum; nEh++) {  
                    for(int nEv = 0; nEv < nAshLr08EvNum; nEv++) {  
                        for(int nEs = 0; nEs < nAshLr08EsNum; nEs++) {
                            for(int nEl = 0; nEl < nAshLr08ElNum; nEl++) {
                                for(int nCr = 0; nCr < nAshLr08CrNum; nCr++) {
                                    for(int nSh = 0; nSh < nAshLr08ShNum; nSh++) 
                                    {
                                        for(int j = 0; j < nWCountTemp; j++){
                                            for(int m = 0; m < nWLCountTemp; m++){
                                                for(int k = 0; k < nSmCountTemp; k++){
                                                    for(int n = 0; n < nTCountTemp; n++){
                                                        for(int o = 0; o < nBrkCountTemp; o++)
                                                        {
                                                            CString strFixW, strFixWL, strFixSm, strFixT, csPrefix, strFixBrk = _T(""), csPrefix_Tmp = _T("");  
                                                            strFixW.Format(_T("%d"), j/2+1);
                                                            strFixWL.Format(_T("%d"), m/2+1);
                                                            strFixSm.Format(_T("%d"), k+1);     
                                                            strFixT.Format(_T("%d"), n+1);
                                                            strFixBrk.Format(_T("%d"), o+1);
                                                            rData.Initialize();  
                                                            LoadCaseNo = 0;
                                                            int i=0, nDCL=0, nDDL=0, nDWL=0, nEHL=0, nEVL=0, nESL=0, nELL=0, nLL=0, nIL=0, nCF=0, nBRK=0, nCRL=0, nLS=0;
                                                            int nWP=0, nFP=0, nBL=0, nSF=0, nWPR=0, nWL=0, nWLL=0, nFR=0, nTL=0, nPS=0, nCR=0,nSH=0, nSTL=0, nn=0;
                                                            for(i=0; i<m_nDcCount; i++)   nDCL += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc], LoadCaseNo, rData, D_SGLD_DL_CVL);
                                                            if(nStrType != 4)
                                                            {
                                                                for(i=0; i<m_nDdCount; i++) nDDL += Set_STLCIncludeCS(arDdLoad.GetAt(i),  dDdFac[nDd], LoadCaseNo, rData, 0);
                                                            }
                                                            for(i=0; i<m_nDwCount; i++)   nDWL += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw], LoadCaseNo, rData, D_SGLD_DL_CVL);
                                                            for(i=0; i<m_nEhCount; i++)   nEHL += Set_STLCIncludeCS(arEhLoad.GetAt(i),  dEhFac[nEh], LoadCaseNo, rData, 0);
                                                            for(i=0; i<m_nEvCount; i++)   nEVL += Set_STLCIncludeCS(arEvLoad.GetAt(i),  dEvFac[nEv], LoadCaseNo, rData, 0);
                                                            for(i=0; i<m_nEsCount; i++)   nESL += Set_STLCIncludeCS(arEsLoad.GetAt(i),  dEsFac[nEs], LoadCaseNo, rData, 0);
                                                            if(nStrType != 4)
                                                            {            
                                                                for(i=0; i<m_nElCount; i++) nELL += Set_STLCIncludeCS(arElLoad.GetAt(i),  dElFac[nEl], LoadCaseNo, rData, 0);
                                                            }
                                                            if(nStrType == 1 || nStrType == 2 || nStrType == 5)
                                                            {
                                                                if(m_nLCount > 0)  
                                                                {
                                                                    for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dLFactor,   LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dLFactor,   LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor,  LoadCaseNo, rData, 0);
                                                                    if(m_nBrkCount > 0)         nBRK+= Set_STLCIncludeCS(arBrkLoad.GetAt(o),dCfFactor,  LoadCaseNo, rData, 0);
                                                                }
                                                                for(i=0; i<m_nCrlCount; i++)  nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCfFactor,  LoadCaseNo, rData, 0);
                                                                for(i=0; i<m_nLsCount; i++)   nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i),  dCfFactor,  LoadCaseNo, rData, 0);            
                                                            }
                                                            for(i=0; i<m_nWpCount; i++)   nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                                            for(i=0; i<m_nFpCount; i++)   nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                                            for(i=0; i<m_nBCount; i++)    nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),   dWpFactor,  LoadCaseNo, rData, 0);
                                                            for(i=0; i<m_nSfCount; i++)   nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                                            for(i=0; i<m_nWprCount; i++)  nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i), dWpFactor,  LoadCaseNo, rData, 0);
                                                            double dWF = (j%2==0) ? dWFactor : -1.*dWFactor;
                                                            if((nStrType == 3 || nStrType == 5) && m_nWCount > 0)
                                                            {
                                                                nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);
                                                            }
                                                            double dWLF = (m%2==0) ? dWlFactor : -1.*dWlFactor;
                                                            if(nStrType == 5 && m_nWlCount > 0)
                                                            {
                                                                nWLL += Set_STLCIncludeCS(arWlLoad.GetAt(m/2), dWLF, LoadCaseNo, rData, 0);
                                                                //for(i=0; i<m_nWlCount; i++) nWLL += Set_STLCIncludeCS(arWlLoad.GetAt(i),  dWlFactor,  LoadCaseNo, rData, 0);
                                                            }
                                                            for(i=0; i<m_nFrCount; i++)   nFR += Set_STLCIncludeCS(arFrLoad.GetAt(i),  dFrFactor,   LoadCaseNo, rData, 0);
                                                            if(m_nTCount > 0)             nTL += Set_STLCIncludeCS(arTLoad.GetAt(n),   dTFactor,    LoadCaseNo, rData, 0);
                                                            for(i=0; i<m_nCrCount; i++)   nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i),  dTFactor, LoadCaseNo, rData, D_SGLD_CS_CVL);
                                                            for(i=0; i<m_nShCount; i++)   nSH += Set_STLCIncludeCS(arShLoad.GetAt(i),  dTFactor, LoadCaseNo, rData, D_SGLD_SS_CVL);
                                                            if(nStrType != 4)
                                                            {
                                                                for(i=0; i<m_nStlCount; i++) nSTL+= Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                                if(m_nSmCount > 0)           Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                            }
                                                            if(m_nConstLoad!=0)
                                                            {
                                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn)) Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);

                                                                CString strcEL;
                                                                int nErection = 0;

                                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                                {
                                                                    strcEL = _T(""); nErection = 0;
                                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                                                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                                    else if(CheckCSEL(nErection, _T("DW")))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                                    else if((nStrType == 1 || nStrType == 2 || nStrType == 5) && CheckCSEL(nErection, _T("L")))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dLFactor, LoadCaseNo, rData, TRUE);
                                                                    else if((nStrType == 3 || nStrType == 5) && CheckCSEL(nErection, _T("W")))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dWFactor, LoadCaseNo, rData, TRUE);
                                                                    else if(CheckCSEL(nErection, _T("T")))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                    else if(nStrType != 4 && CheckCSEL(nErection, _T("STL")))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dStlFactor, LoadCaseNo, rData, TRUE);
                                                                }
                                                                if (m_nAshLr08Deform == 0) // Deform Check
                                                                {
                                                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                                                    if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                    if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                }
                                                                else // All other
                                                                {
                                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                }
                                                            }

                                                            if(m_nLcomType == D_LCOMTYPE_STLCOMP) csPrefix_Tmp = _T(",");
                                                            else                                  csPrefix_Tmp = _T("+");    

                                                            rData.Description = strTitle;  
                                                            if(nDCL>0)  {rData.Description += csPrefix + sDcFac[nDc] + _T("DC"); csPrefix = csPrefix_Tmp;}
                                                            if(nStrType != 4)
                                                            {
                                                                if(nDDL>0) {rData.Description += csPrefix + sDdFac[nDd] + _T("DD"); csPrefix = csPrefix_Tmp;}
                                                            }
                                                            if(nDWL>0)  {rData.Description += csPrefix + sDwFac[nDw] + _T("DW"); csPrefix = csPrefix_Tmp;}
                                                            if(nEHL>0)  {rData.Description += csPrefix + sEhFac[nEh] + _T("EH"); csPrefix = csPrefix_Tmp;}
                                                            if(nEVL>0)  {rData.Description += csPrefix + sEvFac[nEv] + _T("EV"); csPrefix = csPrefix_Tmp;}
                                                            if(nESL>0)  {rData.Description += csPrefix + sEsFac[nEs] + _T("ES"); csPrefix = csPrefix_Tmp;}
                                                            if(nStrType != 4)
                                                            {
                                                                if(nELL>0) {rData.Description += csPrefix + sElFac[nEl] + _T("EL"); csPrefix = csPrefix_Tmp;}
                                                            }
                                                            if(nStrType == 1 || nStrType == 2 || nStrType == 5)
                                                            {
                                                                if(m_nLCount > 0)
                                                                {
                                                                    if(nLL > 0) {rData.Description += csPrefix + sLFactor  + _T("L");   csPrefix = csPrefix_Tmp;}
                                                                    if(nIL > 0) {rData.Description += csPrefix + sLFactor  + _T("IL");  csPrefix = csPrefix_Tmp;}
                                                                    if(nCF > 0) {rData.Description += csPrefix + sCfFactor + _T("CF");  csPrefix = csPrefix_Tmp;}
                                                                    if(nBRK> 0) {rData.Description += csPrefix + sCfFactor + _T("BRK[") + strFixBrk + _T("]"); csPrefix = csPrefix_Tmp;}
                                                                }  
                                                                if(nCRL> 0) {rData.Description += csPrefix + sCfFactor + _T("CRL"); csPrefix = csPrefix_Tmp;}
                                                                if(nLS > 0) {rData.Description += csPrefix + sCfFactor + _T("LS");  csPrefix = csPrefix_Tmp;}            
                                                            }
                                                            if(nWP > 0) {rData.Description += csPrefix + sWpFactor + _T("WP");  csPrefix = csPrefix_Tmp;}
                                                            if(nFP > 0) {rData.Description += csPrefix + sWpFactor + _T("FP");  csPrefix = csPrefix_Tmp;} 
                                                            if(nBL > 0) {rData.Description += csPrefix + sWpFactor + _T("B");   csPrefix = csPrefix_Tmp;} 
                                                            if(nSF > 0) {rData.Description += csPrefix + sWpFactor + _T("SF");  csPrefix = csPrefix_Tmp;} 
                                                            if(nWPR> 0) {rData.Description += csPrefix + sWpFactor + _T("WPR"); csPrefix = csPrefix_Tmp;}
                                                            if(nStrType == 3 || nStrType == 5)
                                                            {
                                                                if(nWL > 0) {if(dWF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = csPrefix_Tmp;}
                                                            }
                                                            if(nStrType == 5)
                                                            {
                                                                if(nWLL > 0) {if(dWLF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWLF) + _T("WL[") + strFixWL + _T("]"); csPrefix = csPrefix_Tmp;}
                                                                //if(nWLL > 0) {rData.Description += csPrefix + sWlFactor + _T("WL"); csPrefix = csPrefix_Tmp;}
                                                            }
                                                            if(nFR > 0) {rData.Description += csPrefix + sFrFactor + _T("FR"); csPrefix = csPrefix_Tmp;}
                                                            if(nTL > 0) {rData.Description += csPrefix + sTFactor  + _T("T[") + strFixT + _T("]");  csPrefix = csPrefix_Tmp;}
                                                            if(nCR > 0) {rData.Description += csPrefix + sTFactor  + _T("CR"); csPrefix = csPrefix_Tmp;}
                                                            if(nSH > 0) {rData.Description += csPrefix + sTFactor  + _T("SH"); csPrefix = csPrefix_Tmp;}
                                                            if(nStrType != 4)
                                                            {
                                                                if(nSTL> 0) {rData.Description += csPrefix + sStlFactor + _T("STL"); csPrefix = csPrefix_Tmp;}
                                                                if(m_nSmCount > 0) {rData.Description += csPrefix + sStlFactor + _T("SM[") + strFixSm + _T("]"); csPrefix = csPrefix_Tmp;}              
                                                            }
                                                            if(m_nConstLoad!=0)
                                                            {
                                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                                {rData.Description += csPrefix + sDcFac[nDc] + _T("(cD)"); csPrefix = csPrefix_Tmp;}

                                                                CString strcEL;
                                                                int nErection = 0;

                                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                                {
                                                                    strcEL = _T(""); nErection = 0;
                                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                                                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")))
                                                                    {rData.Description += csPrefix + sDcFac[nDc] + strcEL; csPrefix = csPrefix_Tmp;}
                                                                    else if(CheckCSEL(nErection, _T("DW")))
                                                                    {rData.Description += csPrefix + sDwFac[nDw] + strcEL; csPrefix = csPrefix_Tmp;}
                                                                    else if((nStrType == 1 || nStrType == 2 || nStrType == 5) && CheckCSEL(nErection, _T("L")))
                                                                    {rData.Description += csPrefix + sLFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                                    else if((nStrType == 3 || nStrType == 5) && CheckCSEL(nErection, _T("W")))
                                                                    {rData.Description += csPrefix + sWFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                                    else if(CheckCSEL(nErection, _T("T")))
                                                                    {rData.Description += csPrefix + sTFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                                    else if(nStrType != 4 && CheckCSEL(nErection, _T("STL")))
                                                                    {rData.Description += csPrefix + sStlFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                                }
                                                                if (m_nAshLr08Deform == 0) // Deform Check
                                                                {
                                                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                                                    {rData.Description += csPrefix + sPSSFactor + _T("(cTP)"); csPrefix = csPrefix_Tmp;}
                                                                    if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                                                    {rData.Description += csPrefix + sTFactor + _T("(cCR)"); csPrefix = csPrefix_Tmp;}
                                                                    if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                                                    {rData.Description += csPrefix + sTFactor + _T("(cSH)"); csPrefix = csPrefix_Tmp;}
                                                                }
                                                                else // All other
                                                                {
                                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                                    {rData.Description += csPrefix + sPSSFactor + _T("(cTS)"); csPrefix = csPrefix_Tmp;}
                                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                                    {rData.Description += csPrefix + sTFactor + _T("(cCR)"); csPrefix = csPrefix_Tmp;}
                                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                                    {rData.Description += csPrefix + sTFactor + _T("(cSH)"); csPrefix = csPrefix_Tmp;}
                                                                }
                                                            }

                                                            if(LoadCaseNo > 0)
                                                            {
                                                                if(m_nLcomType == D_LCOMTYPE_STLCOMP)
                                                                {
                                                                    rData.nActive = 1;
                                                                    rData.nSubLcomType = 0;
                                                                }

                                                                Set_LoadComb4Civil(rData, D_STR);
                                                            }
                                                        }}}}}
                                    }}}}}}}}}
}

void CLoadCombCtrl::Set_CvlAashtoLrfd08Str_M(ArINT& arDcLoad, ArINT& arDdLoad, ArINT& arDwLoad, ArINT& arEhLoad, 
                                             ArINT& arEvLoad, ArINT& arEsLoad, ArINT& arElLoad, ArUNT& arMLoad, ArINT& arLLoad, ArINT& arIlLoad, 
                                             ArINT& arCfLoad, ArINT& arBrkLoad, ArINT& arCrlLoad, ArINT& arLsLoad, ArINT& arWpLoad, ArINT& arFpLoad,
                                             ArINT& arBLoad,  ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arWLoad, ArINT& arWlLoad, ArINT& arFrLoad, 
                                             ArINT& arTLoad,  ArINT& arCrLoad, ArINT& arShLoad, ArINT& arStlLoad, ArUNT& arSmLoad, ArINT& arCSLoad, ArINT& arPsLoad,
                                             int nStrType)
{
    if((nStrType == 1 || nStrType == 2) && m_nLCount==0 && m_nMCount==0 && m_nCrlCount==0 && m_nLsCount==0 &&  
        m_nStlCount==0 && m_nSmCount==0 && m_nConstLoad==0) return;
    if(nStrType == 2 && m_nLCount==0 && m_nMCount==0 && m_nCrlCount==0 && m_nLsCount==0 &&
        (m_nStlCount > 0 || m_nSmCount > 0) && m_nConstLoad==0) return;
    if(nStrType == 3 && m_nWCount == 0) return;
    if(nStrType == 4 && m_nDcCount==0 && m_nDwCount==0 && m_nEhCount==0 && m_nEvCount==0 && 
        m_nEsCount==0 && m_nWpCount==0 && m_nFpCount==0 && m_nBCount==0 &&  m_nSfCount==0 && 
        m_nWprCount==0 && m_nFrCount==0 && m_nTCount==0 && m_nCrCount==0 && m_nShCount==0 && m_nPsCount==0 && m_nConstLoad==0) return;
    if(nStrType == 5 && m_nWCount == 0) return;
    if(nStrType == 5 && m_nWCount > 0  && m_nLCount==0 && m_nMCount==0 && m_nCrlCount==0 &&
        m_nLsCount==0 && m_nConstLoad==0) return;

    // Load Factor
    double dModifier = m_dAshLr08Modifier;
    double dLFactor=0., dCfFactor=0., dWFactor=0.;
    double dWpFactor = 1.0 * dModifier, dWlFactor = 1.0 * dModifier;
    double dFrFactor = 1.0 * dModifier, dTFactor = 1.2 * dModifier;
    double dStlFactor = m_dAshLr08Stl * dModifier;
    double dPSS = (m_bLossFactor ? m_dLossFactorService : 1.0);
    CString strTitle;
    if     (nStrType == 1) {dLFactor = dCfFactor = 1.75 * dModifier; strTitle = _T("Strength-I:");}
    else if(nStrType == 2) {dLFactor = dCfFactor = 1.35 * dModifier; strTitle = _T("Strength-II:");}
    else if(nStrType == 3) {dWFactor = 1.4 * dModifier; strTitle = _T("Strength-III:");}
    else if(nStrType == 4) {strTitle = _T("Strength-IV:");}
    else if(nStrType == 5) {dLFactor = dCfFactor = 1.35 * dModifier; dWFactor = 0.4*dModifier; strTitle = _T("Strength-V:");}
    if(m_bAshLr08CulvertChk == TRUE) dLFactor=2.0 * dModifier;  // Metal Box CulvertÀÎ °æ¿ì
    if(m_nAshLr08Deform == 1) dTFactor=0.5 * dModifier;           

    CString sLFactor, sCfFactor, sWpFactor, sWFactor, sWlFactor, sFrFactor, sTFactor, sStlFactor, sPSSFactor;
    sLFactor.Format(_T("%.2f"), dLFactor);
    sCfFactor.Format(_T("%.2f"), dCfFactor);
    sWpFactor.Format(_T("%.2f"), dWpFactor);
    sWFactor.Format(_T("%.2f"), dWFactor);
    sWlFactor.Format(_T("%.2f"), dWlFactor);
    sFrFactor.Format(_T("%.2f"), dFrFactor);
    sTFactor.Format(_T("%.2f"), dTFactor);
    sStlFactor.Format(_T("%.2f"), dStlFactor);
    sPSSFactor.Format(_T("%.2f"), dPSS);

    CString sDcFac[2], sDdFac[2], sDwFac[2], sEhFac[2], sEvFac[2], sEsFac[2], sElFac[2], sPsFac[2], sCrFac[2], sShFac[2];
    double dDcFac[2], dDdFac[2], dDwFac[2], dEhFac[2], dEvFac[2], dEsFac[2], dElFac[2], dPsFac[2], dCrFac[2], dShFac[2];
    GetAashtoLrfdD08Factor(sDcFac[0], sDcFac[1], sDdFac[0], sDdFac[1], sDwFac[0], sDwFac[1], sEhFac[0], sEhFac[1], 
        sEvFac[0], sEvFac[1], sEsFac[0], sEsFac[1], sElFac[0], sElFac[1], sPsFac[0], sPsFac[1], sCrFac[0], sCrFac[1], 
        sShFac[0], sShFac[1], dDcFac[0], dDcFac[1], dDdFac[0], dDdFac[1], dDwFac[0], dDwFac[1], dEhFac[0], dEhFac[1], 
        dEvFac[0], dEvFac[1], dEsFac[0], dEsFac[1], dElFac[0], dElFac[1], dPsFac[0], dPsFac[1], dCrFac[0], dCrFac[1], 
        dShFac[0], dShFac[1], nStrType);   

    if(nStrType == 4) 
    {
        if(sDcFac[0] == _T("1.25")) sDcFac[0] = _T("1.50");
        if(sDcFac[1] == _T("1.25")) sDcFac[1] = _T("1.50");
        if(dDcFac[0] == 1.25) dDcFac[0] = 1.50;
        if(dDcFac[1] == 1.25) dDcFac[1] = 1.50;
    }

    int nAshLr08DcNum = m_nAshLr08DcNum;     
    int nAshLr08DdNum = m_nAshLr08DdNum;     // DDÀÇ °³¼ö´Â º¯ÇÔ¾øÀ½
    int nAshLr08DwNum = m_nAshLr08DwNum;
    int nAshLr08EhNum = m_nAshLr08EhNum;
    int nAshLr08ElNum = m_nAshLr08ElNum;
    int nAshLr08EvNum = m_nAshLr08EvNum;
    int nAshLr08EsNum = m_nAshLr08EsNum;  

    int nAshLr08PsNum = m_nAshLr08PsNum;
    int nAshLr08CrNum = m_nAshLr08CrNum;
    int nAshLr08ShNum = m_nAshLr08ShNum;

    int nWCountTemp  = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nWLCountTemp  = (m_nWlCount>0) ? m_nWlCount*2 : 1;
    int nSmCountTemp = max(m_nSmCount, 1);
    int nTCountTemp  = max(m_nTCount, 1);
    int nBrkCountTemp = max(m_nBrkCount, 1);
    int nMCount      = max(m_nMCount, 1);

    int LoadCaseNo;
    T_LCOM_D rData;

    for(int nDc = 0; nDc < nAshLr08DcNum; nDc++) {
        for(int nDd = 0; nDd < nAshLr08DdNum; nDd++) {
            for(int nDw = 0; nDw < nAshLr08DwNum; nDw++) {
                for(int nEh = 0; nEh < nAshLr08EhNum; nEh++) {  
                    for(int nEv = 0; nEv < nAshLr08EvNum; nEv++) {
                        for(int nEs = 0; nEs < nAshLr08EsNum; nEs++) {
                            for(int nEl = 0; nEl < nAshLr08ElNum; nEl++) {
                                for(int nPs = 0; nPs < nAshLr08PsNum; nPs++) {
                                    for(int nCr = 0; nCr < nAshLr08PsNum; nCr++) {
                                        for(int nSh = 0; nSh < nAshLr08PsNum; nSh++) 
                                        {  
                                            for(int l = 0; l < nMCount; l++) {
                                                for(int j = 0; j < nWCountTemp; j++) {
                                                    for(int m = 0; m < nWLCountTemp; m++) {
                                                        for(int k = 0; k < nSmCountTemp; k++) {
                                                            for(int n = 0; n < nTCountTemp; n++){
                                                                for(int o = 0; o < nBrkCountTemp; o++)
                                                                {        
                                                                    CString strFixM, strFixW, strFixWL, strFixSm, strFixT, strFixBrk, csPrefix = _T(""), csPrefix_Tmp = _T("");  
                                                                    strFixM.Format(_T("%d"), l+1);
                                                                    strFixW.Format(_T("%d"), j/2+1);
                                                                    strFixWL.Format(_T("%d"), m/2+1);
                                                                    strFixSm.Format(_T("%d"), k+1);
                                                                    strFixT.Format(_T("%d"), n+1);
                                                                    strFixBrk.Format(_T("%d"), o+1);
                                                                    rData.Initialize();  
                                                                    LoadCaseNo = 0;
                                                                    int i=0, nDCL=0, nDDL=0, nDWL=0, nEHL=0, nEVL=0, nESL=0, nELL=0, nLL=0, nIL=0, nCF=0, nBRK=0, nCRL=0, nLS=0;
                                                                    int nWP=0, nFP=0, nBL=0, nSF=0, nWPR=0, nWL=0, nWLL=0, nFR=0, nTL=0, nPS=0, nCR=0,nSH=0, nSTL=0, nn=0;
                                                                    for(i=0; i<m_nDcCount; i++)   nDCL += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc], LoadCaseNo, rData, D_SGLD_DL_CVL);
                                                                    if(nStrType != 4)
                                                                    {
                                                                        for(i=0; i<m_nDdCount; i++) nDDL += Set_STLCIncludeCS(arDdLoad.GetAt(i),  dDdFac[nDd], LoadCaseNo, rData, 0);
                                                                    }
                                                                    for(i=0; i<m_nDwCount; i++)   nDWL += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw], LoadCaseNo, rData, D_SGLD_DL_CVL);
                                                                    for(i=0; i<m_nEhCount; i++)   nEHL += Set_STLCIncludeCS(arEhLoad.GetAt(i),  dEhFac[nEh], LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nEvCount; i++)   nEVL += Set_STLCIncludeCS(arEvLoad.GetAt(i),  dEvFac[nEv], LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nEsCount; i++)   nESL += Set_STLCIncludeCS(arEsLoad.GetAt(i),  dEsFac[nEs], LoadCaseNo, rData, 0);
                                                                    if(nStrType != 4)
                                                                    {
                                                                        for(i=0; i<m_nElCount; i++) nELL += Set_STLCIncludeCS(arElLoad.GetAt(i),  dElFac[nEl], LoadCaseNo, rData, 0);
                                                                    }
                                                                    if(nStrType == 1 || nStrType == 2 || nStrType == 5)
                                                                    {
                                                                        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dLFactor, LoadCaseNo, rData, TRUE);
                                                                        if(m_nLCount > 0)  
                                                                        {
                                                                            for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dLFactor,   LoadCaseNo, rData, 0);
                                                                            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dLFactor,   LoadCaseNo, rData, 0);
                                                                        }
                                                                        if(m_nMCount>0 || m_nLCount>0)
                                                                        {
                                                                            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor,  LoadCaseNo, rData, 0);
                                                                            if(m_nBrkCount > 0)         nBRK+= Set_STLCIncludeCS(arBrkLoad.GetAt(o),dCfFactor,  LoadCaseNo, rData, 0);
                                                                        }
                                                                        for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCfFactor,  LoadCaseNo, rData, 0);
                                                                        for(i=0; i<m_nLsCount; i++)  nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i), dCfFactor,  LoadCaseNo, rData, 0);              
                                                                    }
                                                                    for(i=0; i<m_nWpCount; i++)   nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nFpCount; i++)   nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nBCount; i++)    nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),   dWpFactor,  LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nSfCount; i++)   nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nWprCount; i++)  nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i), dWpFactor,  LoadCaseNo, rData, 0);
                                                                    double dWF = (j%2==0) ? dWFactor : -1.*dWFactor;
                                                                    if((nStrType == 3 || nStrType == 5) && m_nWCount > 0)
                                                                    {
                                                                        nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);
                                                                    }
                                                                    double dWLF = (m%2==0) ? dWlFactor : -1.*dWlFactor;
                                                                    if(nStrType == 5 && m_nWlCount > 0)
                                                                    {
                                                                        nWLL += Set_STLCIncludeCS(arWlLoad.GetAt(m/2), dWLF, LoadCaseNo, rData, 0);
                                                                        //for(i=0; i<m_nWlCount; i++) nWLL+= Set_STLCIncludeCS(arWlLoad.GetAt(i),  dWlFactor,  LoadCaseNo, rData, 0);
                                                                    }
                                                                    for(i=0; i<m_nFrCount; i++) nFR += Set_STLCIncludeCS(arFrLoad.GetAt(i),  dFrFactor,  LoadCaseNo, rData, 0);
                                                                    if(m_nTCount > 0)           nTL += Set_STLCIncludeCS(arTLoad.GetAt(n),   dTFactor,   LoadCaseNo, rData, 0);
                                                                    for(i=0; i<m_nCrCount; i++) nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i),  dTFactor, LoadCaseNo, rData, D_SGLD_CS_CVL);
                                                                    for(i=0; i<m_nShCount; i++) nSH += Set_STLCIncludeCS(arShLoad.GetAt(i),  dTFactor, LoadCaseNo, rData, D_SGLD_SS_CVL);
                                                                    if(nStrType != 4)
                                                                    {
                                                                        for(i=0; i<m_nStlCount; i++) nSTL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                                        if(m_nSmCount > 0)           Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                                    }
                                                                    if(m_nConstLoad!=0)
                                                                    {
                                                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);

                                                                        CString strcEL;
                                                                        int nErection = 0;

                                                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                                        {
                                                                            strcEL = _T(""); nErection = 0;
                                                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                                                            if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                                            else if(CheckCSEL(nErection, _T("DW")))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                                            else if((nStrType == 1 || nStrType == 2 || nStrType == 5) && CheckCSEL(nErection, _T("L")))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dLFactor, LoadCaseNo, rData, TRUE);
                                                                            else if((nStrType == 3 || nStrType == 5) && CheckCSEL(nErection, _T("W")))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dWFactor, LoadCaseNo, rData, TRUE);
                                                                            else if(CheckCSEL(nErection, _T("T")))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                            else if(nStrType != 4 && CheckCSEL(nErection, _T("STL")))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dStlFactor, LoadCaseNo, rData, TRUE);
                                                                        }
                                                                        // MQC:2246-JHYUN-20081105
                                                                        if (m_nAshLr08Deform == 0) // Deform Check
                                                                        {
                                                                            if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                                                            if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                            if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                        }
                                                                        else // All other
                                                                        {
                                                                            if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                                                            if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                            if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                        }
                                                                        //         if(CheckCS_SgldK(D_SGLD_TS_CVL, nn)) Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                                                        //         if(CheckCS_SgldK(D_SGLD_CS_CVL, nn)) Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                        //         if(CheckCS_SgldK(D_SGLD_SS_CVL, nn)) Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                    }

                                                                    if(m_nLcomType == D_LCOMTYPE_STLCOMP) csPrefix_Tmp = _T(",");
                                                                    else                                  csPrefix_Tmp = _T("+");    

                                                                    rData.Description = strTitle;  
                                                                    if(nDCL > 0)  {rData.Description += csPrefix + sDcFac[nDc] + _T("DC"); csPrefix = csPrefix_Tmp;}
                                                                    if(nStrType != 4)
                                                                    {
                                                                        if(nDDL > 0) {rData.Description += csPrefix + sDdFac[nDd] + _T("DD"); csPrefix = csPrefix_Tmp;}
                                                                    }
                                                                    if(nDWL  > 0)  {rData.Description += csPrefix + sDwFac[nDw] + _T("DW"); csPrefix = csPrefix_Tmp;}
                                                                    if(nEHL  > 0)  {rData.Description += csPrefix + sEhFac[nEh] + _T("EH"); csPrefix = csPrefix_Tmp;}
                                                                    if(nEVL  > 0)  {rData.Description += csPrefix + sEvFac[nEv] + _T("EV"); csPrefix = csPrefix_Tmp;}
                                                                    if(nESL  > 0)  {rData.Description += csPrefix + sEsFac[nEs] + _T("ES"); csPrefix = csPrefix_Tmp;}
                                                                    if(nStrType != 4)
                                                                    {
                                                                        if(nELL > 0) {rData.Description += csPrefix + sElFac[nEl] + _T("EL"); csPrefix = csPrefix_Tmp;}
                                                                    }
                                                                    if(nStrType == 1 || nStrType == 2 || nStrType == 5)
                                                                    {
                                                                        if(m_nMCount>0) {rData.Description += csPrefix + sLFactor  + _T("M[") + strFixM + _T("]"); csPrefix = csPrefix_Tmp;}
                                                                        if(m_nLCount > 0)
                                                                        {
                                                                            if(nLL > 0) {rData.Description += csPrefix + sLFactor  + _T("L");   csPrefix = csPrefix_Tmp;}
                                                                            if(nIL > 0) {rData.Description += csPrefix + sLFactor  + _T("IL");  csPrefix = csPrefix_Tmp;}
                                                                        }  
                                                                        if(m_nMCount>0 || m_nLCount>0)
                                                                        {
                                                                            if(nCF > 0) {rData.Description += csPrefix + sCfFactor + _T("CF");  csPrefix = csPrefix_Tmp;}
                                                                            if(nBRK> 0) {rData.Description += csPrefix + sCfFactor + _T("BRK[") + strFixBrk + _T("]"); csPrefix = csPrefix_Tmp;}
                                                                        }
                                                                        if(nCRL> 0) {rData.Description += csPrefix + sCfFactor + _T("CRL"); csPrefix = csPrefix_Tmp;}
                                                                        if(nLS > 0) {rData.Description += csPrefix + sCfFactor + _T("LS");  csPrefix = csPrefix_Tmp;}              
                                                                    }
                                                                    if(nWP > 0) {rData.Description += csPrefix + sWpFactor + _T("WP");  csPrefix = csPrefix_Tmp;} 
                                                                    if(nFP > 0) {rData.Description += csPrefix + sWpFactor + _T("FP");  csPrefix = csPrefix_Tmp;} 
                                                                    if(nBL > 0) {rData.Description += csPrefix + sWpFactor + _T("B");   csPrefix = csPrefix_Tmp;} 
                                                                    if(nSF > 0) {rData.Description += csPrefix + sWpFactor + _T("SF");  csPrefix = csPrefix_Tmp;} 
                                                                    if(nWPR> 0) {rData.Description += csPrefix + sWpFactor + _T("WPR"); csPrefix = csPrefix_Tmp;}
                                                                    if(nStrType == 3 || nStrType == 5)
                                                                    {
                                                                        if(nWL > 0) {if(dWF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = csPrefix_Tmp;}
                                                                    }
                                                                    if(nStrType == 5)
                                                                    {
                                                                        if(nWLL > 0) {if(dWLF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWLF) + _T("WL[") + strFixWL + _T("]"); csPrefix = csPrefix_Tmp;}
                                                                        //if(nWLL > 0) {rData.Description += csPrefix + sWlFactor + _T("WL"); csPrefix = csPrefix_Tmp;}
                                                                    }
                                                                    if(nFR > 0) {rData.Description += csPrefix + sFrFactor + _T("FR");  csPrefix = csPrefix_Tmp;}
                                                                    if(nTL > 0) {rData.Description += csPrefix + sTFactor  + _T("T[") + strFixT + _T("]");  csPrefix = csPrefix_Tmp;}
                                                                    if(nCR > 0) {rData.Description += csPrefix + sTFactor  + _T("CR"); csPrefix = csPrefix_Tmp;}
                                                                    if(nSH > 0) {rData.Description += csPrefix + sTFactor  + _T("SH"); csPrefix = csPrefix_Tmp;}
                                                                    if(nStrType != 4)
                                                                    {
                                                                        if(nSTL> 0) {rData.Description += csPrefix + sStlFactor + _T("STL"); csPrefix = csPrefix_Tmp;}
                                                                        if(m_nSmCount > 0) {rData.Description += csPrefix + sStlFactor + _T("SM[") + strFixSm + _T("]"); csPrefix = csPrefix_Tmp;}              
                                                                    }
                                                                    if(m_nConstLoad!=0)
                                                                    {
                                                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                                        {rData.Description += csPrefix + sDcFac[nDc] + _T("(cD)"); csPrefix = csPrefix_Tmp;}

                                                                        CString strcEL;
                                                                        int nErection = 0;

                                                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                                        {
                                                                            strcEL = _T(""); nErection = 0;
                                                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                                                            if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")))
                                                                            {rData.Description += csPrefix + sDcFac[nDc] + strcEL; csPrefix = csPrefix_Tmp;}
                                                                            else if(CheckCSEL(nErection, _T("DW")))
                                                                            {rData.Description += csPrefix + sDwFac[nDw] + strcEL; csPrefix = csPrefix_Tmp;}
                                                                            else if((nStrType == 1 || nStrType == 2 || nStrType == 5) && CheckCSEL(nErection, _T("L")))
                                                                            {rData.Description += csPrefix + sLFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                                            else if((nStrType == 3 || nStrType == 5) && CheckCSEL(nErection, _T("W")))
                                                                            {rData.Description += csPrefix + sWFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                                            else if(CheckCSEL(nErection, _T("T")))
                                                                            {rData.Description += csPrefix + sTFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                                            else if(nStrType != 4 && CheckCSEL(nErection, _T("STL")))
                                                                            {rData.Description += csPrefix + sStlFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                                        }
                                                                        if (m_nAshLr08Deform == 0) // Deform Check
                                                                        {
                                                                            if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                                                            {rData.Description += csPrefix + sPSSFactor + _T("(cTP)"); csPrefix = csPrefix_Tmp;}
                                                                            if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                                                            {rData.Description += csPrefix + sTFactor + _T("(cCR)"); csPrefix = csPrefix_Tmp;}
                                                                            if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                                                            {rData.Description += csPrefix + sTFactor + _T("(cSH)"); csPrefix = csPrefix_Tmp;}
                                                                        }
                                                                        else // All other
                                                                        {
                                                                            if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                                            {rData.Description += csPrefix + sPSSFactor + _T("(cTS)"); csPrefix = csPrefix_Tmp;}
                                                                            if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                                            {rData.Description += csPrefix + sTFactor + _T("(cCR)"); csPrefix = csPrefix_Tmp;}
                                                                            if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                                            {rData.Description += csPrefix + sTFactor + _T("(cSH)"); csPrefix = csPrefix_Tmp;}
                                                                        }
                                                                    }
                                                                    if(LoadCaseNo > 0)
                                                                    {
                                                                        if(m_nLcomType == D_LCOMTYPE_STLCOMP)
                                                                        {
                                                                            rData.nActive = 1;
                                                                            rData.nSubLcomType = 0;
                                                                        }

                                                                        Set_LoadComb4Civil(rData, D_STR);
                                                                    }
                                                                }}}}}}
                                        }}}}}}}}}}
}

void CLoadCombCtrl::Set_CvlAashtoLrfd08Etr_M(ArINT& arDcLoad, ArINT& arDdLoad, ArINT& arDwLoad, ArINT& arEhLoad, 
                                             ArINT& arEvLoad, ArINT& arEsLoad, ArINT& arElLoad, ArUNT& arMLoad, ArINT& arLLoad, ArINT& arIlLoad, 
                                             ArINT& arCfLoad, ArINT& arBrkLoad,ArINT& arCrlLoad, ArINT& arLsLoad, ArINT& arWpLoad, ArINT& arFpLoad,
                                             ArINT& arBLoad,  ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arFrLoad, ArINT& arELoad, ArUNT& arEspLoad,
                                             ArINT& arIpLoad, ArINT& arCtLoad, ArINT& arCvLoad, ArINT& arCrLoad, ArINT& arShLoad, ArINT& arPsLoad, int nEtrType)
{
    // return condition  
    if     (nEtrType == 11 && m_nECount  == 0) return;
    else if(nEtrType == 12 && m_nEspCount== 0) return;
    else if(nEtrType == 21 && m_nIpCount == 0) return;
    else if(nEtrType == 22 && m_nCtCount == 0) return;
    else if(nEtrType == 23 && m_nCvCount == 0) return;

    // Load Factor
    double dModifier = m_dAshLr08Modifier;
    double dLFactor = 0.5 * dModifier,  dCfFactor = 0.5 * dModifier;
    double dWpFactor = 1.0 * dModifier, dFrFactor = 1.0 * dModifier, dEFactor = 1.0 * dModifier; 
    CString strTitle;
    if (nEtrType == 11 || nEtrType == 12) strTitle = _T("Extreme-I:");
    else strTitle = _T("Extreme-II:");
    if(m_bAshLr08CulvertChk == TRUE) dLFactor=2.0 * dModifier;  // Metal Box CulvertÀÎ °æ¿ì

    CString sLFactor, sCfFactor, sWpFactor, sFrFactor, sEFactor;
    sLFactor.Format(_T("%.2f"), dLFactor);
    sCfFactor.Format(_T("%.2f"), dCfFactor);
    sWpFactor.Format(_T("%.2f"), dWpFactor);
    sFrFactor.Format(_T("%.2f"), dFrFactor);
    sEFactor.Format(_T("%.2f"), dEFactor);

    CString sDcFac[2], sDdFac[2], sDwFac[2], sEhFac[2], sEvFac[2], sEsFac[2], sElFac[2], sPsFac[2], sCrFac[2], sShFac[2];
    double dDcFac[2], dDdFac[2], dDwFac[2], dEhFac[2], dEvFac[2], dEsFac[2], dElFac[2], dPsFac[2], dCrFac[2], dShFac[2];
    GetAashtoLrfdD08Factor(sDcFac[0], sDcFac[1], sDdFac[0], sDdFac[1], sDwFac[0], sDwFac[1], sEhFac[0], sEhFac[1], 
        sEvFac[0], sEvFac[1], sEsFac[0], sEsFac[1], sElFac[0], sElFac[1], sPsFac[0], sPsFac[1], sCrFac[0], sCrFac[1], 
        sShFac[0], sShFac[1], dDcFac[0], dDcFac[1], dDdFac[0], dDdFac[1], dDwFac[0], dDwFac[1], dEhFac[0], dEhFac[1], 
        dEvFac[0], dEvFac[1], dEsFac[0], dEsFac[1], dElFac[0], dElFac[1], dPsFac[0], dPsFac[1], dCrFac[0], dCrFac[1], 
        dShFac[0], dShFac[1], 1);  

    int nAshLr08DcNum = m_nAshLr08DcNum;     
    int nAshLr08DdNum = m_nAshLr08DdNum;     // DDÀÇ °³¼ö´Â º¯ÇÔ¾øÀ½
    int nAshLr08DwNum = m_nAshLr08DwNum;
    int nAshLr08EhNum = m_nAshLr08EhNum;
    int nAshLr08EvNum = m_nAshLr08EvNum;
    int nAshLr08EsNum = m_nAshLr08EsNum;  
    int nAshLr08ElNum = m_nAshLr08ElNum;  


    int nECountTemp = 1;
    int nBrkCountTemp = max(m_nBrkCount, 1);
    if     (nEtrType == 11) nECountTemp = (m_nECount>0)   ? m_nECount*2   : 1;
    else if(nEtrType == 12) nECountTemp = (m_nEspCount>0) ? m_nEspCount*2 : 1;
    double dScaleUpFactor=1.0;

    int LoadCaseNo;
    T_LCOM_D rData;

    for(int nDc = 0; nDc < nAshLr08DcNum; nDc++) {
        for(int nDd = 0; nDd < nAshLr08DdNum; nDd++) {
            for(int nDw = 0; nDw < nAshLr08DwNum; nDw++) {
                for(int nEh = 0; nEh < nAshLr08EhNum; nEh++) {
                    for(int nEv = 0; nEv < nAshLr08EvNum; nEv++) {
                        for(int nEs = 0; nEs < nAshLr08EsNum; nEs++) {
                            for(int nEl = 0; nEl < nAshLr08ElNum; nEl++) 
                            {
                                int nMCount = max(m_nMCount, 1);
                                for(int l = 0; l < nMCount; l++) {
                                    for(int j = 0; j < nECountTemp; j++){
                                        for(int o = 0; o < nBrkCountTemp; o++)
                                        {
                                            CString strFixM, strFixBrk, strFixE = _T(""), csPrefix = _T(""), csPrefix_Tmp = _T("");  
                                            strFixM.Format(_T("%d"), l+1);
                                            strFixE.Format(_T("%d"), j/2+1);
                                            strFixBrk.Format(_T("%d"), o+1);
                                            rData.Initialize();  
                                            LoadCaseNo = 0;
                                            int i=0, nDCL=0, nDDL=0, nDWL=0, nEHL=0, nEVL=0, nESL=0, nELL=0, nLL=0, nIL=0, nCF=0, nBRK=0, nCRL=0, nLS=0;
                                            int nWP=0, nFP=0, nBL=0, nSF=0, nWPR=0, nFR=0, nEL=0, nIP=0, nCT=0, nCV=0, n=0, nPS=0, nCR=0, nSH=0;
                                            for(i=0; i<m_nDcCount; i++)  nDCL+= Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc], LoadCaseNo, rData, D_SGLD_DL_CVL);
                                            for(i=0; i<m_nDdCount; i++)  nDDL+= Set_STLCIncludeCS(arDdLoad.GetAt(i),  dDdFac[nDd], LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nDwCount; i++)  nDWL+= Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw], LoadCaseNo, rData, D_SGLD_DL_CVL);
                                            for(i=0; i<m_nEhCount; i++)  nEHL+= Set_STLCIncludeCS(arEhLoad.GetAt(i),  dEhFac[nEh], LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEvCount; i++)  nEVL+= Set_STLCIncludeCS(arEvLoad.GetAt(i),  dEvFac[nEv], LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEsCount; i++)  nESL+= Set_STLCIncludeCS(arEsLoad.GetAt(i),  dEsFac[nEs], LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nElCount; i++)  nELL+= Set_STLCIncludeCS(arElLoad.GetAt(i),  dElFac[nEl], LoadCaseNo, rData, 0);
                                            if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dLFactor, LoadCaseNo, rData, TRUE);  
                                            if(m_nLCount > 0)  
                                            {
                                                for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dLFactor, LoadCaseNo, rData, 0);        
                                                for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dLFactor, LoadCaseNo, rData, 0);
                                            }
                                            if(m_nMCount>0 || m_nLCount>0)
                                            {
                                                for(i=0; i<m_nCfCount; i++)  nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i),  dCfFactor,  LoadCaseNo, rData, 0);
                                                if(m_nBrkCount > 0) nBRK+= Set_STLCIncludeCS(arBrkLoad.GetAt(o),dCfFactor,  LoadCaseNo, rData, 0);
                                            }
                                            for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCfFactor,  LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nLsCount; i++)  nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i),  dCfFactor,  LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nWpCount; i++)  nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nFpCount; i++)  nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),   dWpFactor,  LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nSfCount; i++)  nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nWprCount; i++) nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i), dWpFactor,  LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nFrCount; i++)  nFR += Set_STLCIncludeCS(arFrLoad.GetAt(i),  dFrFactor,  LoadCaseNo, rData, 0);
                                            double dEF = (j%2==0) ? dEFactor : -1.*dEFactor;
                                            if     (nEtrType==11)        nEL += Set_STLCIncludeCS(arELoad.GetAt(j/2),   dEF,   LoadCaseNo, rData, 0);
                                            else if(nEtrType==12)
                                            {
                                                Get_ScaleUpFactor(D_LOADCASE_SPECTRUM, arEspLoad.GetAt(j/2), dScaleUpFactor);
                                                Set_SpectrumCase(arEspLoad.GetAt(j/2), dEF*dScaleUpFactor, LoadCaseNo, rData, TRUE);
                                            }
                                            else if(nEtrType==21)
                                            {
                                                for(i=0; i<m_nIpCount; i++) nIP += Set_STLCIncludeCS(arIpLoad.GetAt(i),  dEFactor,  LoadCaseNo, rData, 0);
                                            }
                                            else if(nEtrType == 22)
                                            {
                                                for(i=0; i<m_nCtCount; i++) nCT += Set_STLCIncludeCS(arCtLoad.GetAt(i),  dEFactor,  LoadCaseNo, rData, 0);
                                            }
                                            else if(nEtrType == 23)
                                            {
                                                for(i=0; i<m_nCvCount; i++) nCV += Set_STLCIncludeCS(arCvLoad.GetAt(i),  dEFactor,  LoadCaseNo, rData, 0);
                                            }
                                            if(m_nConstLoad!=0)
                                            {
                                                int n=0;
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, n)) Set_CStageCase(m_aCSLoad.GetAt(n), dDcFac[nDc], LoadCaseNo, rData, TRUE);

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")))
                                                        Set_CStageCase(m_aCSLoad.GetAt(n), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                    else if(CheckCSEL(nErection, _T("DW")))
                                                        Set_CStageCase(m_aCSLoad.GetAt(n), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                    else if(CheckCSEL(nErection, _T("L")))
                                                        Set_CStageCase(m_aCSLoad.GetAt(n), dLFactor, LoadCaseNo, rData, TRUE);
                                                    else if(CheckCSEL(nErection, _T("E")) && nEtrType==11)
                                                        Set_CStageCase(m_aCSLoad.GetAt(n), dEFactor, LoadCaseNo, rData, TRUE);
                                                }
                                            }

                                            if(m_nLcomType == D_LCOMTYPE_STLCOMP) csPrefix_Tmp = _T(",");
                                            else                                  csPrefix_Tmp = _T("+");

                                            rData.Description = strTitle;  
                                            if(nDCL> 0) {rData.Description += csPrefix + sDcFac[nDc] + _T("DC"); csPrefix = csPrefix_Tmp;}
                                            if(nDDL> 0) {rData.Description += csPrefix + sDdFac[nDd] + _T("DD"); csPrefix = csPrefix_Tmp;}
                                            if(nDWL> 0) {rData.Description += csPrefix + sDwFac[nDw] + _T("DW"); csPrefix = csPrefix_Tmp;}
                                            if(nEHL> 0) {rData.Description += csPrefix + sEhFac[nEh] + _T("EH"); csPrefix = csPrefix_Tmp;}
                                            if(nEVL> 0) {rData.Description += csPrefix + sEvFac[nEv] + _T("EV"); csPrefix = csPrefix_Tmp;}
                                            if(nESL> 0) {rData.Description += csPrefix + sEsFac[nEs] + _T("ES"); csPrefix = csPrefix_Tmp;}
                                            if(nELL> 0) {rData.Description += csPrefix + sElFac[nEl] + _T("EL"); csPrefix = csPrefix_Tmp;}
                                            if(m_nMCount>0) {rData.Description += csPrefix + sLFactor  + _T("M[") + strFixM + _T("]");   csPrefix = csPrefix_Tmp;}  
                                            if(m_nLCount > 0)
                                            {
                                                if(nLL > 0) {rData.Description += csPrefix + sLFactor  + _T("L");   csPrefix = csPrefix_Tmp;}  
                                                if(nIL > 0) {rData.Description += csPrefix + sLFactor  + _T("IL");  csPrefix = csPrefix_Tmp;}  
                                            } 
                                            if(m_nMCount>0 || m_nLCount>0)
                                            {
                                                if(nCF > 0) {rData.Description += csPrefix + sCfFactor + _T("CF");  csPrefix = csPrefix_Tmp;}     
                                                if(nBRK> 0) {rData.Description += csPrefix + sCfFactor + _T("BRK[") + strFixBrk + _T("]"); csPrefix = csPrefix_Tmp;}
                                            }
                                            if(nCRL> 0) {rData.Description += csPrefix + sCfFactor + _T("CRL"); csPrefix = csPrefix_Tmp;}     
                                            if(nLS > 0) {rData.Description += csPrefix + sCfFactor + _T("LS");  csPrefix = csPrefix_Tmp;}     
                                            if(nWP > 0) {rData.Description += csPrefix + sWpFactor + _T("WP");  csPrefix = csPrefix_Tmp;} 
                                            if(nFP > 0) {rData.Description += csPrefix + sWpFactor + _T("FP");  csPrefix = csPrefix_Tmp;} 
                                            if(nBL > 0) {rData.Description += csPrefix + sWpFactor + _T("B");   csPrefix = csPrefix_Tmp;} 
                                            if(nSF > 0) {rData.Description += csPrefix + sWpFactor + _T("SF");  csPrefix = csPrefix_Tmp;} 
                                            if(nWPR> 0) {rData.Description += csPrefix + sWpFactor + _T("WPR"); csPrefix = csPrefix_Tmp;}
                                            if(nFR > 0) {rData.Description += csPrefix + sFrFactor + _T("FR"); csPrefix = csPrefix_Tmp;}
                                            if(nEtrType==11 && nEL>0)
                                            {
                                                if(dEF<0.) csPrefix=_T("");
                                                rData.Description += csPrefix + GetFactorString(dEF) + _T("E[") + strFixE + _T("]"); csPrefix = csPrefix_Tmp;
                                            }
                                            else if(nEtrType==12)
                                            {
                                                if(dEF<0.) csPrefix=_T("");
                                                rData.Description += csPrefix + GetFactorString(dEF*dScaleUpFactor) + _T("ESP[") + strFixE + _T("]"); csPrefix = csPrefix_Tmp;
                                            }

                                            else if(nEtrType==21 && nIP>0) {rData.Description += csPrefix + sEFactor + _T("IP"); csPrefix = csPrefix_Tmp;}
                                            else if(nEtrType==22 && nCT>0) {rData.Description += csPrefix + sEFactor + _T("CT"); csPrefix = csPrefix_Tmp;}
                                            else if(nEtrType==23 && nCV>0) {rData.Description += csPrefix + sEFactor + _T("CV"); csPrefix = csPrefix_Tmp;}
                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                                                {rData.Description += csPrefix + sDcFac[nDc] + _T("(cD)"); csPrefix = csPrefix_Tmp;}

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")))
                                                    {rData.Description += csPrefix + sDcFac[nDc] + strcEL; csPrefix = csPrefix_Tmp;}
                                                    else if(CheckCSEL(nErection, _T("DW")))
                                                    {rData.Description += csPrefix + sDwFac[nDw] + strcEL; csPrefix = csPrefix_Tmp;}
                                                    else if(CheckCSEL(nErection, _T("L")))
                                                    {rData.Description += csPrefix + sLFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                    else if(CheckCSEL(nErection, _T("E")) && nEtrType==11)
                                                    {rData.Description += csPrefix + sEFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                                }
                                            }

                                            if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);
                                        }}}
                            }}}}}}}
}

void CLoadCombCtrl::Set_CvlAashtoLrfd08Ser_M(ArINT& arDcLoad, ArINT& arDdLoad, ArINT& arDwLoad, ArINT& arEhLoad, 
                                             ArINT& arEvLoad, ArINT& arEsLoad, ArINT& arElLoad, ArUNT& arMLoad, ArINT& arLLoad, ArINT& arIlLoad,
                                             ArINT& arCfLoad, ArINT& arBrkLoad, ArINT& arCrlLoad, ArINT& arLsLoad, ArINT& arWpLoad, ArINT& arFpLoad,
                                             ArINT& arBLoad,  ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arWLoad, ArINT& arWlLoad, ArINT& arFrLoad,
                                             ArINT& arTLoad,  ArINT& arCrLoad, ArINT& arShLoad, ArINT& arPsLoad, ArINT& arTpgLoad, ArINT& arStlLoad, ArUNT& arSmLoad,
                                             ArINT& arCSLoad, int nSerType)
{
    // return condition
    //if(nSerType == 1 && m_nWCount == 0) return; // => ÇÏÁß°è¼ö°¡ II, III°ú ´Ù¸£¹Ç·Î ¸·´Â°Å´Â ÀÇ¹Ì°¡ ¾ø½¿.
    if(nSerType == 2 && m_nDcCount==0 && m_nDdCount==0 && m_nDwCount==0 && m_nEhCount==0 && m_nEvCount==0 && 
        m_nEsCount==0 && m_nLCount==0 && m_nMCount==0 && m_nCrlCount==0 && m_nElCount==0 && m_nWpCount==0 &&
        m_nFpCount==0 && m_nBCount==0 &&  m_nSfCount==0 && m_nWprCount==0 && m_nFrCount==0 && m_nTCount==0 &&
        m_nCrCount==0 && m_nShCount==0 && m_nPsCount==0 && m_nConstLoad==0) return;
    //if(nSerType == 3 && m_nTpgCount == 0 && m_nStlCount == 0 && m_nSmCount == 0) return; // => ÇÏÁß°è¼ö°¡ I, II¿Í ´Ù¸£¹Ç·Î ¸·´Â°Å´Â ÀÇ¹Ì°¡ ¾ø½¿.
    // Load Factor
    double dModifier = m_dAshLr08Modifier;
    double dDFactor =1.0*dModifier, dLFactor = 0., dCfFactor = 0., dWFactor = 0.;
    double dWpFactor=1.0*dModifier, dWlFactor=1.0*dModifier, dFrFactor=1.0*dModifier;  
    double dTFactor=1.2*dModifier;
    double dStlFactor = m_dAshLr08Stl * dModifier;
    double dPSS = (m_bLossFactor ? m_dLossFactorService : 1.0);

    double dTpgFactor;
    if (m_nMCount>0 || m_nLCount>0) dTpgFactor=0.5*dModifier; // Live Load or MVL ÇÏ³ª¶óµµ ÀÖÀ¸¸é 0.5
    else                            dTpgFactor=1.0*dModifier; // Live Load or MVL ÇÑ°³µµ ¾øÀ¸¸é 1.0

    CString strTitle;
    if     (nSerType == 1) {dLFactor = dCfFactor = 1.0 * dModifier; dWFactor = 0.3 * dModifier; strTitle = _T("Service-I:");}
    else if(nSerType == 2) {dLFactor = dCfFactor = 1.3 * dModifier; strTitle = _T("Service-II:");}
    else if(nSerType == 3) {dLFactor = dCfFactor = 0.8 * dModifier; strTitle = _T("Service-III:");}
    else if(nSerType == 4) {dWFactor = 0.7 * dModifier; strTitle = _T("Service-IV:");}

    if(m_bAshLr08CulvertChk == TRUE) dLFactor = 2.0 * dModifier;  // Metal Box CulvertÀÎ °æ¿ì
    if(m_nAshLr08Deform == 1)        dTFactor = 1.0 * dModifier;  // deformation checkÀÎ °æ¿ì  

    CString sDFactor, sLFactor, sCfFactor, sWpFactor, sWFactor, sWlFactor, sFrFactor, sTFactor, sTpgFactor, sStlFactor;
    sDFactor.Format(_T("%.2f"), dDFactor);
    sLFactor.Format(_T("%.2f"), dLFactor);
    sCfFactor.Format(_T("%.2f"), dCfFactor);
    sWpFactor.Format(_T("%.2f"), dWpFactor);
    sWFactor.Format(_T("%.2f"), dWFactor);
    sWlFactor.Format(_T("%.2f"), dWlFactor);
    sFrFactor.Format(_T("%.2f"), dFrFactor);
    sTFactor.Format(_T("%.2f"), dTFactor);
    sTpgFactor.Format(_T("%.2f"), dTpgFactor);
    sStlFactor.Format(_T("%.2f"), dStlFactor);

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nWLCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1;
    int nSmCountTemp = max(m_nSmCount, 1);
    int nTCountTemp = max(m_nTCount, 1);
    int nTpgCountTemp = max(m_nTpgCount, 1);
    int nBrkCountTemp = max(m_nBrkCount, 1);
    int nMCount = max(m_nMCount, 1);

    int LoadCaseNo;
    T_LCOM_D rData;

    for(int l = 0; l < nMCount; l++) {
        for(int j = 0; j < nWCountTemp; j++) {
            for(int o = 0; o < nWLCountTemp; o++) {
                for(int k = 0; k < nSmCountTemp; k++) {
                    for(int n = 0; n < nTCountTemp; n++) {
                        for(int m = 0; m < nTpgCountTemp; m++){
                            for(int p = 0; p < nBrkCountTemp; p++)
                            {
                                CString strFixM, strFixW, strFixWL, strFixSm, strFixT, strFixTpg, strFixBrk, csPrefix = _T(""), csPrefix_Tmp = _T("");  
                                strFixM.Format(_T("%d"), l+1);
                                strFixW.Format(_T("%d"), j/2+1);
                                strFixWL.Format(_T("%d"), o/2+1);
                                strFixSm.Format(_T("%d"), k+1);     
                                strFixT.Format(_T("%d"), n+1);
                                strFixTpg.Format(_T("%d"), m+1);
                                strFixBrk.Format(_T("%d"), p+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;
                                int i=0, nDC=0, nDD=0, nDW=0, nEH=0, nEV=0, nES=0, nEL=0, nLL=0, nIL=0, nCF=0, nBRK=0, nCRL=0, nLS=0, nWP=0, nFP=0;
                                int nBL=0, nSF=0, nWPR=0, nWL=0, nWLL=0, nFR=0, nTL=0, nCR=0, nSH=0, nPS=0, nTPG=0, nSTL=0, nn=0;
                                for(i=0; i<m_nDcCount; i++)  nDC += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDFactor, LoadCaseNo, rData, D_SGLD_DL_CVL);
                                for(i=0; i<m_nDdCount; i++)  nDD += Set_STLCIncludeCS(arDdLoad.GetAt(i),  dDFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nDwCount; i++)  nDW += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDFactor, LoadCaseNo, rData, D_SGLD_DL_CVL);
                                for(i=0; i<m_nEhCount; i++)  nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i),  dDFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEvCount; i++)  nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i),  dDFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEsCount; i++)  nES += Set_STLCIncludeCS(arEsLoad.GetAt(i),  dDFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nElCount; i++)  nEL += Set_STLCIncludeCS(arElLoad.GetAt(i),  dDFactor, LoadCaseNo, rData, 0);
                                if(nSerType == 1 || nSerType == 2 || nSerType == 3)
                                {
                                    if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l),   dLFactor, LoadCaseNo, rData, TRUE);        
                                    if(m_nLCount > 0)  
                                    {
                                        for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),   dLFactor,   LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i),  dLFactor,   LoadCaseNo, rData, 0);
                                    } 
                                    if(m_nMCount>0 || m_nLCount>0)
                                    {
                                        for(i=0; i<m_nCfCount; i++)  nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i),  dCfFactor,  LoadCaseNo, rData, 0);
                                        if(m_nBrkCount > p) nBRK+= Set_STLCIncludeCS(arBrkLoad.GetAt(p),dCfFactor,  LoadCaseNo, rData, 0);
                                    }

                                    for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCfFactor,  LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nLsCount; i++)  nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i),  dCfFactor,  LoadCaseNo, rData, 0);
                                }
                                for(i=0; i<m_nWpCount; i++)  nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                for(i=0; i<m_nFpCount; i++)  nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),   dWpFactor,  LoadCaseNo, rData, 0);
                                for(i=0; i<m_nSfCount; i++)  nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i),  dWpFactor,  LoadCaseNo, rData, 0);
                                for(i=0; i<m_nWprCount; i++) nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i), dWpFactor,  LoadCaseNo, rData, 0);
                                double dWF = (j%2==0) ? dWFactor : -1.*dWFactor;
                                double dWLF = (o%2==0) ? dWlFactor : -1.*dWlFactor;
                                if(nSerType == 1)             
                                {
                                    if(m_nWCount > 0)           nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF,        LoadCaseNo, rData, 0);          
                                    if(m_nWlCount > 0)          nWLL += Set_STLCIncludeCS(arWlLoad.GetAt(o/2), dWLF,        LoadCaseNo, rData, 0);
                                    //for(i=0; i<m_nWlCount; i++) nWLL+= Set_STLCIncludeCS(arWlLoad.GetAt(i),  dWlFactor,  LoadCaseNo, rData, 0);
                                }
                                for(i=0; i<m_nFrCount; i++)   nFR += Set_STLCIncludeCS(arFrLoad.GetAt(i),  dFrFactor,  LoadCaseNo, rData, 0);
                                if(m_nTCount > 0)             nTL += Set_STLCIncludeCS(arTLoad.GetAt(n),   dTFactor,   LoadCaseNo, rData, 0);
                                for(i=0; i<m_nCrCount; i++)   nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i),  dTFactor,   LoadCaseNo, rData, D_SGLD_CS_CVL);
                                for(i=0; i<m_nShCount; i++)   nSH += Set_STLCIncludeCS(arShLoad.GetAt(i),  dTFactor,   LoadCaseNo, rData, D_SGLD_SS_CVL);

                                if(nSerType == 1 || nSerType == 3)
                                {
                                    if(m_nTpgCount > 0)         nTPG+= Set_STLCIncludeCS(arTpgLoad.GetAt(m), dTpgFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nStlCount; i++)nSTL= Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                    if(m_nSmCount > 0)          Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                }
                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFactor, LoadCaseNo, rData, TRUE);

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                        if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFactor, LoadCaseNo, rData, TRUE);
                                        else if(CheckCSEL(nErection, _T("L")))
                                            if(nSerType == 1 || nSerType == 2 || nSerType == 3)
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dLFactor, LoadCaseNo, rData, TRUE);
                                            }
                                            else if(nSerType == 1 && CheckCSEL(nErection, _T("W")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dWFactor, LoadCaseNo, rData, TRUE);
                                            else if(CheckCSEL(nErection, _T("T")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                            else if((nSerType == 1 || nSerType == 3) && CheckCSEL(nErection, _T("TPG")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dTpgFactor, LoadCaseNo, rData, TRUE);
                                            else if((nSerType == 1 || nSerType == 3) && CheckCSEL(nErection, _T("STL")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dStlFactor, LoadCaseNo, rData, TRUE);
                                    }
                                    // MQC:2246-JHYUN-20081105
                                    if (m_nAshLr08Deform == 0) // Deform Check
                                    {
                                        if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                        if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                    }
                                    else // All other
                                    {
                                        if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        //         if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                        //           Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        //         if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                        //           Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                    }
                                    //       if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    //         Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                    //       if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    //         Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                    //       if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    //         Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                    //       if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    //         Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                    //       if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                    //         Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                    //       if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                    //         Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                }

                                if(m_nLcomType == D_LCOMTYPE_STLCOMP) csPrefix_Tmp = _T(",");
                                else                                  csPrefix_Tmp = _T("+");    

                                rData.Description = strTitle;  
                                if(nDC > 0) {rData.Description += csPrefix + sDFactor + _T("DC"); csPrefix = csPrefix_Tmp;}
                                if(nDD > 0) {rData.Description += csPrefix + sDFactor + _T("DD"); csPrefix = csPrefix_Tmp;}
                                if(nDW > 0) {rData.Description += csPrefix + sDFactor + _T("DW"); csPrefix = csPrefix_Tmp;}
                                if(nEH > 0) {rData.Description += csPrefix + sDFactor + _T("EH"); csPrefix = csPrefix_Tmp;}
                                if(nEV > 0) {rData.Description += csPrefix + sDFactor + _T("EV"); csPrefix = csPrefix_Tmp;}
                                if(nES > 0) {rData.Description += csPrefix + sDFactor + _T("ES"); csPrefix = csPrefix_Tmp;}
                                if(nEL > 0) {rData.Description += csPrefix + sDFactor + _T("EL"); csPrefix = csPrefix_Tmp;}
                                if(nSerType == 1 || nSerType == 2 || nSerType == 3)
                                {
                                    if(m_nMCount>0) {rData.Description += csPrefix + sLFactor  + _T("M[") + strFixM + _T("]"); csPrefix = csPrefix_Tmp;}              
                                    if(m_nLCount> 0)
                                    {
                                        if(nLL > 0) {rData.Description += csPrefix + sLFactor  + _T("L");   csPrefix = csPrefix_Tmp;}  
                                        if(nIL > 0) {rData.Description += csPrefix + sLFactor  + _T("IL");  csPrefix = csPrefix_Tmp;}  
                                    }
                                    if(m_nMCount>0 || m_nLCount>0)
                                    {
                                        if(nCF > 0) {rData.Description += csPrefix + sCfFactor + _T("CF");  csPrefix = csPrefix_Tmp;}
                                        if(nBRK> 0) {rData.Description += csPrefix + sCfFactor + _T("BRK[") + strFixBrk + _T("]"); csPrefix = csPrefix_Tmp;}
                                    }
                                }
                                if(nCRL> 0) {rData.Description += csPrefix + sCfFactor + _T("CRL"); csPrefix = csPrefix_Tmp;}     
                                if(nLS > 0) {rData.Description += csPrefix + sCfFactor + _T("LS");  csPrefix = csPrefix_Tmp;}     
                                if(nWP > 0) {rData.Description += csPrefix + sWpFactor + _T("WP");  csPrefix = csPrefix_Tmp;} 
                                if(nFP > 0) {rData.Description += csPrefix + sWpFactor + _T("FP");  csPrefix = csPrefix_Tmp;} 
                                if(nBL > 0) {rData.Description += csPrefix + sWpFactor + _T("B");   csPrefix = csPrefix_Tmp;} 
                                if(nSF > 0) {rData.Description += csPrefix + sWpFactor + _T("SF");  csPrefix = csPrefix_Tmp;} 
                                if(nWPR> 0) {rData.Description += csPrefix + sWpFactor + _T("WPR"); csPrefix = csPrefix_Tmp;}
                                if(nSerType == 1)
                                {
                                    if(nWL > 0) {if(dWF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = csPrefix_Tmp;}
                                    if(nWLL > 0) {if(dWLF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWLF) + _T("WL[") + strFixWL + _T("]"); csPrefix = csPrefix_Tmp;}
                                    //if(nWLL> 0) {rData.Description += csPrefix + sWlFactor + _T("WL"); csPrefix = csPrefix_Tmp;}
                                }
                                if(nFR > 0) {rData.Description += csPrefix + sFrFactor + _T("FR"); csPrefix = csPrefix_Tmp;}
                                if(nTL > 0) {rData.Description += csPrefix + sTFactor  + _T("T[") + strFixT + _T("]");  csPrefix = csPrefix_Tmp;}
                                if(nCR > 0) {rData.Description += csPrefix + sTFactor  + _T("CR"); csPrefix = csPrefix_Tmp;}
                                if(nSH > 0) {rData.Description += csPrefix + sTFactor  + _T("SH"); csPrefix = csPrefix_Tmp;}
                                if(nSerType == 1 || nSerType == 3)
                                {
                                    if(nTPG > 0){rData.Description += csPrefix + sTpgFactor+ _T("TPG[") + strFixTpg + _T("]");  csPrefix = csPrefix_Tmp;}
                                    if(nSTL> 0) {rData.Description += csPrefix + sStlFactor + _T("STL"); csPrefix = csPrefix_Tmp;}
                                    if(m_nSmCount > 0) {rData.Description += csPrefix + sStlFactor + _T("SM[") + strFixSm + _T("]"); csPrefix = csPrefix_Tmp;}              
                                }
                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + sDFactor + _T("(cD)"); csPrefix = csPrefix_Tmp;}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                        if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + sDFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                        else if(CheckCSEL(nErection, _T("L")))
                                        {
                                            if(nSerType == 1 || nSerType == 2 || nSerType == 3)
                                            {
                                                rData.Description += csPrefix + sLFactor + strcEL; csPrefix = csPrefix_Tmp;
                                            }
                                        }
                                        else if(nSerType == 1 && CheckCSEL(nErection, _T("W")))
                                        {rData.Description += csPrefix + sWFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                        else if(CheckCSEL(nErection, _T("T")))
                                        {rData.Description += csPrefix + sTFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                        else if((nSerType == 1 || nSerType == 3) && CheckCSEL(nErection, _T("TPG")))
                                        {rData.Description += csPrefix + sTpgFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                        else if((nSerType == 1 || nSerType == 3) && CheckCSEL(nErection, _T("STL")))
                                        {rData.Description += csPrefix + sStlFactor + strcEL; csPrefix = csPrefix_Tmp;}
                                    }
                                    // MQC:2246-JHYUN-20081105
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {rData.Description += csPrefix + sDFactor + _T("(cTS)"); csPrefix = csPrefix_Tmp;}
                                    if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                    {rData.Description += csPrefix + sDFactor + _T("(cCR)"); csPrefix = csPrefix_Tmp;}
                                    if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                    {rData.Description += csPrefix + sDFactor + _T("(cSH)"); csPrefix = csPrefix_Tmp;}

                                    //       if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    //       {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
                                    //       if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    //       {rData.Description += csPrefix + sTFactor + _T("(cCR)"); csPrefix = _T("+");}
                                    //       if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    //       {rData.Description += csPrefix + sTFactor + _T("(cSH)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)   
                                {
                                    if(m_nLcomType == D_LCOMTYPE_STLCOMP)
                                    {
                                        rData.nActive = 2;
                                        rData.nSubLcomType = 0;
                                    }
                                    else
                                    {
                                        if(m_nLcomType != D_LCOMTYPE_GENERAL) rData.nActive = 2; 
                                    }

                                    Set_LoadComb4Civil(rData, D_SER);
                                }}}}}}}}}

void CLoadCombCtrl::Set_CvlAashtoLrfd08Ftg(ArINT& arLLoad, ArINT& arIlLoad, ArINT& arCfLoad)
{
    // return condition
    if(m_nLCount==0) return;  
    // Load Factor
    double dModifier = m_dAshLr08Modifier;
    double dLFactor = 0.75 * dModifier;
    double dCfFactor = 0.75 * dModifier;

    CString strTitle = _T("Fatigue:");  
    if(m_bAshLr08CulvertChk == TRUE) dLFactor = 2.0 * dModifier;  // Metal Box CulvertÀÎ °æ¿ì  
    CString sLFactor, sCfFactor;
    sLFactor.Format(_T("%.2f"), dLFactor);
    sCfFactor.Format(_T("%.2f"), dCfFactor);

    int LoadCaseNo;
    T_LCOM_D rData;

    CString csPrefix = _T(""), csPrefix_Tmp = _T("");  
    rData.Initialize();  
    LoadCaseNo = 0;
    int i = 0;
    for(i=0; i<m_nLCount; i++)  Set_StaticCase(arLLoad.GetAt(i),   dLFactor,   LoadCaseNo, rData);        
    for(i=0; i<m_nIlCount; i++) Set_StaticCase(arIlLoad.GetAt(i),  dLFactor,   LoadCaseNo, rData); // Impact Load´Â Live Load°¡ ÀÖ´Â °æ¿ì¸¸ Æ÷ÇÔ  
    for(i=0; i<m_nCfCount; i++) Set_StaticCase(arCfLoad.GetAt(i),  dCfFactor,  LoadCaseNo, rData); // Centrifugal Load´Â Live Load°¡ ÀÖ´Â °æ¿ì¸¸ Æ÷ÇÔ    

    if(m_nLcomType == D_LCOMTYPE_STLCOMP) csPrefix_Tmp = _T(",");
    else                                  csPrefix_Tmp = _T("+");    

    rData.Description = strTitle;  
    if(m_nLCount > 0)  {rData.Description += csPrefix + sLFactor  + _T("L");   csPrefix = csPrefix_Tmp;}  
    if(m_nIlCount > 0) {rData.Description += csPrefix + sLFactor  + _T("IL");  csPrefix = csPrefix_Tmp;}  
    if(m_nCfCount > 0) {rData.Description += csPrefix + sCfFactor + _T("CF");  csPrefix = csPrefix_Tmp;}     
    if(LoadCaseNo > 0)   
    {
        if(m_nLcomType == D_LCOMTYPE_STLCOMP)
        {
            rData.nActive = 2;
            rData.nSubLcomType = 1;
        }
        else
        {
            if(m_nLcomType != D_LCOMTYPE_GENERAL) rData.nActive = 2; 
        }

        Set_LoadComb4Civil(rData, D_SER);
    }
}

void CLoadCombCtrl::Set_CvlAashtoLrfd08Ftg_M(ArUNT& arMLoad, ArINT& arLLoad, ArINT& arIlLoad, ArINT& arCfLoad)
{
    // return condition
    if(m_nLCount==0 && m_nMCount==0) return;  
    // Load Factor
    double dModifier = m_dAshLr08Modifier;
    double dLFactor = 0.75 * dModifier;
    double dCfFactor = 0.75 * dModifier;

    CString strTitle = _T("Fatigue:");  
    if(m_bAshLr08CulvertChk == TRUE) dLFactor = 2.0 * dModifier;  // Metal Box CulvertÀÎ °æ¿ì  
    CString sLFactor, sCfFactor;
    sLFactor.Format(_T("%.2f"), dLFactor);
    sCfFactor.Format(_T("%.2f"), dCfFactor);

    int LoadCaseNo;
    T_LCOM_D rData;

    int nMCount = max(m_nMCount, 1);
    for(int l=0; l<nMCount; l++)
    {

        CString strFixM, csPrefix = _T(""), csPrefix_Tmp = _T("");  
        strFixM.Format(_T("%d"), l+1);
        rData.Initialize();  
        LoadCaseNo = 0;    
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l),   dLFactor,   LoadCaseNo, rData, TRUE);
        int i=0;
        if(m_nLCount>0)
        {
            for(i=0; i<m_nLCount; i++)  Set_StaticCase(arLLoad.GetAt(i),   dLFactor,   LoadCaseNo, rData);
            for(i=0; i<m_nIlCount; i++) Set_StaticCase(arIlLoad.GetAt(i),  dLFactor,   LoadCaseNo, rData);
        }
        for(i=0; i<m_nCfCount; i++) Set_StaticCase(arCfLoad.GetAt(i),  dCfFactor,  LoadCaseNo, rData);

        if(m_nLcomType == D_LCOMTYPE_STLCOMP) csPrefix_Tmp = _T(",");
        else                                  csPrefix_Tmp = _T("+");    

        rData.Description = strTitle;  
        if(m_nMCount > 0) {rData.Description += csPrefix + sLFactor  + _T("M[") + strFixM + _T("]");   csPrefix = csPrefix_Tmp;}      
        if(m_nLCount > 0)
        {
            {rData.Description += csPrefix + sLFactor  + _T("L");   csPrefix = csPrefix_Tmp;}  
            if(m_nIlCount > 0) {rData.Description += csPrefix + sLFactor  + _T("IL");  csPrefix = csPrefix_Tmp;}  
        }
        if(m_nCfCount > 0) {rData.Description += csPrefix + sCfFactor + _T("CF");  csPrefix = csPrefix_Tmp;}     
        if(LoadCaseNo > 0)   
        {
            if(m_nLcomType == D_LCOMTYPE_STLCOMP)
            {
                rData.nActive = 2;
                rData.nSubLcomType = 1;
            }
            else
            {
                if(m_nLcomType != D_LCOMTYPE_GENERAL) rData.nActive = 2; 
            }

            Set_LoadComb4Civil(rData, D_SER);
        }
    }
}

