                                                            int nWP=0, nFP=0, nBL=0, nSF=0, nWPR=0, nWL=0, nWLL=0, nFR=0, nTL=0, nPSL=0, nCRL=0, nSHL=0, nSTL=0, nn=0;
                                                            for(i=0; i<m_nDcCount; i++)   nDCL += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc], LoadCaseNo, rData, D_SGLD_DL_CVL);
