                                                                    //             Set_CStageCase(arCSLoad.GetAt(nn), dPSS, LoadCaseNo, rData, TRUE);
                                                                    //           if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                                                    //             Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                    //           if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                                                    //             Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                                    if(CheckCS_SgldK(D_SGLD_CP_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dCrFac[nCr], LoadCaseNo, rData, TRUE);
                                                                    if(CheckCS_SgldK(D_SGLD_SP_CVL, nn))
                                                                        Set_CStageCase(arCSLoad.GetAt(nn), dShFac[nSh], LoadCaseNo, rData, TRUE);
