        if ( nEhL > 0 ) { rData.Description += csPrefix + GetFactorString(dEpFac[nEp]) + _T("EH"); csPrefix = _T("+"); }
        if ( nEvL > 0 ) { rData.Description += csPrefix + GetFactorString(dEpFac[nEp]) + _T("EV"); csPrefix = _T("+"); }
