        if ( nWlL > 0 ) { if ( dWlF < 0.0 ) csPrefix = _T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+"); }

