                                                            int nLL=0, nLsL=0, nCfL=0, nWL=0, nWlL=0, nIpL=0, nTL=0, nTpgL=0, nFrL=0, nn=0;

                                                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nLIPCount; i++) { nLipL += Set_STLCIncludeCS(arLIPLoad.GetAt(i), dLIPFac[nLip],   LoadCaseNo, rData, 0            ); (nLip==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nPLCount; i++)  { nPlL  += Set_STLCIncludeCS(arPLLoad.GetAt(i),  dPLFac[nPl],     LoadCaseNo, rData, 0            ); (nPl==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nBLCount; i++)  { nBlL  += Set_STLCIncludeCS(arBLLoad.GetAt(i),  dBLFac[nBl],     LoadCaseNo, rData, 0            ); (nBl==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0            ); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nEpCount; i++)  { nEpL  += Set_STLCIncludeCS(arEpLoad.GetAt(i),  dEpFac[nEp],     LoadCaseNo, rData, 0            ); (nEp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nEhCount; i++)  { nEhL  += Set_STLCIncludeCS(arEhLoad.GetAt(i),  dEpFac[nEp],     LoadCaseNo, rData, 0            ); (nEp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nEvCount; i++)  { nDL   += Set_STLCIncludeCS(arEvLoad.GetAt(i),  dDFac[nD],       LoadCaseNo, rData, 0            ); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nEsCount; i++)  { nEsL  += Set_STLCIncludeCS(arEsLoad.GetAt(i),  dEpFac[nEp],     LoadCaseNo, rData, 0            ); (nEp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0            ); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
