                                                            //       nLcomCount++;
                                                            rData.Description = strTitle;

                                                            if(nDL  > 0)  {rData.Description += csPrefix + GetFactorString(dDFac[nD])   + _T("D"); csPrefix = _T("+");}
                                                            if(nLipL> 0)  {rData.Description += csPrefix + GetFactorString(dLIPFac[nLip]) + _T("LIP"); csPrefix = _T("+");}
                                                            if(nPlL > 0)  {rData.Description += csPrefix + GetFactorString(dPLFac[nPl])   + _T("PL");  csPrefix = _T("+");}
