CString CLoadCombCtrl::Get_CvlSP_35_13330_11_Title(int nGroup)
{
    CString strTitle;

    if     (nGroup == 0) strTitle = _T("1st Group.-");
    else if(nGroup == 1) strTitle = _T("1st Group(Fatigue).-");
    else                 strTitle = _T("2nd Group.-");

    return strTitle;
}


