void CLoadCombCtrl::Get_PNS10030_Factor(CString& sD1Fac,  CString& sD2Fac,   CString& sDc1Fac,   CString& sDc2Fac, CString& sDw1Fac,   CString& sDw2Fac,  
                                        CString& sPs1Fac,  CString& sPs2Fac,  CString& sWp1Fac,   CString& sWp2Fac, 
                                        double& dD1,   double& dD2,   double& dDc1,   double& dDc2,   double& dDw1,   double& dDw2,   double& dPs1,   
                                        double& dPs2,  double& dWp1,  double& dWp2,   BOOL b1stGrp)
{
    // b1stGrp = TRUE  : Group 1 ÀÏ¶§ 
    // b1stGrp = FALSE : Group 2 ÀÏ¶§ 

    if(b1stGrp)
    {
        dD1 = m_dPNS10030D[0]; sD1Fac.Format(_T("%.2f"), m_dPNS10030D[0]);
        dD2 = m_dPNS10030D[1]; sD2Fac.Format(_T("%.2f"), m_dPNS10030D[1]);
        dDc1 = m_dPNS10030DC[0]; sDc1Fac.Format(_T("%.2f"), m_dPNS10030DC[0]);
        dDc2 = m_dPNS10030DC[1]; sDc1Fac.Format(_T("%.2f"), m_dPNS10030DC[1]);
        dDw1 = m_dPNS10030DW[0]; sDw1Fac.Format(_T("%.2f"), m_dPNS10030DW[0]);
        dDw2 = m_dPNS10030DW[1]; sDw2Fac.Format(_T("%.2f"), m_dPNS10030DW[1]);
        dPs1 = m_dPNS10030PS[0]; sPs1Fac.Format(_T("%.2f"), m_dPNS10030PS[0]);
        dPs2 = m_dPNS10030PS[1]; sPs2Fac.Format(_T("%.2f"), m_dPNS10030PS[1]);
        dWp1 = m_dPNS10030WP[0]; sWp1Fac.Format(_T("%.2f"), m_dPNS10030WP[0]);
        dWp2 = m_dPNS10030WP[1]; sWp2Fac.Format(_T("%.2f"), m_dPNS10030WP[1]);

    }
    else
    {
        dD1 = 1.0; sD1Fac.Format(_T("%.2f"), 1.0);
        dD2 = 1.0; sD2Fac.Format(_T("%.2f"), 1.0);
        dDc1 = 1.0; sDc1Fac.Format(_T("%.2f"), 1.0);
        dDc2 = 1.0; sDc2Fac.Format(_T("%.2f"), 1.0);
        dDw1 = 1.0; sDw1Fac.Format(_T("%.2f"), 1.0);
        dDw2 = 1.0; sDw2Fac.Format(_T("%.2f"), 1.0);
        dPs1 = 1.0; sPs1Fac.Format(_T("%.2f"), 1.0);
        dPs2 = 1.0; sPs2Fac.Format(_T("%.2f"), 1.0);
        dWp1 = 1.0; sWp1Fac.Format(_T("%.2f"), 1.0);
        dWp2 = 1.0; sWp2Fac.Format(_T("%.2f"), 1.0);

    }

}

BOOL CLoadCombCtrl::IsUsedFunc(unsigned int LcomK, const _LCOM_IN& UnitResD, int nDepth)
{
    int nResSize = UnitResD.arVariableLoadCase.GetSize();
    for(int i = 0; i < nResSize; ++i)
    {
        if(UnitResD.arVariableLoadCase[i].LcomK == LcomK) return TRUE;
    }
    return FALSE;
}

BOOL CLoadCombCtrl::Swap(_LCOM_IN& LoadInD, int i, int j)
{
    _LCOM_UNIT Temp = LoadInD.arVariableLoadCase[i];
    LoadInD.arVariableLoadCase[i] = LoadInD.arVariableLoadCase[j];
    LoadInD.arVariableLoadCase[j] = Temp;

    return TRUE;
}

void CLoadCombCtrl::SetCrticalFactor(_LCOM_IN& arrRestUnit, const _LCOM_FD& FactorInD)
{
    int nLoadCaseSize = arrRestUnit.arVariableLoadCase.GetSize();   //n
    int nFactorSize   = FactorInD.arCrticalF.GetSize();             //k
    for(int i = 0; i < nLoadCaseSize; ++i)		
    {		
        _LCOM_UNIT& LoadCaseInD =  arrRestUnit.arVariableLoadCase[i];
        int nFactorIndex = min(nFactorSize-1, i);
        double dCrticalFactor = FactorInD.arCrticalF[nFactorIndex];

        LoadCaseInD.dFactor = LoadCaseInD.dFactor * dCrticalFactor;
        LoadCaseInD.strLcomName.Format(_T("%.2f*%s"), LoadCaseInD.dFactor, LoadCaseInD.strLcomName);

    }
}


BOOL CLoadCombCtrl::MakeLoadCombination4Var(_LCOM_IN& arrResUnit, int nDepth, _LCOM_IN& LoadInD, const _LCOM_FD& FactorInD, _LCOM_RES& rData)
{
    int nLoadCaseSize = LoadInD.arVariableLoadCase.GetSize(); // n
    int nFactorSize = FactorInD.arCrticalF.GetSize();         // k

    if(nLoadCaseSize < 1) return TRUE;
    if(nFactorSize < 1) return TRUE;

    _LCOM_IN DummyD;

    if(nDepth == nFactorSize - 1)
    {
        arrResUnit.arVariableLoadCase.Copy(LoadInD.arVariableLoadCase);
        SetCrticalFactor(arrResUnit, FactorInD);
        rData.arLcomD.Add(arrResUnit);
    }
    else
    {
        for(int i = nDepth; i < nLoadCaseSize; ++i)
        {	 
            Swap(LoadInD, nDepth, i);
            arrResUnit.arVariableLoadCase.Copy(LoadInD.arVariableLoadCase);

            MakeLoadCombination4Var(arrResUnit, nDepth+1, LoadInD, FactorInD, rData);

            Swap(LoadInD, i, nDepth);
        }

    }

    return TRUE;
}




void CLoadCombCtrl::SetCvl_PNS10030_1_P(CString strCode,
                                        ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad, ArINT& arStlLoad, ArUNT& arSmLoad, 
                                        ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCfLoad, ArINT& arCrlLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)
{ 
    if(m_bPNS10030BaseType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0  && m_nCSCount == 0) return;

    if(m_nMCount  == 0 && m_nCfCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dCfFactor = 0.0, dMFactor = 0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, dEPNNFactor = 0.0,
        dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;


    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");

    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dCrlFactor = 1.0 * 1.3; //Permanent
    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    _LCOM_IN InData;
    _LCOM_FD FData;
    _LCOM_RES ResData;

    _LCOM_UNIT UnitD;
    UnitD.Initialize();

    if(m_nMCount > 0)
    {
        UnitD.LcomK = 1;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("M");
        InData.arVariableLoadCase.Add(UnitD);
    }
    if(m_nCfCount > 0)
    {
        UnitD.LcomK = 2;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("CF");
        InData.arVariableLoadCase.Add(UnitD);
    }

    switch (InData.arVariableLoadCase.GetSize())
    {
    case 1:
        FData.arCrticalF.SetSize(1);
        FData.arCrticalF[0] = 1.0;
        break;
    case 2:
        FData.arCrticalF.SetSize(2);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        break;
    default:
        break;
    }


    _LCOM_IN arrResUnit;
    MakeLoadCombination4Var(arrResUnit, 0, InData, FData, ResData);

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) 
                            {
                                for(int nVL =0; nVL<ResData.arLcomD.GetSize(); nVL++)
                                {
                                    const _LCOM_IN& aUnit = ResData.arLcomD[nVL];

                                    rData.Initialize();  
                                    LoadCaseNo = 0;
                                    CString strFixM, csPrefix, strFixSm = _T("");  
                                    strFixM.Format(_T("%d"), l+1);
                                    strFixSm.Format(_T("%d"), k+1);

                                    _LCOM_BOTH BothD; BothD.Initialize();
                                    int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nErL=0, nCrL=0, nShL=0, nSmL=0;
                                    int nn=0, nLL=0, nCfL=0 ;
                                    int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                    for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                    for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);
                                    if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                                    for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                    for(int j = 0; j < aUnit.arVariableLoadCase.GetSize(); ++j)
                                    {
                                        const _LCOM_UNIT& aa = aUnit.arVariableLoadCase[j];

                                        switch (aa.LcomK)
                                        {
                                        case 1: // MV
                                            {
                                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), aa.dFactor, LoadCaseNo, rData, TRUE);
                                                dMFactor = aa.dFactor;
                                            }
                                            break;
                                        case 2: //CF
                                            {
                                                if(m_nMCount>0 || m_nLCount>0)
                                                {
                                                    for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                    dCfFactor = aa.dFactor;
                                                }
                                            }
                                            break;
                                        default:
                                            break;
                                        }
                                    }

                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }		

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("L")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                            if(CheckCSEL(nErection, _T("DW")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                        }
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                        }
                                    }

                                    rData.Description = strTitle;

                                    if(nDL  > 0)     {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                    if(nDcL > 0)     {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                    if(nDwL > 0)     {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                    if(nPsL > 0)     {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                    if(nWpL > 0)     {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                    if(nEpL>0)       {rData.Description +=csPrefix + GetFactorString(dEpFactor)      + _T("EP"); csPrefix = _T("+");}
                                    if(nStlL>0)      {rData.Description +=csPrefix + GetFactorString(dStlFactor)     + _T("STL"); csPrefix = _T("+");}
                                    if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}      
                                    if(nCrlL > 0)    {rData.Description += csPrefix + GetFactorString(dCrlFactor)    + _T("CRL"); csPrefix = _T("+");}

                                    if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                    if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                    if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                    if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                    if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                    if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                    if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                    if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                    if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                    if(nCfL > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}

                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("L")))
                                            {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DW")))
                                            {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    }
                                    // rData.Description += strCritical;


                                    if(LoadCaseNo > 0)  
                                    {

                                        if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                        else                                  rData.nActive = 1;  
                                        rData.nSubLcomType = 0;
                                        AddLcomBoth(BothD);
                                        Set_LoadComb4CivilName_proxy(rData, D_STR);


                                    } 
                                }
                            }
                        }
                    }}}}
    }
}



void CLoadCombCtrl::SetCvl_PNS10030_1_PD(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad, ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCfLoad, ArINT& arCrlLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0  && m_nCSCount == 0) return;

    if(m_nMCount  == 0 && m_nCfCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dCfFactor = 0.0, dMFactor = 0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");
    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1;    //Permanent
    dStlFactor = 1.0 * 1.2;    //Permanent
    dCfFactor  = 1.0 * 1.25;   //Permanent
    dCrlFactor = 1.0 * 1.2;    //Permanent
    dMFactor   = 1.0 * 1.25;   //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString strFixM, strFixSm, csPrefix = _T("");  
                                strFixM.Format(_T("%d"), l+1);
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;

                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nErL=0, nCrL=0, nShL=0;
                                int nn=0, nLL=0, nCfL=0 ;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],      LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);



                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("L")))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                //       CString strLcomCount;
                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                //       
                                //       rData.Description = strTitle + strLcomCount;  
                                //       nLcomCount++;
                                rData.Description = strTitle;

                                if(nDL  > 0)  {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL> 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL> 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)  {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)  {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}


                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                if(nCfL > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}



                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("L")))
                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo>0)
                                {
                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 1;  
                                    rData.nSubLcomType = 0;
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_STR);

                                }
                            }
                        }}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_1_PW(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad, ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCfLoad, ArINT& arCrlLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)
{
    if(m_bPNS10030UniqType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0  && m_nCSCount == 0) return;

    if(m_nMCount  == 0 && m_nCfCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dCfFactor = 0.0, dMFactor = 0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");
    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; // Permanent load
    dStlFactor = 1.0 * 1.1; // Permanent load
    dCrlFactor = 1.0 * 1.1; // Permanent load
    dCfFactor  = 0.8 * 1.15; // Variable load
    dMFactor   = 0.8 * 1.15; // Variable load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) 
                            {              
                                CString strFixM, strFixSm, csPrefix = _T("");  
                                strFixM.Format(_T("%d"), l+1);
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;

                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nErL=0, nCrL=0, nShL=0;
                                int nn=0, nLL=0, nCfL=0 ;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],      LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("L")))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                //       CString strLcomCount;
                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                //       
                                //       rData.Description = strTitle + strLcomCount;  
                                //       nLcomCount++;
                                rData.Description = strTitle;

                                if(nDL  > 0)  {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL> 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL> 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)  {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)  {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                if(nCfL > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("L")))
                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 1;  
                                    rData.nSubLcomType = 0;
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_STR);
                                }
                            }
                        }}}}}}
}



void CLoadCombCtrl::SetCvl_PNS10030_2_P(CString strCode,
                                        ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad, 
                                        ArINT& arStlLoad, ArUNT& arSmLoad,  ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCrlLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)
{
    if(m_bPNS10030BaseType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0  && m_nCSCount == 0) return;

    if(m_nMCount  == 0 ) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0,  dMFactor = 0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;


    if(m_nDCount   == 0 && m_nEpCount == 0 && m_nCSCount == 0)  m_nPNS10030DNum = 1;
    if(m_nDwCount  == 0 && m_nDcCount == 0 && m_nCSCount == 0)  m_nPNS10030DWNum = 1; m_nPNS10030DCNum = 1;
    if(m_nPsCount  == 0 && m_nCSCount==0)                       m_nPNS10030PSNum= 1;
    if(m_nWpCount  == 0)                                        m_nPNS10030WPNum = 1; // 

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dCrlFactor = 1.0 * 1.3; //Permanent
    dMFactor   = 1.0 * 1.5; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString strFixM, strFixSm, csPrefix = _T("");  
                                strFixM.Format(_T("%d"), l+1);
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;

                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nErL=0, nCrL=0, nShL=0;
                                int nn=0, nLL=0, nCfL=0 ;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 			

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);			
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);			
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);			
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);			
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);			
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);			
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);			
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);	

                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);


                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("L")))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                //       CString strLcomCount;
                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                //       
                                //       rData.Description = strTitle + strLcomCount;  
                                //       nLcomCount++;
                                rData.Description = strTitle;

                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor)  + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}


                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("L")))
                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 1;  
                                    rData.nSubLcomType = 0;
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_STR);


                                }
                            }
                        }}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_2_PD(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad, 
                                         ArINT& arStlLoad, ArUNT& arSmLoad, ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCrlLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)
{
    if(m_bPNS10030AddType  != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0  && m_nCSCount == 0) return;

    if(m_nMCount  == 0 ) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0,  dMFactor = 0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;


    if(m_nDCount   == 0 && m_nEpCount == 0 && m_nCSCount == 0)  m_nPNS10030DNum = 1;
    if(m_nDwCount  == 0 && m_nDcCount == 0 && m_nCSCount == 0)  m_nPNS10030DWNum = 1; m_nPNS10030DCNum = 1;
    if(m_nPsCount  == 0 && m_nCSCount==0)                       m_nPNS10030PSNum= 1;
    if(m_nWpCount  == 0)                                        m_nPNS10030WPNum = 1; // 

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");
    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1;  // Permanent load 
    dStlFactor = 1.0 * 1.2;  // Permanent load
    dCrlFactor = 1.0 * 1.2;  // Permanent load
    dMFactor   = 1.0 * 1.25; // Variable load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString strFixM, strFixSm, csPrefix = _T("");  
                                strFixM.Format(_T("%d"), l+1);
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;

                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nErL=0, nCrL=0, nShL=0;
                                int nn=0, nLL=0, nCfL=0 ;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);



                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("L")))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                //       CString strLcomCount;
                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                //       
                                //       rData.Description = strTitle + strLcomCount;  
                                //       nLcomCount++;
                                rData.Description = strTitle;

                                if(nDL  > 0)  {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL> 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL> 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)  {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)  {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}


                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("L")))
                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 1;  
                                    rData.nSubLcomType = 0;
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_STR);

                                }
                            }
                        }}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_2_PW(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad, 
                                         ArINT& arStlLoad, ArUNT& arSmLoad, ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCrlLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)
{
    if(m_bPNS10030UniqType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0  && m_nCSCount == 0) return;

    if(m_nMCount  == 0 ) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0,  dMFactor = 0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;


    if(m_nDCount   == 0 && m_nEpCount == 0 && m_nCSCount == 0)  m_nPNS10030DNum = 1;
    if(m_nDwCount  == 0 && m_nDcCount == 0 && m_nCSCount == 0)  m_nPNS10030DWNum = 1; m_nPNS10030DCNum = 1;
    if(m_nPsCount  == 0 && m_nCSCount==0)                       m_nPNS10030PSNum= 1;
    if(m_nWpCount  == 0)                                        m_nPNS10030WPNum = 1; // 

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");
    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; // Permanent load
    dStlFactor = 1.0 * 1.1; // Permanent load
    dCrlFactor = 1.0 * 1.1; // Permanent load
    dMFactor   = 0.8 * 1.15; // Variable load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString strFixM, strFixSm, csPrefix = _T("");  
                                strFixM.Format(_T("%d"), l+1);
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;

                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nErL=0, nCrL=0, nShL=0;
                                int nn=0, nLL=0, nCfL=0 ;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);


                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("L")))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                //       CString strLcomCount;
                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                //       
                                //       rData.Description = strTitle + strLcomCount;  
                                //       nLcomCount++;
                                rData.Description = strTitle;

                                if(nDL  > 0)  {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL> 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL> 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)  {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)  {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}



                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("L")))
                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 1;  
                                    rData.nSubLcomType = 0;
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_STR);

                                }
                            }
                        }}}}}}
}



void CLoadCombCtrl::SetCvl_PNS10030_3_P(CString strCode,
                                        ArINT& arDLoad,   ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArUNT& arMLoad, ArINT& arLLoad,
                                        ArINT& arCfLoad, ArINT& arBrkLoad, ArINT& arWLoad,  ArINT& arWlLoad,  ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)
{
    if(m_bPNS10030BaseType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0) return;

    if( m_nMCount  == 0 && m_nCfCount == 0 && m_nBrkCount == 0  
        && m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dCfFactor =0.0, dBrkFactor =0.0, dWFactor=0.0, dTFactor =0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");

    _LCOM_IN InData;
    _LCOM_FD FData;
    _LCOM_RES ResData;

    _LCOM_UNIT UnitD;
    UnitD.Initialize();

    if(m_nMCount > 0)
    {
        UnitD.LcomK = 1;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("M");
        InData.arVariableLoadCase.Add(UnitD);

    }

    if(m_nCfCount > 0)
    {
        UnitD.LcomK = 2;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("CF");
        InData.arVariableLoadCase.Add(UnitD);

    }
    if(m_nTCount > 0) 
    {
        UnitD.LcomK = 3;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("T");
        InData.arVariableLoadCase.Add(UnitD);

    }
    if(m_nWCount > 0)
    {
        UnitD.LcomK = 4;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("W");
        InData.arVariableLoadCase.Add(UnitD);

    }
    if(m_nBrkCount > 0)
    {
        UnitD.LcomK = 5;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("BRK");
        InData.arVariableLoadCase.Add(UnitD);

    }

    switch (InData.arVariableLoadCase.GetSize())
    {
    case 1:
        FData.arCrticalF.SetSize(1);
        FData.arCrticalF[0] = 1.0;
        break;
    case 2:
        FData.arCrticalF.SetSize(2);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        break;
    case 3:
        FData.arCrticalF.SetSize(3);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        FData.arCrticalF[2] = 0.8;
        break;

    default:
        break;
    }


    if(InData.arVariableLoadCase.GetSize() > 3) 
    {
        FData.arCrticalF.SetSize(4);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        FData.arCrticalF[2] = 0.8;
        FData.arCrticalF[3] = 0.7;
    }

    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dCrlFactor = 1.0 * 1.3; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    _LCOM_IN arrResUnit;
    MakeLoadCombination4Var(arrResUnit, 0, InData, FData, ResData);


    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int m = 0; m < nWCountTemp; m++) { 
                                for(int n = 0; n < nWlCountTemp; n++) { 
                                    for(int o = 0; o < nTCountTemp; o++) { 
                                        for(int p = 0; p < nTpgCountTemp; p++) 
                                        {
                                            for(int k = 0; k < nSmCountTemp; k++) {
                                                for(int nVL =0; nVL<ResData.arLcomD.GetSize(); nVL++)
                                                {
                                                    const _LCOM_IN& aUnit = ResData.arLcomD[nVL];

                                                    CString strFixM, strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                    strFixM.Format(_T("%d"), l+1);
                                                    strFixW.Format(_T("%d"), m/2+1);
                                                    strFixWl.Format(_T("%d"), n/2+1);
                                                    strFixT.Format(_T("%d"), o+1);
                                                    strFixTpg.Format(_T("%d"), p+1);
                                                    strFixSm.Format(_T("%d"), k+1);
                                                    rData.Initialize();  
                                                    LoadCaseNo = 0;

                                                    _LCOM_BOTH BothD; BothD.Initialize();
                                                    int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nWL=0, nWlL=0, nTL=0, nBrkL=0, nErL=0, nCrL=0, nShL=0, nTpgL=0.0;
                                                    int nn=0, nLL=0, nCfL=0 ;
                                                    int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 			
                                                    double dWF =0.0, dWlF = 0.0;
                                                    for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                    for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                    for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                    for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                    for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                                    for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                    if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                    for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                                    for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                    double dCriFactor= 0.0;
                                                    for(int j = 0; j < aUnit.arVariableLoadCase.GetSize(); ++j)
                                                    {
                                                        const _LCOM_UNIT& aa = aUnit.arVariableLoadCase[j];

                                                        switch (aa.LcomK)
                                                        {
                                                        case 1: // MV
                                                            {
                                                                Set_MovingCase(arMLoad.GetAt(l), aa.dFactor, LoadCaseNo, rData, TRUE);
                                                                dMFactor=aa.dFactor;
                                                            }
                                                            break;
                                                        case 2: //CF
                                                            {
                                                                if(m_nMCount>0 || m_nLCount>0)
                                                                {
                                                                    for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                                    dCfFactor = aa.dFactor;
                                                                }
                                                            }
                                                            break;
                                                        case 3: //T
                                                            {
                                                                if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   aa.dFactor, LoadCaseNo, rData, 0);
                                                                if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), aa.dFactor, LoadCaseNo, rData, 0);
                                                                dTFactor = aa.dFactor;
                                                            }
                                                            break;
                                                        case 4: //W
                                                            {
                                                                dWF = (m%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                                dWlF = (n%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                                if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                                if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);
                                                            }
                                                            break;
                                                        case 5: //BRK
                                                            {
                                                                for(i=0; i<m_nBrkCount; i++) nBrkL += Set_STLCIncludeCS(arBrkLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                                dBrkFactor = aa.dFactor;
                                                            }
                                                            break;
                                                        default:
                                                            break;
                                                        }
                                                    }

                                                    if(m_nConstLoad!=0)
                                                    {
                                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }		

                                                        CString strcEL;
                                                        int nErection = 0;

                                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                        {
                                                            strcEL = _T(""); nErection = 0;
                                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                            if(CheckCSEL(nErection, _T("D")))
                                                            {
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                            }
                                                            if(CheckCSEL(nErection, _T("DC")))
                                                            {
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                                (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                            }
                                                            if(CheckCSEL(nErection, _T("L")))
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                            if(CheckCSEL(nErection, _T("DW")))
                                                            {
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                                (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                            }
                                                            if(CheckCSEL(nErection, _T("W")))
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                            if(CheckCSEL(nErection, _T("T")))
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE); 
                                                        }

                                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                        }
                                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                        }
                                                    }

                                                    //                         int nCNum = nVL+1;
                                                    //                         CString strCriticalNum;
                                                    //                         strCriticalNum.Format(_T("%d"), nCNum);
                                                    //                         CString strCritical;
                                                    //                         if(m == 0)  strCritical = _T("-(Case ") + strCriticalNum + _T(")");
                                                    //                         else        strCritical = _T("-(Case ") + strCriticalNum + _T("-1)");

                                                    rData.Description = strTitle;

                                                    if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                    if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                    if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                    if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                    if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                                    if(nEpL > 0)   {rData.Description += csPrefix + GetFactorString(dEpFactor)     + _T("EP");  csPrefix = _T("+");}
                                                    if(nStlL> 0)   {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("STL"); csPrefix = _T("+");}
                                                    if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                                    if(nCrlL> 0)   {rData.Description += csPrefix + GetFactorString(dCrlFactor)    + _T("CRL"); csPrefix = _T("+");}

                                                    if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                    if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                    if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                    if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                    if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                    if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                    if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                    if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                    if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                                    if(m_nMCount>0 || m_nLCount>0)
                                                    {
                                                        if(nCfL> 0) { rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+"); }
                                                    }

                                                    if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                    if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                                    if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                    if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF)  + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                                    if(nBrkL> 0) { rData.Description += csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+"); }

                                                    if(m_nConstLoad!=0)
                                                    {
                                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                        CString strcEL;
                                                        int nErection = 0;

                                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                        {
                                                            strcEL = _T(""); nErection = 0;
                                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                            if(CheckCSEL(nErection, _T("D")))
                                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("DC")))
                                                            {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("L")))
                                                            {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("DW")))
                                                            {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("W")))
                                                            {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("T")))
                                                            {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        }

                                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                        {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    }
                                                    /*        rData.Description += strCritical;*/

                                                    if(LoadCaseNo > 0)  
                                                    {

                                                        if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                        else                                  rData.nActive = 1;  
                                                        rData.nSubLcomType = 0;
                                                        AddLcomBoth(BothD);
                                                        Set_LoadComb4CivilName_proxy(rData, D_STR);

                                                    } 
                                                }
                                            }
                                        }
                                    }}}}}}}}}
}


void CLoadCombCtrl::SetCvl_PNS10030_3_PD(CString strCode,
                                         ArINT& arDLoad,   ArINT& arDcLoad,  ArINT& arDwLoad,  ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArUNT& arMLoad, ArINT& arLLoad,
                                         ArINT& arCfLoad,  ArINT& arBrkLoad, ArINT& arWLoad,   ArINT& arWlLoad,  ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad,ArINT& arEPNCLoad,ArINT& arEPMNLoad,ArINT& arEPMCLoad,
                                         BOOL bState)
{
    if(m_bPNS10030AddType  != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0) return;

    if( m_nMCount  == 0 && m_nCfCount == 0 && m_nBrkCount == 0  
        && m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0) return;
    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dCfFactor =0.0, dBrkFactor =0.0, dWFactor=0.0, dTFactor =0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent
    dCrlFactor = 1.0 * 1.2; //Permanent
    dMFactor   = 1.0 * 1.25; //Variable Load
    dCfFactor  = 1.0 * 1.25; //Variable Load
    dBrkFactor = 1.0 * 1.2; //Variable Load
    dWFactor   = 1.0 * 1.2; //Variable Load
    dTFactor   = 1.0 * 1.2; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int m = 0; m < nWCountTemp; m++) { 
                                for(int n = 0; n < nWlCountTemp; n++) { 
                                    for(int o = 0; o < nTCountTemp; o++) { 
                                        for(int p = 0; p < nTpgCountTemp; p++) 
                                        {
                                            for(int k = 0; k < nSmCountTemp; k++) {
                                                CString strFixM, strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                strFixM.Format(_T("%d"), l+1);
                                                strFixW.Format(_T("%d"), m/2+1);
                                                strFixWl.Format(_T("%d"), n/2+1);
                                                strFixT.Format(_T("%d"), o+1);
                                                strFixTpg.Format(_T("%d"), p+1);
                                                strFixSm.Format(_T("%d"), k+1);
                                                rData.Initialize();  
                                                LoadCaseNo = 0;

                                                _LCOM_BOTH BothD; BothD.Initialize();
                                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nWL=0, nWlL=0, nTL=0, nBrkL=0, nErL=0, nCrL=0, nShL=0, nTpgL=0.0;
                                                int nn=0, nLL=0, nCfL=0 ;
                                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);

                                                if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                                if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                                double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                                double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                                if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nBrkCount; i++) nBrkL += Set_STLCIncludeCS(arBrkLoad.GetAt(i), dBrkFactor, LoadCaseNo, rData, 0);

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }		

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("L")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("W")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("T")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE); 
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                    }
                                                }

                                                //       CString strLcomCount;
                                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                                //       
                                                //       rData.Description = strTitle + strLcomCount;  
                                                //       nLcomCount++;
                                                rData.Description = strTitle;

                                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                                if(nCfL > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}                        

                                                if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
                                                if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                                if(nBrkL> 0) { rData.Description += csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+"); }

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("L")))
                                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("W")))
                                                        {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("T")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                }

                                                if(LoadCaseNo > 0)  
                                                {

                                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                    else                                  rData.nActive = 1;  
                                                    rData.nSubLcomType = 0;
                                                    AddLcomBoth(BothD);
                                                    Set_LoadComb4CivilName_proxy(rData, D_STR);

                                                }
                                            }
                                        }}}}}}}}}}
}


void CLoadCombCtrl::SetCvl_PNS10030_3_PW(CString strCode,
                                         ArINT& arDLoad,   ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArUNT& arMLoad, ArINT& arLLoad,
                                         ArINT& arCfLoad, ArINT& arBrkLoad, ArINT& arWLoad,  ArINT& arWlLoad,  ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad, ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)
{
    if(m_bPNS10030UniqType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0) return;

    if( m_nMCount  == 0 && m_nCfCount == 0 && m_nBrkCount == 0  
        && m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dCfFactor =0.0, dBrkFactor =0.0, dWFactor=0.0, dTFactor =0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent
    dCrlFactor = 1.0 * 1.1; //Permanent
    dMFactor   = 0.8 * 1.15; //Variable Load
    dCfFactor  = 0.8 * 1.15; //Variable Load
    dBrkFactor = 0.8 * 1.1; //Variable Load
    dWFactor   = 0.8 * 1.1; //Variable Load
    dTFactor   = 0.8 * 1.1; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int m = 0; m < nWCountTemp; m++) { 
                                for(int n = 0; n < nWlCountTemp; n++) { 
                                    for(int o = 0; o < nTCountTemp; o++) { 
                                        for(int p = 0; p < nTpgCountTemp; p++) 
                                        {
                                            for(int k = 0; k < nSmCountTemp; k++) {
                                                CString strFixM, strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                strFixM.Format(_T("%d"), l+1);
                                                strFixW.Format(_T("%d"), m/2+1);
                                                strFixWl.Format(_T("%d"), n/2+1);
                                                strFixT.Format(_T("%d"), o+1);
                                                strFixTpg.Format(_T("%d"), p+1);
                                                strFixSm.Format(_T("%d"), k+1);
                                                rData.Initialize();  
                                                LoadCaseNo = 0;

                                                _LCOM_BOTH BothD; BothD.Initialize();
                                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nWL=0, nWlL=0, nTL=0, nBrkL=0, nErL=0, nCrL=0, nShL=0, nTpgL=0.0;
                                                int nn=0, nLL=0, nCfL=0 ;
                                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);

                                                if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                                if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                                double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                                double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                                if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nBrkCount; i++) nBrkL += Set_STLCIncludeCS(arBrkLoad.GetAt(i), dBrkFactor, LoadCaseNo, rData, 0);

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }		

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("L")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("W")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("T")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                    }
                                                }

                                                //       CString strLcomCount;
                                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                                //       
                                                //       rData.Description = strTitle + strLcomCount;  
                                                //       nLcomCount++;
                                                rData.Description = strTitle;

                                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                                if(nCfL > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}

                                                if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                                if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                                if(nBrkL> 0) { rData.Description += csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+"); }


                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("L")))
                                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("W")))
                                                        {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("T")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                }

                                                if(LoadCaseNo > 0)  
                                                {

                                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                    else                                  rData.nActive = 1;  
                                                    rData.nSubLcomType = 0;
                                                    AddLcomBoth(BothD);
                                                    Set_LoadComb4CivilName_proxy(rData, D_STR);

                                                }
                                            }
                                        }}}}}}}}}}
}


void CLoadCombCtrl::SetCvl_PNS10030_4_P(CString strCode,
                                        ArINT& arDLoad,  ArINT& arDcLoad,  ArINT& arDwLoad,   ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArUNT& arMLoad, ArINT& arLLoad,
                                        ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad,  ArINT& arIpLoad,  ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)
{
    if(m_bPNS10030BaseType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0  && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount == 0 && m_nCSCount == 0) return;

    if( m_nMCount  == 0 && m_nTCount == 0  && m_nTpgCount == 0 && m_nCrlCount == 0 && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dTFactor =0.0, dIpFactor =0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");

    _LCOM_IN InData;
    _LCOM_FD FData;
    _LCOM_RES ResData;

    _LCOM_UNIT UnitD;
    UnitD.Initialize();

    if(m_nMCount > 0)
    {
        UnitD.LcomK = 1;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("M");
        InData.arVariableLoadCase.Add(UnitD);

    }

    if(m_nTCount > 0)
    {
        UnitD.LcomK = 2;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("T");
        InData.arVariableLoadCase.Add(UnitD);

    }
    if(m_nIpCount > 0) 
    {
        UnitD.LcomK = 3;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("IP");
        InData.arVariableLoadCase.Add(UnitD);

    }


    switch (InData.arVariableLoadCase.GetSize())
    {
    case 1:
        FData.arCrticalF.SetSize(1);
        FData.arCrticalF[0] = 1.0;
        break;
    case 2:
        FData.arCrticalF.SetSize(2);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        break;
    case 3:
        FData.arCrticalF.SetSize(3);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        FData.arCrticalF[2] = 0.8;
        break;

    default:
        break;
    }


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dCrlFactor = 1.0 * 1.3; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    _LCOM_IN arrResUnit;
    MakeLoadCombination4Var(arrResUnit, 0, InData, FData, ResData);

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int o = 0; o < nTCountTemp; o++) { 
                                for(int p = 0; p < nTpgCountTemp; p++) 
                                {
                                    for(int k = 0; k < nSmCountTemp; k++) {
                                        for(int nVL =0; nVL<ResData.arLcomD.GetSize(); nVL++)
                                        {
                                            const _LCOM_IN& aUnit = ResData.arLcomD[nVL];

                                            CString strFixM, strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                            strFixM.Format(_T("%d"), l+1);
                                            strFixT.Format(_T("%d"), o+1);
                                            strFixTpg.Format(_T("%d"), p+1);
                                            strFixSm.Format(_T("%d"), k+1);
                                            rData.Initialize();  
                                            LoadCaseNo = 0;

                                            _LCOM_BOTH BothD; BothD.Initialize();
                                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nIpL=0,nCrlL=0,nTL=0, nCrL=0, nShL=0, nTpgL=0 ;
                                            int nn=0, nLL=0, nCfL=0 ;
                                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 			
                                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nEpCount; i++)   nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nStlCount; i++)  nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                            for(i=0; i<m_nCrlCount; i++)  nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                            for(int j = 0; j < aUnit.arVariableLoadCase.GetSize(); ++j)
                                            {
                                                const _LCOM_UNIT& aa = aUnit.arVariableLoadCase[j];

                                                switch (aa.LcomK)
                                                {
                                                case 1: // MV
                                                    {
                                                        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), aa.dFactor, LoadCaseNo, rData, TRUE);
                                                        dMFactor = aa.dFactor; 
                                                    }

                                                    break;
                                                case 2: //T
                                                    {
                                                        if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   aa.dFactor, LoadCaseNo, rData, 0);
                                                        if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), aa.dFactor, LoadCaseNo, rData, 0);
                                                        dTFactor = aa.dFactor;
                                                    }
                                                    break;
                                                case 3: //IP
                                                    {
                                                        for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                        dIpFactor = aa.dFactor;
                                                    }

                                                    break;

                                                default:
                                                    break;
                                                }
                                            }

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }		

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("L")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("T")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                }
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                }
                                            }

                                            //                       int nCNum = nVL+1;
                                            //                       CString strCriticalNum;
                                            //                       strCriticalNum.Format(_T("%d"), nCNum);
                                            //                       CString strCritical = _T("-(Case ") + strCriticalNum + _T(")");

                                            rData.Description = strTitle;

                                            if(nDL   > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                            if(nDcL  > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                            if(nDwL  > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                            if(nPsL  > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                            if(nWpL  > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                            if(nEpL  > 0)   {rData.Description += csPrefix + GetFactorString(dEpFactor)     + _T("EP");  csPrefix = _T("+");}
                                            if(nStlL > 0)   {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("STL"); csPrefix = _T("+");}
                                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                            if(nCrlL > 0)   {rData.Description += csPrefix + GetFactorString(dCrlFactor)    + _T("CRL"); csPrefix = _T("+");}

                                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                            if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}

                                            if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                            if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                            if(nIpL > 0) {rData.Description += csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("L")))
                                                    {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("T")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            }
                                            //                     rData.Description += strCritical;

                                            if(LoadCaseNo > 0)  
                                            {

                                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                else                                  rData.nActive = 1;  
                                                rData.nSubLcomType = 0;
                                                AddLcomBoth(BothD);
                                                Set_LoadComb4CivilName_proxy(rData, D_STR);


                                            }
                                        }
                                    }
                                }}}}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_4_PD(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad,  ArINT& arDwLoad,   ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArUNT& arMLoad, ArINT& arLLoad,
                                         ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad,  ArINT& arIpLoad,  ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)
{
    if(m_bPNS10030AddType  != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0  && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount == 0 && m_nCSCount == 0) return;

    if( m_nMCount  == 0 && m_nTCount == 0  && m_nTpgCount == 0 && m_nCrlCount == 0 && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dTFactor =0.0, dIpFactor =0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent
    dCrlFactor = 1.0 * 1.2; //Permanent
    dMFactor   = 1.0 * 1.25; //Variable Load
    dTFactor   = 1.0 * 1.2; //Variable Load
    dIpFactor  = 1.0 * 1.0; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int o = 0; o < nTCountTemp; o++) { 
                                for(int p = 0; p < nTpgCountTemp; p++) 
                                {
                                    for(int k = 0; k < nSmCountTemp; k++) {
                                        CString strFixM, strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                        strFixM.Format(_T("%d"), l+1);
                                        strFixT.Format(_T("%d"), o+1);
                                        strFixTpg.Format(_T("%d"), p+1);
                                        strFixSm.Format(_T("%d"), k+1);
                                        rData.Initialize();  
                                        LoadCaseNo = 0;

                                        _LCOM_BOTH BothD; BothD.Initialize();
                                        int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nIpL=0,nCrlL=0,nTL=0, nCrL=0, nShL=0, nTpgL=0 ;
                                        int nn=0, nLL=0, nCfL=0 ;
                                        int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                        for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                        if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                        for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                        for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);

                                        if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                        if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                        for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                                        if(m_nConstLoad!=0)
                                        {
                                            if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }		

                                            CString strcEL;
                                            int nErection = 0;

                                            for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                            {
                                                strcEL = _T(""); nErection = 0;
                                                if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                if(CheckCSEL(nErection, _T("D")))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCSEL(nErection, _T("DC")))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                    (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCSEL(nErection, _T("L")))
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                if(CheckCSEL(nErection, _T("DW")))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                    (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCSEL(nErection, _T("T")))
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE); 
                                            }

                                            if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                            }
                                            if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                            }
                                        }

                                        //       CString strLcomCount;
                                        //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                        //       
                                        //       rData.Description = strTitle + strLcomCount;  
                                        //       nLcomCount++;
                                        rData.Description = strTitle;

                                        if(nDL  > 0)    {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                        if(nDcL > 0)    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                        if(nDwL > 0)    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                        if(nPsL > 0)    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                        if(nWpL > 0)    {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                        if(nEpL>0)      {rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                        if(nStlL>0)     {rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                        if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                        if(nCrlL > 0)   {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                        if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                        if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                        if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                        if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                        if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                        if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                        if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                        if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                        if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}

                                        if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                        if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                        if(nIpL > 0) {rData.Description += csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                                        if(m_nConstLoad!=0)
                                        {
                                            if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                            CString strcEL;
                                            int nErection = 0;

                                            for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                            {
                                                strcEL = _T(""); nErection = 0;
                                                if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                if(CheckCSEL(nErection, _T("D")))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                if(CheckCSEL(nErection, _T("DC")))
                                                {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                if(CheckCSEL(nErection, _T("L")))
                                                {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                if(CheckCSEL(nErection, _T("DW")))
                                                {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                if(CheckCSEL(nErection, _T("T")))
                                                {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                            }

                                            if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                            {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                            if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                        }

                                        if(LoadCaseNo > 0)  
                                        {

                                            if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                            else                                  rData.nActive = 1;  
                                            rData.nSubLcomType = 0;
                                            AddLcomBoth(BothD);
                                            Set_LoadComb4CivilName_proxy(rData, D_STR);

                                        }
                                    }
                                }}}}}}}}
}


void CLoadCombCtrl::SetCvl_PNS10030_4_PW(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad,  ArINT& arDwLoad,   ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArUNT& arMLoad, ArINT& arLLoad,
                                         ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad,  ArINT& arIpLoad,  ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)
{
    if(m_bPNS10030UniqType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0  && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount == 0 && m_nCSCount == 0) return;

    if( m_nMCount  == 0 && m_nTCount == 0  && m_nTpgCount == 0 && m_nCrlCount == 0 && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dTFactor =0.0, dIpFactor =0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent
    dCrlFactor = 1.0 * 1.1; //Permanent
    dMFactor   = 0.8 * 1.15; //Variable Load
    dTFactor   = 0.8 * 1.1;  //Variable Load
    dIpFactor  = 0.8 * 1.0;  //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int o = 0; o < nTCountTemp; o++) { 
                                for(int p = 0; p < nTpgCountTemp; p++) 
                                {
                                    for(int k = 0; k < nSmCountTemp; k++) {
                                        CString strFixM, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                        strFixM.Format(_T("%d"), l+1);
                                        strFixT.Format(_T("%d"), o+1);
                                        strFixTpg.Format(_T("%d"), p+1);
                                        strFixSm.Format(_T("%d"), k+1);
                                        rData.Initialize();  
                                        LoadCaseNo = 0;

                                        _LCOM_BOTH BothD; BothD.Initialize();
                                        int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nIpL=0,nCrlL=0,nTL=0, nCrL=0, nShL=0, nTpgL=0 ;
                                        int nn=0, nLL=0, nCfL=0 ;
                                        int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                        for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                        for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                        if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                        for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                        for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                        for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                        if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                        if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                        for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                                        if(m_nConstLoad!=0)
                                        {
                                            if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }		

                                            CString strcEL;
                                            int nErection = 0;

                                            for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                            {
                                                strcEL = _T(""); nErection = 0;
                                                if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                if(CheckCSEL(nErection, _T("D")))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCSEL(nErection, _T("DC")))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                    (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCSEL(nErection, _T("L")))
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                if(CheckCSEL(nErection, _T("DW")))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                    (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCSEL(nErection, _T("T")))
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                            }

                                            if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                            }
                                            if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                            }
                                        }

                                        //       CString strLcomCount;
                                        //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                        //       
                                        //       rData.Description = strTitle + strLcomCount;  
                                        //       nLcomCount++;
                                        rData.Description = strTitle;

                                        if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                        if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                        if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                        if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                        if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                        if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                        if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                        if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                        if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                        if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                        if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                        if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                        if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                        if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                        if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                        if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                        if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                        if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}

                                        if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                        if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                        if(nIpL > 0) {rData.Description += csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}
                                        if(m_nConstLoad!=0)
                                        {
                                            if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                            CString strcEL;
                                            int nErection = 0;

                                            for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                            {
                                                strcEL = _T(""); nErection = 0;
                                                if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                if(CheckCSEL(nErection, _T("D")))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                if(CheckCSEL(nErection, _T("DC")))
                                                {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                if(CheckCSEL(nErection, _T("L")))
                                                {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                if(CheckCSEL(nErection, _T("DW")))
                                                {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                            }

                                            if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                            {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                            if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("T")))
                                            {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                        }

                                        if(LoadCaseNo > 0)  
                                        {

                                            if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                            else                                  rData.nActive = 1;  
                                            rData.nSubLcomType = 0;
                                            AddLcomBoth(BothD);
                                            Set_LoadComb4CivilName_proxy(rData, D_STR);


                                        }
                                    }
                                }}}}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_5_P(CString strCode,
                                        ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                        ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arIpLoad, ArINT& arErLoad,  ArINT& arCSLoad,
                                        ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)

{
    if(m_bPNS10030BaseType != 1) return;
    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dIpFactor =0.0, dErFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");

    _LCOM_IN InData;
    _LCOM_FD FData;
    _LCOM_RES ResData;

    _LCOM_UNIT UnitD;
    UnitD.Initialize();

    if(m_nTCount > 0)
    {
        UnitD.LcomK = 1;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("T");
        InData.arVariableLoadCase.Add(UnitD);

    }

    if(m_nWCount > 0)
    {
        UnitD.LcomK = 2;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("W");
        InData.arVariableLoadCase.Add(UnitD);

    }


    if(m_nIpCount > 0) 
    {
        UnitD.LcomK = 3;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("IP");
        InData.arVariableLoadCase.Add(UnitD);

    }

    switch (InData.arVariableLoadCase.GetSize())
    {
    case 1:
        FData.arCrticalF.SetSize(1);
        FData.arCrticalF[0] = 1.0;
        break;
    case 2:
        FData.arCrticalF.SetSize(2);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        break;
    case 3:
        FData.arCrticalF.SetSize(3);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        FData.arCrticalF[2] = 0.8;
        break;

    default:
        break;
    }


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dErFactor  = 1.0 * 1.5; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    _LCOM_IN arrResUnit;
    MakeLoadCombination4Var(arrResUnit, 0, InData, FData, ResData);

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            for(int nVL =0; nVL<ResData.arLcomD.GetSize(); nVL++)
                                            {
                                                const _LCOM_IN& aUnit = ResData.arLcomD[nVL];

                                                CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                strFixW.Format(_T("%d"), m/2+1);
                                                strFixWl.Format(_T("%d"), n/2+1);
                                                strFixT.Format(_T("%d"), o+1);
                                                strFixTpg.Format(_T("%d"), p+1);
                                                strFixSm.Format(_T("%d"), k+1);
                                                rData.Initialize();  
                                                LoadCaseNo = 0;

                                                _LCOM_BOTH BothD; BothD.Initialize();
                                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                                                int nn=0;
                                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 			
                                                double dWF = 0.0, dWlF =0.0;
                                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                for(int j = 0; j < aUnit.arVariableLoadCase.GetSize(); ++j)
                                                {
                                                    const _LCOM_UNIT& aa = aUnit.arVariableLoadCase[j];

                                                    switch (aa.LcomK)
                                                    {
                                                    case 1: //T
                                                        {
                                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   aa.dFactor, LoadCaseNo, rData, 0);
                                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), aa.dFactor, LoadCaseNo, rData, 0);
                                                            dTFactor = aa.dFactor;
                                                        }
                                                        break;
                                                    case 2: //W
                                                        {
                                                            dWF = (m%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                            dWlF = (n%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);
                                                        }
                                                        break;
                                                    case 3: //IP
                                                        {
                                                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                            dIpFactor = aa.dFactor;
                                                        }
                                                        break;
                                                    default:
                                                        break;
                                                    }
                                                }

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }		

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }

                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("W")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("T")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("ER")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                    }
                                                }

                                                //                         int nCNum = nVL+1;
                                                //                         CString strCriticalNum;
                                                //                         strCriticalNum.Format(_T("%d"), nCNum);
                                                //                         CString strCritical;
                                                //                         if(m == 0)  strCritical = _T("-(Case ") + strCriticalNum + _T(")");
                                                //                         else        strCritical = _T("-(Case ") + strCriticalNum + _T("-1)");

                                                rData.Description = strTitle;

                                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                                if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                                if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                                if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("W")))
                                                        {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("T")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("ER")))
                                                        {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                }

                                                if(LoadCaseNo > 0)  
                                                {

                                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                    else                                  rData.nActive = 1;  
                                                    rData.nSubLcomType = 0;
                                                    AddLcomBoth(BothD);
                                                    Set_LoadComb4CivilName_proxy(rData, D_STR);
                                                }
                                            }
                                        }
                                    }}}}}}}}}
}



void CLoadCombCtrl::SetCvl_PNS10030_5_PD(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arIpLoad, ArINT& arErLoad,  ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0  && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount == 0 && m_nCSCount == 0) return;

    if( m_nMCount  == 0 && m_nTCount == 0  && m_nTpgCount == 0 && m_nCrlCount == 0 && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dIpFactor =0.0, dErFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent load
    dStlFactor = 1.0 * 1.2; //Permanent load
    dErFactor  = 1.0 * 1.25;//Permanent load
    dWFactor   = 1.0 * 1.2; //Variable load
    dTFactor   = 1.0 * 1.2; //Variable load
    dIpFactor  = 1.0 * 1.0; //Variable load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                            strFixW.Format(_T("%d"), m/2+1);
                                            strFixWl.Format(_T("%d"), n/2+1);
                                            strFixT.Format(_T("%d"), o+1);
                                            strFixTpg.Format(_T("%d"), p+1);
                                            strFixSm.Format(_T("%d"), k+1);
                                            rData.Initialize();  
                                            LoadCaseNo = 0;

                                            _LCOM_BOTH BothD; BothD.Initialize();
                                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                                            int nn=0;
                                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                            for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                            double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                            double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }		

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }

                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("W")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("T")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("ER")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                }
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                }
                                            }

                                            //       CString strLcomCount;
                                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                            //       
                                            //       rData.Description = strTitle + strLcomCount;  
                                            //       nLcomCount++;
                                            rData.Description = strTitle;

                                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                            if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                            if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                            if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                            if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                            if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                            if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("W")))
                                                    {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("T")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("ER")))
                                                    {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            }

                                            if(LoadCaseNo > 0)  
                                            {

                                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                else                                  rData.nActive = 1;  
                                                rData.nSubLcomType = 0;
                                                AddLcomBoth(BothD);
                                                Set_LoadComb4CivilName_proxy(rData, D_STR);


                                            }
                                        }
                                    }}}}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_5_PW(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arIpLoad, ArINT& arErLoad,  ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030UniqType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0  && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount == 0 && m_nCSCount == 0) return;

    if( m_nMCount  == 0 && m_nTCount == 0  && m_nTpgCount == 0 && m_nCrlCount == 0 && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dIpFactor =0.0, dErFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent Load
    dStlFactor = 1.0 * 1.1; //Permanent Load
    dErFactor  = 0.8 * 1.15; //Permanent Load
    dWFactor   = 0.8 * 1.1; //Variable Load
    dTFactor   = 0.8 * 1.1; //Variable Load
    dIpFactor  = 0.8 * 1.0; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                            strFixW.Format(_T("%d"), m/2+1);
                                            strFixWl.Format(_T("%d"), n/2+1);
                                            strFixT.Format(_T("%d"), o+1);
                                            strFixTpg.Format(_T("%d"), p+1);
                                            strFixSm.Format(_T("%d"), k+1);
                                            rData.Initialize();  
                                            LoadCaseNo = 0;

                                            _LCOM_BOTH BothD; BothD.Initialize();
                                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                                            int nn=0;
                                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                            for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                            double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                            double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }		

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }

                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("W")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("T")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("ER")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                }
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                }
                                            }

                                            //       CString strLcomCount;
                                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                            //       
                                            //       rData.Description = strTitle + strLcomCount;  
                                            //       nLcomCount++;
                                            rData.Description = strTitle;

                                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}
                                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                            if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                            if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                            if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                            if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                            if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}
                                            if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("W")))
                                                    {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("T")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("ER")))
                                                    {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            }

                                            if(LoadCaseNo > 0)  
                                            {

                                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                else                                  rData.nActive = 1;  
                                                rData.nSubLcomType = 0;
                                                AddLcomBoth(BothD);
                                                Set_LoadComb4CivilName_proxy(rData, D_STR);


                                            }
                                        }
                                    }}}}}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_6_P(CString strCode,
                                        ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                        ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arErLoad,  ArINT& arCSLoad,
                                        ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)
{
    if(m_bPNS10030BaseType != 1) return;
    if( m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nErCount == 0 && m_nCSCount == 0) return;

    if(m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dErFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");

    _LCOM_IN InData;
    _LCOM_FD FData;
    _LCOM_RES ResData;

    _LCOM_UNIT UnitD;
    UnitD.Initialize();

    if(m_nTCount > 0)
    {
        UnitD.LcomK = 1;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("T");
        InData.arVariableLoadCase.Add(UnitD);

    }

    if(m_nWCount > 0)
    {
        UnitD.LcomK = 2;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("W");
        InData.arVariableLoadCase.Add(UnitD);

    }
    switch (InData.arVariableLoadCase.GetSize())
    {
    case 1:
        FData.arCrticalF.SetSize(1);
        FData.arCrticalF[0] = 1.0;
        break;
    case 2:
        FData.arCrticalF.SetSize(2);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        break;

    default:
        break;
    }


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dErFactor  = 1.0 * 1.5; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    _LCOM_IN arrResUnit;
    MakeLoadCombination4Var(arrResUnit, 0, InData, FData, ResData);


    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            for(int nVL =0; nVL<ResData.arLcomD.GetSize(); nVL++)
                                            {
                                                const _LCOM_IN& aUnit = ResData.arLcomD[nVL];

                                                CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                strFixW.Format(_T("%d"), m/2+1);
                                                strFixWl.Format(_T("%d"), n/2+1);
                                                strFixT.Format(_T("%d"), o+1);
                                                strFixTpg.Format(_T("%d"), p+1);
                                                strFixSm.Format(_T("%d"), k+1);
                                                rData.Initialize();  
                                                LoadCaseNo = 0;

                                                _LCOM_BOTH BothD; BothD.Initialize();
                                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                                                int nn=0;
                                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 
                                                double dWF = 0.0, dWlF =0.0;
                                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }


                                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                for(int j = 0; j < aUnit.arVariableLoadCase.GetSize(); ++j)
                                                {
                                                    const _LCOM_UNIT& aa = aUnit.arVariableLoadCase[j];

                                                    switch (aa.LcomK)
                                                    {
                                                    case 1: //T
                                                        {
                                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   aa.dFactor, LoadCaseNo, rData, 0);
                                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), aa.dFactor, LoadCaseNo, rData, 0);
                                                            dTFactor = aa.dFactor;
                                                        }
                                                        break;
                                                    case 2: //W
                                                        {
                                                            dWF = (m%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                            dWlF = (n%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);
                                                        }
                                                        break;

                                                    default:
                                                        break;
                                                    }
                                                }

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }		

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }

                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("W")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("T")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("ER")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                    }
                                                }

                                                //                     int nCNum = nVL+1;
                                                //                     CString strCriticalNum;
                                                //                     strCriticalNum.Format(_T("%d"), nCNum);
                                                //                     CString strCritical;
                                                //                     if(m == 0)  strCritical = _T("-(Case ") + strCriticalNum + _T(")");
                                                //                     else        strCritical = _T("-(Case ") + strCriticalNum + _T("-1)");

                                                rData.Description = strTitle;

                                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                                if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                                if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("W")))
                                                        {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("T")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("ER")))
                                                        {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                }
                                                //                     rData.Description += strCritical;

                                                if(LoadCaseNo > 0)  
                                                {

                                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                    else                                  rData.nActive = 1;  
                                                    rData.nSubLcomType = 0;
                                                    AddLcomBoth(BothD);
                                                    Set_LoadComb4CivilName_proxy(rData, D_STR);


                                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                    else                                  rData.nActive = 2;  
                                                    rData.nSubLcomType = 0; 
                                                    AddLcomBoth(BothD);
                                                    Set_LoadComb4CivilName_proxy(rData, D_SER);

                                                }
                                            }
                                        }
                                    }}}}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_6_PD(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arErLoad,  ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if( m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nErCount == 0 && m_nCSCount == 0) return;

    if(m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dErFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent Load
    dStlFactor = 1.0 * 1.2; //Permanent Load
    dErFactor  = 1.0 * 1.25; //Permanent Load
    dWFactor   = 1.0 * 1.2; //Variable Load
    dTFactor   = 1.0 * 1.2; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                            strFixW.Format(_T("%d"), m/2+1);
                                            strFixWl.Format(_T("%d"), n/2+1);
                                            strFixT.Format(_T("%d"), o+1);
                                            strFixTpg.Format(_T("%d"), p+1);
                                            strFixSm.Format(_T("%d"), k+1);
                                            rData.Initialize();  
                                            LoadCaseNo = 0;

                                            _LCOM_BOTH BothD; BothD.Initialize();
                                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                                            int nn=0;
                                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                            for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                            double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                            double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }		

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }

                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("W")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("T")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("ER")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                }
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                }
                                            }

                                            //       CString strLcomCount;
                                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                            //       
                                            //       rData.Description = strTitle + strLcomCount;  
                                            //       nLcomCount++;
                                            rData.Description = strTitle;

                                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                            if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                            if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                            if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                            if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                            if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("W")))
                                                    {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("T")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("ER")))
                                                    {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            }

                                            if(LoadCaseNo > 0)  
                                            {

                                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                else                                  rData.nActive = 1;  
                                                rData.nSubLcomType = 0;
                                                AddLcomBoth(BothD);
                                                Set_LoadComb4CivilName_proxy(rData, D_STR);

                                            }
                                        }
                                    }}}}}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_6_PW(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arErLoad,  ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030UniqType != 1) return;
    if( m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nErCount == 0 && m_nCSCount == 0) return;

    if(m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dErFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent Load
    dStlFactor = 1.0 * 1.1; //Permanent Load
    dErFactor  = 1.0 * 1.15; //Permanent Load
    dWFactor   = 0.8 * 1.1; //Variable Load
    dTFactor   = 0.8 * 1.1; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                            strFixW.Format(_T("%d"), m/2+1);
                                            strFixWl.Format(_T("%d"), n/2+1);
                                            strFixT.Format(_T("%d"), o+1);
                                            strFixTpg.Format(_T("%d"), p+1);
                                            strFixSm.Format(_T("%d"), k+1);
                                            rData.Initialize();  
                                            LoadCaseNo = 0;

                                            _LCOM_BOTH BothD; BothD.Initialize();
                                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                                            int nn=0;
                                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                            for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                            double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                            double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }		

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }

                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("W")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("T")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("ER")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                }
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                }
                                            }

                                            //       CString strLcomCount;
                                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                            //       
                                            //       rData.Description = strTitle + strLcomCount;  
                                            //       nLcomCount++;
                                            rData.Description = strTitle;

                                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                            if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                            if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                            if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                            if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                            if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}


                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("W")))
                                                    {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("T")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("ER")))
                                                    {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            }

                                            if(LoadCaseNo > 0)  
                                            {

                                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                else                                  rData.nActive = 1;  
                                                rData.nSubLcomType = 0;
                                                AddLcomBoth(BothD);
                                                Set_LoadComb4CivilName_proxy(rData, D_STR);

                                            }
                                        }
                                    }}}}}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_7_P(CString strCode,
                                        ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                        ArINT& arIpLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)

{
    if(m_bPNS10030BaseType != 1) return;
    if(  m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;


    if( m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dIpFactor =0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nSmCountTemp   = max(m_nSmCount, 1);

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dIpFactor  = 1.0 * 1.5; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 
                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);	


                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);


                            }
                        }
                    }}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_7_PD(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arIpLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if(  m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;


    if( m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dIpFactor =0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);


    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent
    dIpFactor  = 1.0 * 1.0; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);


                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}



                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);
                            }
                        }
                    }}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_7_PW(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arIpLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030UniqType != 1) return;
    if(  m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;


    if( m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dIpFactor =0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);


    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent
    dIpFactor  = 0.8 * 1.0; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);


                            }
                        }
                    }}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_8_P(CString strCode,
                                        ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                        ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arIpLoad,  ArINT& arCSLoad,
                                        ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)

{
    if(m_bPNS10030BaseType != 1) return;
    if( m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;

    if(m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0  && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dIpFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");

    _LCOM_IN InData;
    _LCOM_FD FData;
    _LCOM_RES ResData;

    _LCOM_UNIT UnitD;
    UnitD.Initialize();

    if(m_nTCount > 0)
    {
        UnitD.LcomK = 1;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("T");
        InData.arVariableLoadCase.Add(UnitD);

    }

    if(m_nWCount > 0)
    {
        UnitD.LcomK = 2;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("W");
        InData.arVariableLoadCase.Add(UnitD);

    }


    if(m_nIpCount > 0) 
    {
        UnitD.LcomK = 3;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("IP");
        InData.arVariableLoadCase.Add(UnitD);

    }

    switch (InData.arVariableLoadCase.GetSize())
    {
    case 1:
        FData.arCrticalF.SetSize(1);
        FData.arCrticalF[0] = 1.0;
        break;
    case 2:
        FData.arCrticalF.SetSize(2);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        break;
    case 3:
        FData.arCrticalF.SetSize(3);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        FData.arCrticalF[2] = 0.8;
        break;

    default:
        break;
    }

    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    _LCOM_IN arrResUnit;
    MakeLoadCombination4Var(arrResUnit, 0, InData, FData, ResData);

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            for(int nVL =0; nVL<ResData.arLcomD.GetSize(); nVL++)
                                            {
                                                const _LCOM_IN& aUnit = ResData.arLcomD[nVL];

                                                CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                strFixW.Format(_T("%d"), m/2+1);
                                                strFixWl.Format(_T("%d"), n/2+1);
                                                strFixT.Format(_T("%d"), o+1);
                                                strFixTpg.Format(_T("%d"), p+1);
                                                strFixSm.Format(_T("%d"), k+1);
                                                rData.Initialize();  
                                                LoadCaseNo = 0;

                                                _LCOM_BOTH BothD; BothD.Initialize();
                                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nCrL=0, nShL=0;
                                                int nn=0;
                                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 
                                                double dWF = 0.0, dWlF =0.0;
                                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }


                                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                for(int j = 0; j < aUnit.arVariableLoadCase.GetSize(); ++j)
                                                {
                                                    const _LCOM_UNIT& aa = aUnit.arVariableLoadCase[j];

                                                    switch (aa.LcomK)
                                                    {
                                                    case 1: //T
                                                        {
                                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   aa.dFactor, LoadCaseNo, rData, 0);
                                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), aa.dFactor, LoadCaseNo, rData, 0);
                                                            dTFactor = aa.dFactor;
                                                        }
                                                        break;
                                                    case 2: //W
                                                        {
                                                            dWF = (m%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                            dWlF = (n%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);
                                                        }
                                                        break;
                                                    case 3: //IP
                                                        {
                                                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                            dIpFactor = aa.dFactor;
                                                        }
                                                        break;
                                                    default:
                                                        break;
                                                    }
                                                }

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }		

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }

                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("W")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("T")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                    }
                                                }

                                                //                     int nCNum = nVL+1;
                                                //                     CString strCriticalNum;
                                                //                     strCriticalNum.Format(_T("%d"), nCNum);
                                                //                     CString strCritical;
                                                //                     if(m == 0)  strCritical = _T("-(Case ") + strCriticalNum + _T(")");
                                                //                     else        strCritical = _T("-(Case ") + strCriticalNum + _T("-1)");

                                                rData.Description = strTitle;

                                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                                if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}
                                                if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}


                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("W")))
                                                        {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("T")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                }
                                                //                 rData.Description += strCritical;
                                                if(LoadCaseNo > 0)  
                                                {

                                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                    else                                  rData.nActive = 1;  
                                                    rData.nSubLcomType = 0;
                                                    AddLcomBoth(BothD);
                                                    Set_LoadComb4CivilName_proxy(rData, D_STR);
                                                }
                                            }
                                        }
                                    }}}}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_8_PD(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arIpLoad,  ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if( m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;

    if(m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0  && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dIpFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent
    dWFactor   = 1.0 * 1.2; //Variable Load
    dTFactor   = 1.0 * 1.2; //Variable Load
    dIpFactor  = 1.0 * 1.0; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                            strFixW.Format(_T("%d"), m/2+1);
                                            strFixWl.Format(_T("%d"), n/2+1);
                                            strFixT.Format(_T("%d"), o+1);
                                            strFixTpg.Format(_T("%d"), p+1);
                                            strFixSm.Format(_T("%d"), k+1);
                                            rData.Initialize();  
                                            LoadCaseNo = 0;

                                            _LCOM_BOTH BothD; BothD.Initialize();
                                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nCrL=0, nShL=0;
                                            int nn=0;
                                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                            double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                            double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }		

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }

                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("W")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("T")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                }
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                }
                                            }

                                            //       CString strLcomCount;
                                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                            //       
                                            //       rData.Description = strTitle + strLcomCount;  
                                            //       nLcomCount++;
                                            rData.Description = strTitle;

                                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                            if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                            if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                            if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                            if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                            if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("W")))
                                                    {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("T")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            }

                                            if(LoadCaseNo > 0)  
                                            {

                                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                else                                  rData.nActive = 1;  
                                                rData.nSubLcomType = 0;
                                                AddLcomBoth(BothD);
                                                Set_LoadComb4CivilName_proxy(rData, D_STR);

                                            }
                                        }
                                    }}}}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_8_PW(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arWLoad, ArINT& arWlLoad, ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arIpLoad,  ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030UniqType != 1) return;
    if( m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;

    if(m_nWCount == 0 && m_nWlCount == 0 && m_nTCount == 0 && m_nTpgCount == 0  && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dIpFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent
    dWFactor   = 0.8 * 1.1; //Variable Load
    dTFactor   = 0.8 * 1.1; //Variable Load
    dIpFactor  = 0.8 * 1.0; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m = 0; m < nWCountTemp; m++) { 
                            for(int n = 0; n < nWlCountTemp; n++) { 
                                for(int o = 0; o < nTCountTemp; o++) { 
                                    for(int p = 0; p < nTpgCountTemp; p++) 
                                    {
                                        for(int k = 0; k < nSmCountTemp; k++) {
                                            CString strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                            strFixW.Format(_T("%d"), m/2+1);
                                            strFixWl.Format(_T("%d"), n/2+1);
                                            strFixT.Format(_T("%d"), o+1);
                                            strFixTpg.Format(_T("%d"), p+1);
                                            strFixSm.Format(_T("%d"), k+1);
                                            rData.Initialize();  
                                            LoadCaseNo = 0;

                                            _LCOM_BOTH BothD; BothD.Initialize();
                                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nCrL=0, nShL=0;
                                            int nn=0;
                                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                            if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                            if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                            double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                            double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                            if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                            if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                            for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }		

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }

                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCSEL(nErection, _T("W")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                    if(CheckCSEL(nErection, _T("T")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                }
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                }
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {
                                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                }
                                            }

                                            //       CString strLcomCount;
                                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                            //       
                                            //       rData.Description = strTitle + strLcomCount;  
                                            //       nLcomCount++;
                                            rData.Description = strTitle;

                                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                            if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                            if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                            if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                            if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                            if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}

                                            if(m_nConstLoad!=0)
                                            {
                                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                CString strcEL;
                                                int nErection = 0;

                                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                {
                                                    strcEL = _T(""); nErection = 0;
                                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                    if(CheckCSEL(nErection, _T("D")))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DC")))
                                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("DW")))
                                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("W")))
                                                    {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("T")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    if(CheckCSEL(nErection, _T("TPG")))
                                                    {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                }

                                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                            }

                                            if(LoadCaseNo > 0)  
                                            {

                                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                else                                  rData.nActive = 1;  
                                                rData.nSubLcomType = 0;
                                                AddLcomBoth(BothD);
                                                Set_LoadComb4CivilName_proxy(rData, D_STR);
                                            }
                                        }
                                    }}}}}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_9_P(CString strCode,
                                        ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                        ArINT& arCSLoad,
                                        ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                        ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                        BOOL bState)

{
    if(m_bPNS10030BaseType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0) return;
    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 
                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);	
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);	

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);

                            }
                        }
                    }}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_9_PD(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arCSLoad,  ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);

                            }
                        }
                    }}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_9_PW(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030UniqType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0) return;
    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);


    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);

                            }
                        }
                    }}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_10_P(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030BaseType != 1) return;
    if( m_nDCount  == 0 && m_nDcCount  == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;

    if( m_nTCount  == 0 && m_nTpgCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dTFactor =0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nSmCountTemp   = max(m_nSmCount, 1);
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dTFactor   = 1.0 * 1.3; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int o = 0; o < nTCountTemp; o++) { 
                            for(int p = 0; p < nTpgCountTemp; p++) 
                            {
                                for(int k = 0; k < nSmCountTemp; k++) {
                                    CString strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                    strFixT.Format(_T("%d"), o+1);
                                    strFixTpg.Format(_T("%d"), p+1);
                                    strFixSm.Format(_T("%d"), k+1);
                                    rData.Initialize();  
                                    LoadCaseNo = 0;

                                    _LCOM_BOTH BothD; BothD.Initialize();
                                    int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nCrL=0, nShL=0;
                                    int nn=0;
                                    int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 
                                    for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                    if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                                    for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                    if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                    if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }		

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }

                                            if(CheckCSEL(nErection, _T("DW")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("T")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                            if(CheckCSEL(nErection, _T("TPG")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                        }
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                        }
                                    }

                                    //       CString strLcomCount;
                                    //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                    //       
                                    //       rData.Description = strTitle + strLcomCount;  
                                    //       nLcomCount++;
                                    rData.Description = strTitle;

                                    if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                    if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                    if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                    if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                    if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}


                                    if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                    if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                    if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                                    if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                    if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                    if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                    if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                    if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                    if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                    if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                    if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                    if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                    if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}


                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DW")))
                                            {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("T")))
                                            {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("TPG")))
                                            {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    }

                                    if(LoadCaseNo > 0)  
                                    {

                                        if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                        else                                  rData.nActive = 1;  
                                        rData.nSubLcomType = 0;
                                        AddLcomBoth(BothD);
                                        Set_LoadComb4CivilName_proxy(rData, D_STR);

                                    }
                                }
                            }}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_10_PD(CString strCode,
                                          ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                          ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                          ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                          BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if( m_nDCount  == 0 && m_nDcCount  == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;

    if( m_nTCount  == 0 && m_nTpgCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dTFactor =0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nSmCountTemp   = max(m_nSmCount, 1);
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 

    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent
    dTFactor   = 1.0 * 1.2; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int o = 0; o < nTCountTemp; o++) { 
                            for(int p = 0; p < nTpgCountTemp; p++) 
                            {
                                for(int k = 0; k < nSmCountTemp; k++) {
                                    CString strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                    strFixT.Format(_T("%d"), o+1);
                                    strFixTpg.Format(_T("%d"), p+1);
                                    strFixSm.Format(_T("%d"), k+1);
                                    rData.Initialize();  
                                    LoadCaseNo = 0;

                                    _LCOM_BOTH BothD; BothD.Initialize();
                                    int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0,nCrL=0, nShL=0;
                                    int nn=0;
                                    int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                    for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                    for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                    if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                                    for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                    if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                    if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);


                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }		

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }

                                            if(CheckCSEL(nErection, _T("DW")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("T")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                            if(CheckCSEL(nErection, _T("TPG")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                        }
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                        }
                                    }

                                    //       CString strLcomCount;
                                    //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                    //       
                                    //       rData.Description = strTitle + strLcomCount;  
                                    //       nLcomCount++;
                                    rData.Description = strTitle;

                                    if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                    if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                    if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                    if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                    if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                    if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                    if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                    if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                                    if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                    if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                    if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                    if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                    if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                    if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                    if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                    if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                    if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                    if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}


                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DW")))
                                            {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("T")))
                                            {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("TPG")))
                                            {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    }

                                    if(LoadCaseNo > 0)  
                                    {

                                        if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                        else                                  rData.nActive = 1;  
                                        rData.nSubLcomType = 0;
                                        AddLcomBoth(BothD);
                                        Set_LoadComb4CivilName_proxy(rData, D_STR);

                                    }
                                }
                            }}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_10_PW(CString strCode,
                                          ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                          ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                          ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                          BOOL bState)

{
    if(m_bPNS10030UniqType != 1) return;
    if( m_nDCount  == 0 && m_nDcCount  == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 
        && m_nCSCount == 0) return;

    if( m_nTCount  == 0 && m_nTpgCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dWFactor = 0.0, dTFactor =0.0, dIpFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;


    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent
    dTFactor   = 0.8 * 1.1; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int o = 0; o < nTCountTemp; o++) { 
                            for(int p = 0; p < nTpgCountTemp; p++) 
                            {
                                for(int k = 0; k < nSmCountTemp; k++) {
                                    CString strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                    strFixT.Format(_T("%d"), o+1);
                                    strFixTpg.Format(_T("%d"), p+1);
                                    strFixSm.Format(_T("%d"), k+1);
                                    rData.Initialize();  
                                    LoadCaseNo = 0;

                                    _LCOM_BOTH BothD; BothD.Initialize();
                                    int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nCrL=0, nShL=0;
                                    int nn=0;
                                    int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                    for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                    for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                    if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);

                                    for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                    if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                    if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);


                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }		

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }

                                            if(CheckCSEL(nErection, _T("DW")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("T")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                            if(CheckCSEL(nErection, _T("TPG")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                        }
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                        }
                                    }

                                    //       CString strLcomCount;
                                    //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                    //       
                                    //       rData.Description = strTitle + strLcomCount;  
                                    //       nLcomCount++;
                                    rData.Description = strTitle;

                                    if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                    if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                    if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                    if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                    if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                    if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                    if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                    if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                                    if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                    if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                    if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                    if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                    if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                    if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                    if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                    if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                    if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                    if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}


                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DW")))
                                            {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("T")))
                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("TPG")))
                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                    }

                                    if(LoadCaseNo > 0)  
                                    {

                                        if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                        else                                  rData.nActive = 1;  
                                        rData.nSubLcomType = 0;
                                        AddLcomBoth(BothD);
                                        Set_LoadComb4CivilName_proxy(rData, D_STR);

                                    }
                                }
                            }}}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_11_P(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,   ArINT& arStlLoad, ArUNT& arSmLoad,   ArUNT& arMLoad, ArINT& arLLoad,
                                         ArINT& arCfLoad, ArINT& arWLoad,  ArINT& arWlLoad,  ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad, ArINT& arIpLoad,   ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030BaseType != 1) return;
    if( m_nDCount   == 0 && m_nDcCount  == 0 && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount  == 0  && m_nEpCount ==0  && m_nStlCount == 0 
        && m_nCrlCount == 0 && m_nCSCount  == 0 ) return;

    if( m_nMCount  == 0 &&  m_nTCount  == 0 && m_nTpgCount == 0  && m_nWCount  == 0 
        && m_nWlCount == 0 &&  m_nCfCount == 0 && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dCfFactor =0.0, dWFactor=0.0, dTFactor =0.0, dCrlFactor = 0.0, dIpFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");


    _LCOM_IN InData;
    _LCOM_FD FData;
    _LCOM_RES ResData;

    _LCOM_UNIT UnitD;
    UnitD.Initialize();

    if(m_nMCount > 0)
    {
        UnitD.LcomK = 1;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("M");
        InData.arVariableLoadCase.Add(UnitD);

    }

    if(m_nCfCount > 0)
    {
        UnitD.LcomK = 2;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("CF");
        InData.arVariableLoadCase.Add(UnitD);

    }
    if(m_nTCount > 0) 
    {
        UnitD.LcomK = 3;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("T");
        InData.arVariableLoadCase.Add(UnitD);

    }
    if(m_nWCount > 0)
    {
        UnitD.LcomK = 4;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("W");
        InData.arVariableLoadCase.Add(UnitD);

    }
    if(m_nIpCount > 0)
    {
        UnitD.LcomK = 5;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("IP");
        InData.arVariableLoadCase.Add(UnitD);

    }

    switch (InData.arVariableLoadCase.GetSize())
    {
    case 1:
        FData.arCrticalF.SetSize(1);
        FData.arCrticalF[0] = 1.0;
        break;
    case 2:
        FData.arCrticalF.SetSize(2);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        break;
    case 3:
        FData.arCrticalF.SetSize(3);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        FData.arCrticalF[2] = 0.8;
        break;

    default:
        break;
    }


    if(InData.arVariableLoadCase.GetSize() > 3) 
    {
        FData.arCrticalF.SetSize(4);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        FData.arCrticalF[2] = 0.8;
        FData.arCrticalF[3] = 0.7;
    }

    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dCrlFactor = 1.0 * 1.3; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    _LCOM_IN arrResUnit;
    MakeLoadCombination4Var(arrResUnit, 0, InData, FData, ResData);

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int m = 0; m < nWCountTemp; m++) { 
                                for(int n = 0; n < nWlCountTemp; n++) { 
                                    for(int o = 0; o < nTCountTemp; o++) { 
                                        for(int p = 0; p < nTpgCountTemp; p++) 
                                        {
                                            for(int k = 0; k < nSmCountTemp; k++) {
                                                for(int nVL =0; nVL<ResData.arLcomD.GetSize(); nVL++)
                                                {
                                                    const _LCOM_IN& aUnit = ResData.arLcomD[nVL];

                                                    CString strFixM, strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                    strFixM.Format(_T("%d"), l+1);
                                                    strFixW.Format(_T("%d"), m/2+1);
                                                    strFixWl.Format(_T("%d"), n/2+1);
                                                    strFixT.Format(_T("%d"), o+1);
                                                    strFixTpg.Format(_T("%d"), p+1);
                                                    strFixSm.Format(_T("%d"), k+1);
                                                    rData.Initialize();  
                                                    LoadCaseNo = 0;

                                                    _LCOM_BOTH BothD; BothD.Initialize();
                                                    int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nWL=0, nWlL=0, nTL=0, nIpL=0, nErL=0, nCrL=0, nShL=0, nTpgL=0.0;
                                                    int nn=0, nLL=0, nCfL=0 ;
                                                    int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 
                                                    double dWF =0.0, dWlF = 0.0;
                                                    for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                    for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                    for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                    for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                    for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                                    for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                    if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                    for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                                    for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                    for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                    for(int j = 0; j < aUnit.arVariableLoadCase.GetSize(); ++j)
                                                    {
                                                        const _LCOM_UNIT& aa = aUnit.arVariableLoadCase[j];

                                                        switch (aa.LcomK)
                                                        {
                                                        case 1: // MV
                                                            {

                                                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), aa.dFactor, LoadCaseNo, rData, TRUE);
                                                                dMFactor = aa.dFactor;
                                                            }
                                                            break;
                                                        case 2: //CF
                                                            {
                                                                if(m_nMCount>0 || m_nLCount>0)
                                                                {
                                                                    for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                                    dCfFactor = aa.dFactor;
                                                                }
                                                            }
                                                            break;
                                                        case 3: //T
                                                            {
                                                                if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   aa.dFactor, LoadCaseNo, rData, 0);
                                                                if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), aa.dFactor, LoadCaseNo, rData, 0);
                                                                dTFactor = aa.dFactor;
                                                            }
                                                            break;
                                                        case 4: //W
                                                            {
                                                                dWF = (m%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                                dWlF = (n%2==0) ? aa.dFactor : -1.*aa.dFactor;
                                                                if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                                if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);
                                                            }
                                                            break;
                                                        case 5: //IP
                                                            {
                                                                for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                                dIpFactor = aa.dFactor;
                                                            }
                                                            break;
                                                        default:
                                                            break;
                                                        }
                                                    }

                                                    if(m_nConstLoad!=0)
                                                    {
                                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }		

                                                        CString strcEL;
                                                        int nErection = 0;

                                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                        {
                                                            strcEL = _T(""); nErection = 0;
                                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                            if(CheckCSEL(nErection, _T("D")))
                                                            {
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                            }
                                                            if(CheckCSEL(nErection, _T("DC")))
                                                            {
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                                (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                            }
                                                            if(CheckCSEL(nErection, _T("L")))
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                            if(CheckCSEL(nErection, _T("DW")))
                                                            {
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                                (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                            }
                                                            if(CheckCSEL(nErection, _T("W")))
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                            if(CheckCSEL(nErection, _T("T")))
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                            if(CheckCSEL(nErection, _T("TPG")))
                                                                Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                        }

                                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                        }
                                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                        }
                                                    }

                                                    //                       int nCNum = nVL+1;
                                                    //                       CString strCriticalNum;
                                                    //                       strCriticalNum.Format(_T("%d"), nCNum);
                                                    //                       CString strCritical;
                                                    //                       if(m == 0)  strCritical = _T("-(Case ") + strCriticalNum + _T(")");
                                                    //                       else        strCritical = _T("-(Case ") + strCriticalNum + _T("-1)");

                                                    rData.Description = strTitle;

                                                    if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                    if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                    if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                    if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                    if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                                    if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                                    if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                                    if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                                    if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                                    if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                    if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                    if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                    if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                    if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                    if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                    if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                    if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                    if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                                    if(nCfL> 0) { rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+"); }

                                                    if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                    if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                                    if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                    if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                                    if(nIpL> 0) { rData.Description += csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+"); }

                                                    if(m_nConstLoad!=0)
                                                    {
                                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                        CString strcEL;
                                                        int nErection = 0;

                                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                        {
                                                            strcEL = _T(""); nErection = 0;
                                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                            if(CheckCSEL(nErection, _T("D")))
                                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("DC")))
                                                            {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("L")))
                                                            {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("DW")))
                                                            {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("W")))
                                                            {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("T")))
                                                            {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                            if(CheckCSEL(nErection, _T("TPG")))
                                                            {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        }

                                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                        {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    }
                                                    //                     rData.Description += strCritical;

                                                    if(LoadCaseNo > 0)  
                                                    {

                                                        if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                        else                                  rData.nActive = 1;  
                                                        rData.nSubLcomType = 0;
                                                        AddLcomBoth(BothD);
                                                        Set_LoadComb4CivilName_proxy(rData, D_STR);

                                                    }
                                                }
                                            }
                                        }}}}}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_11_PD(CString strCode,
                                          ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,   ArINT& arStlLoad, ArUNT& arSmLoad,   ArUNT& arMLoad, ArINT& arLLoad,
                                          ArINT& arCfLoad, ArINT& arWLoad,  ArINT& arWlLoad,  ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad, ArINT& arIpLoad,   ArINT& arCSLoad,
                                          ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                          ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                          BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if( m_nDCount   == 0 && m_nDcCount  == 0 && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount  == 0  && m_nEpCount ==0  && m_nStlCount == 0 
        && m_nCrlCount == 0 && m_nCSCount  == 0 ) return;

    if( m_nMCount  == 0 &&   m_nTCount  == 0 && m_nTpgCount == 0  && m_nWCount  == 0 
        && m_nWlCount == 0 &&  m_nCfCount == 0 && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dCfFactor =0.0, dWFactor=0.0, dTFactor =0.0, dCrlFactor = 0.0, dIpFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent
    dCrlFactor = 1.0 * 1.2; //Permanent
    dMFactor   = 1.0 * 1.25; //Variable Load
    dCfFactor  = 1.0 * 1.25; //Variable Load
    dWFactor   = 1.0 * 1.2; //Variable Load
    dTFactor   = 1.0 * 1.2; //Variable Load
    dIpFactor  = 1.0 * 1.0; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int m = 0; m < nWCountTemp; m++) { 
                                for(int n = 0; n < nWlCountTemp; n++) { 
                                    for(int o = 0; o < nTCountTemp; o++) { 
                                        for(int p = 0; p < nTpgCountTemp; p++) 
                                        {
                                            for(int k = 0; k < nSmCountTemp; k++) {
                                                CString strFixM, strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                strFixM.Format(_T("%d"), l+1);
                                                strFixW.Format(_T("%d"), m/2+1);
                                                strFixWl.Format(_T("%d"), n/2+1);
                                                strFixT.Format(_T("%d"), o+1);
                                                strFixTpg.Format(_T("%d"), p+1);
                                                strFixSm.Format(_T("%d"), k+1);
                                                rData.Initialize();  
                                                LoadCaseNo = 0;

                                                _LCOM_BOTH BothD; BothD.Initialize();
                                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nWL=0, nWlL=0, nTL=0, nIpL=0, nErL=0, nCrL=0, nShL=0, nTpgL=0.0;
                                                int nn=0, nLL=0, nCfL=0 ;
                                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);

                                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);

                                                if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                                if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);

                                                double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                                double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                                if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }		

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("L")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("W")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("T")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                    }
                                                }

                                                //       CString strLcomCount;
                                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                                //       
                                                //       rData.Description = strTitle + strLcomCount;  
                                                //       nLcomCount++;
                                                rData.Description = strTitle;

                                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                                if(nCfL> 0) { rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+"); }

                                                if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                                if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                                if(nIpL> 0) { rData.Description += csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+"); }


                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("L")))
                                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("W")))
                                                        {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("T")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                }

                                                if(LoadCaseNo > 0)  
                                                {

                                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                    else                                  rData.nActive = 1;  
                                                    rData.nSubLcomType = 0;
                                                    AddLcomBoth(BothD);
                                                    Set_LoadComb4CivilName_proxy(rData, D_STR);


                                                }
                                            }
                                        }}}}}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_11_PW(CString strCode,
                                          ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,   ArINT& arStlLoad, ArUNT& arSmLoad,   ArUNT& arMLoad, ArINT& arLLoad,
                                          ArINT& arCfLoad, ArINT& arWLoad,  ArINT& arWlLoad,  ArINT& arTLoad,  ArINT& arTpgLoad, ArINT& arCrlLoad, ArINT& arIpLoad,   ArINT& arCSLoad,
                                          ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                          ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                          BOOL bState)

{
    if(m_bPNS10030UniqType != 1) return;
    if( m_nDCount   == 0 && m_nDcCount  == 0 && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount  == 0  && m_nEpCount ==0  && m_nStlCount == 0 
        && m_nCrlCount == 0 && m_nCSCount  == 0 ) return;

    if( m_nMCount  == 0 &&   m_nTCount  == 0 && m_nTpgCount == 0  && m_nWCount  == 0 
        && m_nWlCount == 0 &&  m_nCfCount == 0 && m_nIpCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dMFactor = 0.0, dCfFactor =0., dWFactor=0.0, dTFactor =0.0, dCrlFactor = 0.0, dIpFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1; 
    int nTCountTemp = max(m_nTCount, 1); 
    int nTpgCountTemp = max(m_nTpgCount, 1); 
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent
    dCrlFactor = 1.0 * 1.1; //Permanent
    dMFactor   = 0.8 * 1.15; //Variable Load
    dCfFactor  = 0.8 * 1.15; //Variable Load
    dWFactor   = 0.8 * 1.1; //Variable Load
    dTFactor   = 0.8 * 1.1; //Variable Load
    dIpFactor  = 0.8 * 1.0; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++) { 
                            for(int m = 0; m < nWCountTemp; m++) { 
                                for(int n = 0; n < nWlCountTemp; n++) { 
                                    for(int o = 0; o < nTCountTemp; o++) { 
                                        for(int p = 0; p < nTpgCountTemp; p++) 
                                        {
                                            for(int k = 0; k < nSmCountTemp; k++) {
                                                CString strFixM, strFixW, strFixWl, strFixT, strFixTpg, strFixSm, csPrefix = _T("");  
                                                strFixM.Format(_T("%d"), l+1);
                                                strFixW.Format(_T("%d"), m/2+1);
                                                strFixWl.Format(_T("%d"), n/2+1);
                                                strFixT.Format(_T("%d"), o+1);
                                                strFixTpg.Format(_T("%d"), p+1);
                                                strFixSm.Format(_T("%d"), k+1);
                                                rData.Initialize();  
                                                LoadCaseNo = 0;

                                                _LCOM_BOTH BothD; BothD.Initialize();
                                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nWL=0, nWlL=0, nTL=0, nIpL=0, nErL=0, nCrL=0, nShL=0, nTpgL=0.0;
                                                int nn=0, nLL=0, nCfL=0 ;
                                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);


                                                if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);
                                                if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTFactor, LoadCaseNo, rData, 0);
                                                double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                                double dWlF = (n%2==0) ? dWFactor : -1.*dWFactor;
                                                if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);
                                                if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2), dWlF, LoadCaseNo, rData, 0);

                                                for(i=0; i<m_nIpCount; i++) nIpL += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);


                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }		

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("L")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                        }
                                                        if(CheckCSEL(nErection, _T("W")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dWF, LoadCaseNo, rData, TRUE);
                                                        if(CheckCSEL(nErection, _T("T")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);  
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                            Set_CStageCase(arCSLoad.GetAt(nn), dTFactor, LoadCaseNo, rData, TRUE);
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                                    }
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {
                                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                                    }
                                                }

                                                //       CString strLcomCount;
                                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                                //       
                                                //       rData.Description = strTitle + strLcomCount;  
                                                //       nLcomCount++;
                                                rData.Description = strTitle;

                                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                                if(nCfL> 0) { rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+"); }

                                                if(nTL  > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
                                                if(nTpgL> 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}

                                                if(nWL  > 0) {if(dWF <0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                                                if(nWlL > 0) {if(dWlF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWlF) + _T("WL[") + strFixWl + _T("]"); csPrefix = _T("+");}

                                                if(nIpL> 0) { rData.Description += csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+"); }

                                                if(m_nConstLoad!=0)
                                                {
                                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                                    CString strcEL;
                                                    int nErection = 0;

                                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                                    {
                                                        strcEL = _T(""); nErection = 0;
                                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                                        if(CheckCSEL(nErection, _T("D")))
                                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DC")))
                                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("L")))
                                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("DW")))
                                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("W")))
                                                        {rData.Description += csPrefix + GetFactorString(dWF) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("T")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                        if(CheckCSEL(nErection, _T("TPG")))
                                                        {rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                                                    }

                                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                                }

                                                if(LoadCaseNo > 0)  
                                                {

                                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                                    else                                  rData.nActive = 1;  
                                                    rData.nSubLcomType = 0;
                                                    AddLcomBoth(BothD);
                                                    Set_LoadComb4CivilName_proxy(rData, D_STR);
                                                }
                                            }
                                        }}}}}}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_12_P(CString strCode,
                                         ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arErLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)

{
    if(m_bPNS10030BaseType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 &&
        m_nCSCount ) return;

    if(m_nErCount == 0 ) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dErFactor =0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);


    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dErFactor  = 1.0 * 1.5; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 
                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                            for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("ER")))
                                        Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                            if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("ER")))
                                    {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);

                            }
                        }
                    }}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_12_PD(CString strCode,
                                          ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                          ArINT& arErLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                          ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                          BOOL bState)

{
    if(m_bPNS10030AddType  != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 &&
        m_nCSCount ) return;

    if(m_nErCount == 0 ) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dErFactor =0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);


    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent
    dErFactor  = 1.0 * 1.25; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                            for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("ER")))
                                        Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                            if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("ER")))
                                    {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);


                            }
                        }
                    }}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_12_PW(CString strCode,
                                          ArINT& arDLoad,  ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad, ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                          ArINT& arErLoad, ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                          ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                          BOOL bState)

{
    if(m_bPNS10030UniqType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0 && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 && m_nStlCount ==0 &&
        m_nCSCount ) return;

    if(m_nErCount == 0 ) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dErFactor =0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);


    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent
    dErFactor  = 1.0 * 1.15; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;

                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0,  nWL=0, nWlL=0, nTL=0, nTpgL=0, nIpL=0, nErL=0, nCrL=0, nShL=0;
                            int nn=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                            for(i=0; i<m_nErCount; i++) nErL += Set_STLCIncludeCS(arErLoad.GetAt(i), dErFactor, LoadCaseNo, rData, 0);

                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("ER")))
                                        Set_CStageCase(arCSLoad.GetAt(nn), dErFactor, LoadCaseNo, rData, TRUE);
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            //       CString strLcomCount;
                            //       strLcomCount.Format(_T("%d:"), nLcomCount);
                            //       
                            //       rData.Description = strTitle + strLcomCount;  
                            //       nLcomCount++;
                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                            if(nErL>0){rData.Description +=csPrefix + GetFactorString(dErFactor) + _T("ER"); csPrefix = _T("+");}

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("ER")))
                                    {rData.Description += csPrefix + GetFactorString(dErFactor) + strcEL; csPrefix = _T("+");}
                                }

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 1;  
                                rData.nSubLcomType = 0;
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_STR);

                            }
                        }
                    }}}}}
}


void CLoadCombCtrl::SetCvl_PNS10030_13_P(CString strCode,
                                         ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCfLoad, ArINT& arBrkLoad, ArINT& arCrlLoad, ArINT& arCSLoad,
                                         ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                         BOOL bState)
{ 
    if(m_bPNS10030BaseType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0  && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0 && m_nCSCount == 0) return;

    if(m_nMCount  == 0 && m_nCfCount == 0 && m_nBrkCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dCfFactor = 0.0, dMFactor = 0.0, dBrkFactor=0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;


    strTitle = Get_PNS10030_Title(nState) + _T("Base.-");


    _LCOM_IN InData;
    _LCOM_FD FData;
    _LCOM_RES ResData;

    _LCOM_UNIT UnitD;
    UnitD.Initialize();

    if(m_nMCount > 0)
    {
        UnitD.LcomK = 1;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("M");
        InData.arVariableLoadCase.Add(UnitD);

    }

    if(m_nCfCount > 0)
    {
        UnitD.LcomK = 2;
        UnitD.dFactor = 1.5;
        UnitD.strLcomName = _T("CF");
        InData.arVariableLoadCase.Add(UnitD);

    }

    if(m_nBrkCount > 0)
    {
        UnitD.LcomK = 3;
        UnitD.dFactor = 1.3;
        UnitD.strLcomName = _T("BRK");
        InData.arVariableLoadCase.Add(UnitD);

    }


    switch (InData.arVariableLoadCase.GetSize())
    {
    case 1:
        FData.arCrticalF.SetSize(1);
        FData.arCrticalF[0] = 1.0;
        break;
    case 2:
        FData.arCrticalF.SetSize(2);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        break;
    case 3:
        FData.arCrticalF.SetSize(3);
        FData.arCrticalF[0] = 1.0;
        FData.arCrticalF[1] = 0.9;
        FData.arCrticalF[2] = 0.8;
        break;

    default:
        break;
    }

    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.3; //Permanent
    dCrlFactor = 1.0 * 1.3; //Permanent

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    _LCOM_IN arrResUnit;
    MakeLoadCombination4Var(arrResUnit, 0, InData, FData, ResData);

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                for(int nVL =0; nVL<ResData.arLcomD.GetSize(); nVL++)
                                {
                                    const _LCOM_IN& aUnit = ResData.arLcomD[nVL];
                                    CString strFixM, strFixSm, csPrefix = _T("");  
                                    strFixM.Format(_T("%d"), l+1);
                                    strFixSm.Format(_T("%d"), k+1);
                                    rData.Initialize();  
                                    LoadCaseNo = 0;

                                    _LCOM_BOTH BothD; BothD.Initialize();
                                    int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nBrkL=0, nCrL=0, nShL=0;
                                    int nn=0, nLL=0, nCfL=0 ;
                                    int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 
                                    for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                    for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }


                                    for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                    if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                    for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                    for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                    for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                    for(int j = 0; j < aUnit.arVariableLoadCase.GetSize(); ++j)
                                    {
                                        const _LCOM_UNIT& aa = aUnit.arVariableLoadCase[j];

                                        switch (aa.LcomK)
                                        {
                                        case 1: // MV
                                            {

                                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), aa.dFactor, LoadCaseNo, rData, TRUE);
                                                dMFactor = aa.dFactor;
                                            }
                                            break;
                                        case 2: //CF
                                            {
                                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                dCfFactor = aa.dFactor;
                                            }
                                            break;

                                        case 3: //BRK
                                            {
                                                for(i=0; i<m_nBrkCount; i++) nBrkL += Set_STLCIncludeCS(arBrkLoad.GetAt(i), aa.dFactor, LoadCaseNo, rData, 0);
                                                dBrkFactor = aa.dFactor;
                                            }
                                            break;
                                        default:
                                            break;
                                        }

                                    }
                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }		

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                                (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                                (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                            if(CheckCSEL(nErection, _T("L")))
                                                Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                            if(CheckCSEL(nErection, _T("DW")))
                                            {
                                                Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                                (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                            }
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                        }
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                        }
                                    }

                                    //               int nCNum = nVL+1;
                                    //               CString strCriticalNum;
                                    //               strCriticalNum.Format(_T("%d"), nCNum);
                                    //               CString strCritical = _T("-(Case ") + strCriticalNum + _T(")");

                                    rData.Description = strTitle;

                                    if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                    if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                    if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                    if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                    if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                    if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                    if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                    if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                    if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                    if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                    if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                    if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                    if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                    if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                    if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                    if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                    if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                    if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}

                                    if(nCfL > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}
                                    if(nBrkL > 0) {rData.Description += csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+");}

                                    if(m_nConstLoad!=0)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                        CString strcEL;
                                        int nErection = 0;

                                        for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                            if(CheckCSEL(nErection, _T("D")))
                                            {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DC")))
                                            {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("L")))
                                            {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                            if(CheckCSEL(nErection, _T("DW")))
                                            {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                        }

                                        if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                        if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    }
                                    //              rData.Description += strCritical;

                                    if(LoadCaseNo > 0)  
                                    {

                                        if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                        else                                  rData.nActive = 1;  
                                        rData.nSubLcomType = 0;
                                        AddLcomBoth(BothD);
                                        Set_LoadComb4CivilName_proxy(rData, D_STR);

                                    }
                                }
                            }
                        }}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_13_PD(CString strCode,
                                          ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                          ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCfLoad, ArINT& arBrkLoad, ArINT& arCrlLoad, ArINT& arCSLoad,
                                          ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                          ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                          BOOL bState)
{ 
    if(m_bPNS10030AddType  != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0  && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0 && m_nCSCount == 0) return;

    if(m_nMCount  == 0 && m_nCfCount == 0 && m_nBrkCount == 0) return;

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dCfFactor = 0.0, dMFactor = 0.0, dBrkFactor=0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;


    strTitle = Get_PNS10030_Title(nState) + _T("Add.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.2; //Permanent
    dCrlFactor = 1.0 * 1.2; //Permanent
    dCfFactor  = 1.0 * 1.25; //Variable Load
    dMFactor   = 1.0 * 1.25; //Variable Load
    dBrkFactor = 1.0 * 1.2; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString strFixM, strFixSm, csPrefix = _T("");  
                                strFixM.Format(_T("%d"), l+1);
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;

                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nBrkL=0, nCrL=0, nShL=0;
                                int nn=0, nLL=0, nCfL=0 ;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nBrkCount; i++) nBrkL += Set_STLCIncludeCS(arBrkLoad.GetAt(i), dBrkFactor, LoadCaseNo, rData, 0);

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("L")))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                //       CString strLcomCount;
                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                //       
                                //       rData.Description = strTitle + strLcomCount;  
                                //       nLcomCount++;
                                rData.Description = strTitle;

                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                if(nCfL > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}
                                if(nBrkL > 0) {rData.Description += csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+");}


                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("L")))
                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 1;  
                                    rData.nSubLcomType = 0;
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_STR);

                                }
                            }
                        }}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_13_PW(CString strCode,
                                          ArINT& arDLoad, ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                          ArUNT& arMLoad, ArINT& arLLoad,  ArINT& arCfLoad, ArINT& arBrkLoad, ArINT& arCrlLoad, ArINT& arCSLoad,
                                          ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                          ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,
                                          BOOL bState)
{ 
    if(m_bPNS10030UniqType != 1) return;
    if(m_nDCount  == 0 && m_nDcCount == 0  && m_nDwCount == 0  && m_nPsCount == 0  && m_nWpCount == 0 && m_nEpCount ==0 &&
        m_nStlCount ==0 && m_nCrlCount == 0 && m_nCSCount == 0) return;

    if(m_nMCount  == 0 && m_nCfCount == 0 && m_nBrkCount == 0) return;


    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor = 0.0, dStlFactor = 0.0, dCfFactor = 0.0, dMFactor = 0.0, dBrkFactor=0.0, dCrlFactor = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);
    int nLcomCount = 0;

    int LoadCaseNo;
    T_LCOM_D rData;


    strTitle = Get_PNS10030_Title(nState) + _T("Uniq.-");


    // Combination Factor * Reliability Factor
    dEpFactor  = 1.0 * 1.1; //Permanent
    dStlFactor = 1.0 * 1.1; //Permanent
    dCrlFactor = 1.0 * 1.1; //Permanent
    dCfFactor  = 0.8 * 1.15; //Variable Load
    dMFactor   = 0.8 * 1.15; //Variable Load
    dBrkFactor = 0.8 * 1.1; //Variable Load

    dEANNFactor = 1.0 * 1.1;    //Permanent
    dEANCFactor = 1.0 * 1.25;   //Permanent
    dEAMNFactor = 1.0 * 1.25;   //Permanent
    dEAMCFactor = 1.0 * 1.35;   //Permanent
    dEPNNFactor = 1.0 * 0.9;    //Permanent
    dEPNCFactor = 1.0 * 0.8;    //Permanent
    dEPMNFactor = 1.0 * 0.85;   //Permanent
    dEPMCFactor = 1.0 * 0.7;    //Permanent
    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l = 0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString strFixM, strFixSm, csPrefix = _T("");  
                                strFixM.Format(_T("%d"), l+1);
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;

                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrlL=0, nBrkL=0, nCrL=0, nShL=0;
                                int nn=0, nLL=0, nCfL=0 ;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCrlCount; i++) nCrlL += Set_STLCIncludeCS(arCrlLoad.GetAt(i), dCrlFactor, LoadCaseNo, rData, 0);

                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nBrkCount; i++) nBrkL += Set_STLCIncludeCS(arBrkLoad.GetAt(i), dBrkFactor, LoadCaseNo, rData, 0);

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("L")))
                                            Set_CStageCase(arCSLoad.GetAt(nn), dMFactor, LoadCaseNo, rData, TRUE);

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                //       CString strLcomCount;
                                //       strLcomCount.Format(_T("%d:"), nLcomCount);
                                //       
                                //       rData.Description = strTitle + strLcomCount;  
                                //       nLcomCount++;
                                rData.Description = strTitle;

                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nCrlL > 0) {rData.Description += csPrefix + GetFactorString(dCrlFactor) + _T("CRL"); csPrefix = _T("+");}

                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");  csPrefix = _T("+");}
                                if(nCfL > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}
                                if(nBrkL > 0) {rData.Description += csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+");}


                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("L")))
                                        {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 1;  
                                    rData.nSubLcomType = 0;
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_STR);

                                }
                            }
                        }}}}}}
}


void CLoadCombCtrl::SetCvl_PNS10030_SLS1(CString strCode,
                                         ArINT& arDLoad,   ArINT& arDcLoad, ArINT& arDwLoad, ArINT& arPsLoad,  ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArUNT& arMLoad,
                                         ArINT& arCSLoad, ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad, BOOL bState)
{

    if(m_nMCount == 0) return;   //Moving Load

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0, dMFactor    = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;

    int nMCount = max(m_nMCount, 1);
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Basic.-");


    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.0; //Permanent Load
    dEpFactor   = 1.0 * 1.0; //Permanent Load
    dMFactor    = 1.0 * 1.0; //Most Critical Load

    dEANNFactor = 1.0 * 1.0;   //Permanent
    dEANCFactor = 1.0 * 1.0;   //Permanent
    dEAMNFactor = 1.0 * 1.0;   //Permanent
    dEAMCFactor = 1.0 * 1.0;   //Permanent
    dEPNNFactor = 1.0 * 1.0;   //Permanent
    dEPNCFactor = 1.0 * 1.0;   //Permanent
    dEPMNFactor = 1.0 * 1.0;   //Permanent
    dEPMCFactor = 1.0 * 1.0;   //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int l =0; l < nMCount; l++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString  strFixM, strFixSm, csPrefix = _T("");  
                                strFixSm.Format(_T("%d"), k+1);
                                strFixM.Format(_T("%d"), l+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;
                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrL=0, nShL=0;
                                int nn=0, nML=0, nCfL=0;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l), dMFactor, LoadCaseNo, rData, TRUE);
                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(!bState)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                rData.Description = strTitle;

                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}


                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM   + _T("]");  csPrefix = _T("+");}

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {
                                    // Service       

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 2;  
                                    rData.nSubLcomType = 0; 
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_SER);

                                }
                            }
                        }}}}}
    }
}
void CLoadCombCtrl::SetCvl_PNS10030_SLS2(CString strCode,
                                         ArINT& arDLoad,    ArINT& arDcLoad,   ArINT& arDwLoad,   ArINT& arPsLoad,   ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArINT& arCfLoad,
                                         ArINT& arCSLoad,   ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad, BOOL bState)
{

    if(m_nCfCount == 0) return;   //Cf

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0, dCfFactor   = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Basic.-");


    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.0; //Permanent Load
    dEpFactor   = 1.0 * 1.0; //Permanent Load
    dCfFactor   = 1.0 * 1.0; // Most Critical Load

    dEANNFactor = 1.0 * 1.0;   //Permanent
    dEANCFactor = 1.0 * 1.0;   //Permanent
    dEAMNFactor = 1.0 * 1.0;   //Permanent
    dEAMCFactor = 1.0 * 1.0;   //Permanent
    dEPNNFactor = 1.0 * 1.0;   //Permanent
    dEPNCFactor = 1.0 * 1.0;   //Permanent
    dEPMNFactor = 1.0 * 1.0;   //Permanent
    dEPMCFactor = 1.0 * 1.0;   //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;
                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nCfL=0, nStlL=0, nCrL=0, nShL=0;
                            int nn=0, nML=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            for(i=0; i<m_nCfCount; i++) nCfL += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }
                                if(!bState)
                                {
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }
                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(nCfL>0){rData.Description +=csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}               

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }
                                if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {
                                // Service       

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 2;  
                                rData.nSubLcomType = 0; 
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_SER);

                            }
                        }
                    }}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_SLS3(CString strCode,
                                         ArINT& arDLoad,    ArINT& arDcLoad,   ArINT& arDwLoad,   ArINT& arPsLoad,   ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArINT& arTLoad,
                                         ArINT& arCSLoad,   ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,  BOOL bState)
{

    if(m_nTCount == 0) return;   //T

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0, dTFactor    = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;

    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Basic.-");


    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.0; //Permanent Load
    dEpFactor   = 1.0 * 1.0; //Permanent Load
    dTFactor  = 1.0 * 1.0; // Most Critical Load

    dEANNFactor = 1.0 * 1.0;   //Permanent
    dEANCFactor = 1.0 * 1.0;   //Permanent
    dEAMNFactor = 1.0 * 1.0;   //Permanent
    dEAMCFactor = 1.0 * 1.0;   //Permanent
    dEPNNFactor = 1.0 * 1.0;   //Permanent
    dEPNCFactor = 1.0 * 1.0;   //Permanent
    dEPMNFactor = 1.0 * 1.0;   //Permanent
    dEPMCFactor = 1.0 * 1.0;   //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int o = 0; o < m_nTCount; o++) { // MQC.15906 Seungjun SLS ¿ÂµµÇÏÁß ÇÏ³ª¾¿ ÀçÇÏ.
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString  strFixSm, csPrefix = _T("");  
                                strFixSm.Format(_T("%d"), k+1);

                                // MQC.15906 Seungjun SLS ¿ÂµµÇÏÁß ÇÏ³ª¾¿ ÀçÇÏ.
                                CString  strFixT;
                                strFixT.Format(_T("%d"), o+1);

                                rData.Initialize();  
                                LoadCaseNo = 0;
                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0,  nStlL=0,  nTL=0, nCrL=0, nShL=0;
                                int nn=0, nML=0, nCfL=0;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                for(i=0; i<m_nEpCount; i++) nEpL    += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL  += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nTCount > 0)   nTL   += Set_STLCIncludeCS(arTLoad.GetAt(o),   dTFactor, LoadCaseNo, rData, 0);// MQC.15906 Seungjun SLS ¿ÂµµÇÏÁß ÇÏ³ª¾¿ ÀçÇÏ.

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(!bState)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                rData.Description = strTitle;

                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(nTL>0){rData.Description +=csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}// MQC.15906 Seungjun SLS ¿ÂµµÇÏÁß ÇÏ³ª¾¿ ÀçÇÏ.

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {
                                    // Service       

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 2;  
                                    rData.nSubLcomType = 0; 
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_SER);

                                }
                            }
                        }}}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_SLS4(CString strCode,
                                         ArINT& arDLoad,    ArINT& arDcLoad,   ArINT& arDwLoad,   ArINT& arPsLoad,   ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArINT& arTpgLoad,
                                         ArINT& arCSLoad,   ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad, BOOL bState)
{

    if(m_nTpgCount == 0) return;   //Tpg

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0, dTpgFactor  = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Basic.-");


    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.0; //Permanent Load
    dEpFactor   = 1.0 * 1.0; //Permanent Load
    dTpgFactor  = 1.0 * 1.0; // Most Critical Load

    dEANNFactor = 1.0 * 1.0;   //Permanent
    dEANCFactor = 1.0 * 1.0;   //Permanent
    dEAMNFactor = 1.0 * 1.0;   //Permanent
    dEAMCFactor = 1.0 * 1.0;   //Permanent
    dEPNNFactor = 1.0 * 1.0;   //Permanent
    dEPNCFactor = 1.0 * 1.0;   //Permanent
    dEPMNFactor = 1.0 * 1.0;   //Permanent
    dEPMCFactor = 1.0 * 1.0;   //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int p = 0; p < m_nTpgCount; p++) {// MQC.15906 Seungjun SLS ¿ÂµµÇÏÁß ÇÏ³ª¾¿ ÀçÇÏ.
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString  strFixSm, csPrefix = _T("");  
                                strFixSm.Format(_T("%d"), k+1);

                                // MQC.15906 Seungjun SLS ¿ÂµµÇÏÁß ÇÏ³ª¾¿ ÀçÇÏ.
                                CString  strFixTpg;
                                strFixTpg.Format(_T("%d"), p+1);

                                rData.Initialize();  
                                LoadCaseNo = 0;
                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0,  nStlL=0,  nTpgL=0,  nCrL=0, nShL=0;
                                int nn=0, nML=0, nCfL=0;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                if(m_nTpgCount > 0) nTpgL += Set_STLCIncludeCS(arTpgLoad.GetAt(p), dTpgFactor, LoadCaseNo, rData, 0);// MQC.15906 Seungjun SLS ¿ÂµµÇÏÁß ÇÏ³ª¾¿ ÀçÇÏ.

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(!bState)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                rData.Description = strTitle;

                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(nTpgL>0){rData.Description +=csPrefix + GetFactorString(dTpgFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}// MQC.15906 Seungjun SLS ¿ÂµµÇÏÁß ÇÏ³ª¾¿ ÀçÇÏ.

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {
                                    // Service       

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 2;  
                                    rData.nSubLcomType = 0; 
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_SER);

                                }
                            }
                        }}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_SLS5(CString strCode,
                                         ArINT& arDLoad,    ArINT& arDcLoad,   ArINT& arDwLoad,   ArINT& arPsLoad,   ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArINT& arWLoad,
                                         ArINT& arCSLoad,   ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad, BOOL bState)
{

    if(m_nWCount == 0) return;   //W

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0, dWFactor    = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Basic.-");

    int nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1; 
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1;

    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.3; //Permanent Load
    dEpFactor   = 1.0 * 1.1; //Permanent Load
    dWFactor  = 1.0 * 1.0; // Most Critical Load

    dEANNFactor = 1.0 * 1.0;   //Permanent
    dEANCFactor = 1.0 * 1.0;   //Permanent
    dEAMNFactor = 1.0 * 1.0;   //Permanent
    dEAMCFactor = 1.0 * 1.0;   //Permanent
    dEPNNFactor = 1.0 * 1.0;   //Permanent
    dEPNCFactor = 1.0 * 1.0;   //Permanent
    dEPMNFactor = 1.0 * 1.0;   //Permanent
    dEPMCFactor = 1.0 * 1.0;   //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m  =0 ; m  < nWCountTemp;  m++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString  strFixSm, csPrefix = _T("");  
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;
                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nWL=0, nStlL=0, nCrL=0, nShL=0;
                                int nn=0, nML=0, nCfL=0;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                for(i=0; i<m_nEpCount; i++) nEpL   += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                double dWF = (m%2==0) ? dWFactor : -1.*dWFactor;
                                if(m_nWCount>0)  nWL  += Set_STLCIncludeCS(arWLoad.GetAt(m/2), dWF,  LoadCaseNo, rData, 0);

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(!bState)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                rData.Description = strTitle;

                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(nWL>0){rData.Description +=csPrefix + GetFactorString(dWF) + _T("W"); csPrefix = _T("+");}               

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {
                                    // Service       

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 2;  
                                    rData.nSubLcomType = 0; 
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_SER);

                                }
                            }
                        }}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_SLS6(CString strCode,
                                         ArINT& arDLoad,    ArINT& arDcLoad,   ArINT& arDwLoad,   ArINT& arPsLoad,   ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArINT& arWlLoad,
                                         ArINT& arCSLoad,   ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad, BOOL bState)
{

    if(m_nWlCount == 0) return;   //Wl

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0, dWlFactor   = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Basic.-");
    int nWlCountTemp = (m_nWlCount>0) ? m_nWlCount*2 : 1;

    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.3; //Permanent Load
    dEpFactor   = 1.0 * 1.1; //Permanent Load
    dWlFactor  = 1.0 * 1.0; // Most Critical Load

    dEANNFactor = 1.0 * 1.0;  //Permanent
    dEANCFactor = 1.0 * 1.0;  //Permanent
    dEAMNFactor = 1.0 * 1.0;  //Permanent
    dEAMCFactor = 1.0 * 1.0;  //Permanent
    dEPNNFactor = 1.0 * 1.0;  //Permanent
    dEPNCFactor = 1.0 * 1.0;  //Permanent
    dEPMNFactor = 1.0 * 1.0;  //Permanent
    dEPMCFactor = 1.0 * 1.0;  //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int m  = 0; m  < nWlCountTemp;  m++)
                        {
                            for(int k = 0; k < nSmCountTemp; k++) {
                                CString  strFixSm, csPrefix = _T("");  
                                strFixSm.Format(_T("%d"), k+1);
                                rData.Initialize();  
                                LoadCaseNo = 0;
                                _LCOM_BOTH BothD; BothD.Initialize();
                                int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0,  nStlL=0, nWlL=0, nCrL=0, nShL=0;
                                int nn=0, nML=0, nCfL=0;
                                int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                                for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                                for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                                for(i=0; i<m_nEpCount; i++) nEpL   += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                                if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                                for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                                for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                                double dWlF = (m%2==0) ? dWlFactor : -1.*dWlFactor;
                                if(m_nWlCount>0) nWlL += Set_STLCIncludeCS(arWlLoad.GetAt(m/2), dWlF, LoadCaseNo, rData, 0);

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }		

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                            (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                            (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }

                                        if(CheckCSEL(nErection, _T("DW")))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                            (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(!bState)
                                    {
                                        if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                        {
                                            Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                            (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                        }
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                    }
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                    }
                                }

                                rData.Description = strTitle;

                                if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                                if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                                if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                                if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                                if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                                if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                                if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                                if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                                if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                                if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                                if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                                if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                                if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                                if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                                if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                                if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                                if(nWlL>0){rData.Description +=csPrefix + GetFactorString(dWlF) + _T("WL"); csPrefix = _T("+");}               

                                if(m_nConstLoad!=0)
                                {
                                    if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                    CString strcEL;
                                    int nErection = 0;

                                    for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                    {
                                        strcEL = _T(""); nErection = 0;
                                        if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                        if(CheckCSEL(nErection, _T("D")))
                                        {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DC")))
                                        {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                        if(CheckCSEL(nErection, _T("DW")))
                                        {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                    }
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                    if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                    if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                                }

                                if(LoadCaseNo > 0)  
                                {
                                    // Service       

                                    if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                    else                                  rData.nActive = 2;  
                                    rData.nSubLcomType = 0; 
                                    AddLcomBoth(BothD);
                                    Set_LoadComb4CivilName_proxy(rData, D_SER);

                                }
                            }
                        }}}}}}
}
void CLoadCombCtrl::SetCvl_PNS10030_SLS7(CString strCode,
                                         ArINT& arDLoad,    ArINT& arDcLoad,   ArINT& arDwLoad,   ArINT& arPsLoad,   ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArINT& arBrkLoad,
                                         ArINT& arCSLoad,   ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad, BOOL bState)
{

    if(m_nBrkCount == 0) return;   //BRK

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0, dBrkFactor  = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Basic.-");


    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.0; //Permanent Load
    dEpFactor   = 1.0 * 1.0; //Permanent Load
    dBrkFactor  = 1.0 * 1.0; // Most Critical Load

    dEANNFactor = 1.0 * 1.0;   //Permanent
    dEANCFactor = 1.0 * 1.0;   //Permanent
    dEAMNFactor = 1.0 * 1.0;   //Permanent
    dEAMCFactor = 1.0 * 1.0;   //Permanent
    dEPNNFactor = 1.0 * 1.0;   //Permanent
    dEPNCFactor = 1.0 * 1.0;   //Permanent
    dEPMNFactor = 1.0 * 1.0;   //Permanent
    dEPMCFactor = 1.0 * 1.0;   //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;
                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nBrkL=0, nStlL=0, nCrL=0, nShL=0;
                            int nn=0, nML=0, nCfL=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            for(i=0; i<m_nBrkCount; i++) nBrkL += Set_STLCIncludeCS(arBrkLoad.GetAt(i), dBrkFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }
                                if(!bState)
                                {
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }
                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(nBrkL>0){rData.Description +=csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+");}               

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }
                                if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {
                                // Service       

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 2;  
                                rData.nSubLcomType = 0; 
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_SER);

                            }
                        }
                    }}}}}
}


void CLoadCombCtrl::SetCvl_PNS10030_SLS8(CString strCode,
                                         ArINT& arDLoad,    ArINT& arDcLoad,   ArINT& arDwLoad,   ArINT& arPsLoad,   ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad,  ArINT& arIpLoad,
                                         ArINT& arCSLoad,   ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad,  BOOL bState)
{

    if(m_nIpCount == 0) return;   //Ip

    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0, dIpFactor   = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Basic.-");


    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.0; //Permanent Load
    dEpFactor   = 1.0 * 1.0; //Permanent Load
    dIpFactor   = 1.0 * 1.0; // Most Critical Load

    dEANNFactor = 1.0 * 1.0;   //Permanent
    dEANCFactor = 1.0 * 1.0;   //Permanent
    dEAMNFactor = 1.0 * 1.0;   //Permanent
    dEAMCFactor = 1.0 * 1.0;   //Permanent
    dEPNNFactor = 1.0 * 1.0;   //Permanent
    dEPNCFactor = 1.0 * 1.0;   //Permanent
    dEPMNFactor = 1.0 * 1.0;   //Permanent
    dEPMCFactor = 1.0 * 1.0;   //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;
                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nIpL=0, nCrL=0, nShL=0;
                            int nn=0, nML=0, nCfL=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL   += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            for(i=0; i<m_nIpCount; i++) nIpL   += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }
                                if(!bState)
                                {
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }
                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  

                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(nIpL>0){rData.Description +=csPrefix + GetFactorString(dIpFactor) + _T("IP"); csPrefix = _T("+");}               

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }
                                if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {
                                // Service       

                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 2;  
                                rData.nSubLcomType = 0; 
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_SER);

                            }
                        }
                    }}}}}
}

void CLoadCombCtrl::SetCvl_PNS10030_SLS9(CString strCode,
                                         ArINT& arDLoad,    ArINT& arDcLoad,   ArINT& arDwLoad,   ArINT& arPsLoad,   ArINT& arWpLoad,  ArINT& arEpLoad,  ArINT& arStlLoad, ArUNT& arSmLoad, 
                                         ArINT& arCSLoad,   ArINT& arEANNLoad, ArINT& arEANCLoad, ArINT& arEAMNLoad, ArINT& arEAMCLoad, 
                                         ArINT& arEPNNLoad, ArINT& arEPNCLoad, ArINT& arEPMNLoad, ArINT& arEPMCLoad, BOOL bState)
{
    //Long-term Load
    CString sDFac[2], sDcFac[2], sDwFac[2], sPsFac[2], sWpFac[2];
    double  dDFac[2], dDcFac[2], dDwFac[2], dPsFac[2], dWpFac[2];
    Get_PNS10030_Factor(sDFac[0],  sDFac[1],  sDcFac[0],  sDcFac[1], sDwFac[0],  sDwFac[1],  sPsFac[0], sPsFac[1],  sWpFac[0],  sWpFac[1],
        dDFac[0],  dDFac[1],  dDcFac[0],  dDcFac[1], dDwFac[0],  dDwFac[1],  dPsFac[0], dPsFac[1],  dWpFac[0],  dWpFac[1], bState);


    double dEpFactor   = 0.0, dStlFactor  = 0.0,
        dEANNFactor = 0.0, dEANCFactor = 0.0, dEAMNFactor = 0.0, dEAMCFactor = 0.0, 
        dEPNNFactor = 0.0, dEPNCFactor = 0.0, dEPMNFactor = 0.0, dEPMCFactor = 0.0 ;


    CString strTitle = _T("");
    int nState = 0;         // 0:ULS 1:SLS
    if(bState) nState = 0;
    else        nState = 1;
    int nSmCountTemp   = max(m_nSmCount, 1);
    int LoadCaseNo;
    T_LCOM_D rData;

    strTitle = Get_PNS10030_Title(nState) + _T("Long-Term.-");


    // Combination Factor * Reliability Factor
    dStlFactor  = 1.0 * 1.0; //Permanent Load
    dEpFactor   = 1.0 * 1.0; //Permanent Load

    dEANNFactor = 1.0 * 1.0;   //Permanent
    dEANCFactor = 1.0 * 1.0;   //Permanent
    dEAMNFactor = 1.0 * 1.0;   //Permanent
    dEAMCFactor = 1.0 * 1.0;   //Permanent
    dEPNNFactor = 1.0 * 1.0;   //Permanent
    dEPNCFactor = 1.0 * 1.0;   //Permanent
    dEPMNFactor = 1.0 * 1.0;   //Permanent
    dEPMCFactor = 1.0 * 1.0;   //Permanent

    for(int nD    = 0; nD     < m_nPNS10030DNum;    nD++) {
        for(int nDc   = 0; nDc    < m_nPNS10030DCNum;   nDc++){
            for(int nDw   = 0; nDw    < m_nPNS10030DWNum;   nDw++){
                for(int nPs   = 0; nPs    < m_nPNS10030PSNum;   nPs++){
                    for(int nWp   = 0; nWp    < m_nPNS10030WPNum;   nWp++)  
                    {
                        for(int k = 0; k < nSmCountTemp; k++) {
                            CString  strFixSm, csPrefix = _T("");  
                            strFixSm.Format(_T("%d"), k+1);
                            rData.Initialize();  
                            LoadCaseNo = 0;
                            _LCOM_BOTH BothD; BothD.Initialize();
                            int i=0, nDL=0, nDcL=0, nDwL=0, nWpL=0, nPsL=0, nEpL=0, nStlL=0, nCrL=0, nShL=0;
                            int nn=0, nML=0, nCfL=0;
                            int nEANNL = 0, nEANCL = 0, nEAMNL = 0, nEAMCL = 0, nEPNNL = 0, nEPNCL = 0, nEPMNL = 0, nEPMCL = 0; 

                            for(i=0; i<m_nDCount; i++)   { nDL   += Set_STLCIncludeCS(arDLoad.GetAt(i),   dDFac[nD],       LoadCaseNo, rData, D_SGLD_DL_CVL); (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDcCount; i++)  { nDcL  += Set_STLCIncludeCS(arDcLoad.GetAt(i),  dDcFac[nDc],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDc==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nDwCount; i++)  { nDwL  += Set_STLCIncludeCS(arDwLoad.GetAt(i),  dDwFac[nDw],     LoadCaseNo, rData, D_SGLD_DL_CVL); (nDw==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nPsCount; i++)  { nPsL  += Set_STLCIncludeCS(arPsLoad.GetAt(i),  dPsFac[nPs],     LoadCaseNo, rData, 0); (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }
                            for(i=0; i<m_nWpCount; i++)  { nWpL  += Set_STLCIncludeCS(arWpLoad.GetAt(i),  dWpFac[nWp],     LoadCaseNo, rData, 0); (nWp==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0; }

                            for(i=0; i<m_nEpCount; i++) nEpL    += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nStlCount; i++) nStlL  += Set_STLCIncludeCS(arStlLoad.GetAt(i), dStlFactor, LoadCaseNo, rData, 0);
                            if(m_nSmCount > 0)                    Set_SettleCase(arSmLoad.GetAt(k),  dStlFactor, LoadCaseNo, rData, TRUE);
                            for(i=0; i<m_nEANNCount; i++) nEANNL += Set_STLCIncludeCS(arEANNLoad.GetAt(i), dEANNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEANCCount; i++) nEANCL += Set_STLCIncludeCS(arEANCLoad.GetAt(i), dEANCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMNCount; i++) nEAMNL += Set_STLCIncludeCS(arEAMNLoad.GetAt(i), dEAMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEAMCCount; i++) nEAMCL += Set_STLCIncludeCS(arEAMCLoad.GetAt(i), dEAMCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNNCount; i++) nEPNNL += Set_STLCIncludeCS(arEPNNLoad.GetAt(i), dEPNNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPNCCount; i++) nEPNCL += Set_STLCIncludeCS(arEPNCLoad.GetAt(i), dEPNCFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMNCount; i++) nEPMNL += Set_STLCIncludeCS(arEPMNLoad.GetAt(i), dEPMNFactor, LoadCaseNo, rData, 0);
                            for(i=0; i<m_nEPMCCount; i++) nEPMCL += Set_STLCIncludeCS(arEPMCLoad.GetAt(i), dEPMCFactor, LoadCaseNo, rData, 0);

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                    (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }		

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nD], LoadCaseNo, rData, TRUE);
                                        (nD==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDcFac[nDc], LoadCaseNo, rData, TRUE);
                                        (nDc==1)    ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }

                                    if(CheckCSEL(nErection, _T("DW")))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dDwFac[nDw], LoadCaseNo, rData, TRUE);
                                        (nDw==1)  ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }
                                if(!bState)
                                {
                                    if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                    {
                                        Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                        (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                    }
                                }
                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dPsFac[nPs], LoadCaseNo, rData, TRUE);
                                    (nPs==1)   ? BothD.nBoth[LoadCaseNo]=1 : BothD.nBoth[LoadCaseNo] = 0;
                                }
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nCrL], LoadCaseNo, rData, TRUE);
                                }
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {
                                    Set_CStageCase(arCSLoad.GetAt(nn), dDFac[nShL], LoadCaseNo, rData, TRUE);
                                }
                            }

                            rData.Description = strTitle;

                            if(nDL  > 0)   {rData.Description += csPrefix + GetFactorString(dDFac[nD])     + _T("D");   csPrefix = _T("+");}
                            if(nDcL > 0)   {rData.Description += csPrefix + GetFactorString(dDcFac[nDc])   + _T("DC");  csPrefix = _T("+");}
                            if(nDwL > 0)   {rData.Description += csPrefix + GetFactorString(dDwFac[nDw])   + _T("DW");  csPrefix = _T("+");}
                            if(nPsL > 0)   {rData.Description += csPrefix + GetFactorString(dPsFac[nPs])   + _T("PS");  csPrefix = _T("+");}
                            if(nWpL > 0)   {rData.Description += csPrefix + GetFactorString(dWpFac[nWp])   + _T("WP");  csPrefix = _T("+");}

                            if(nEpL>0){rData.Description +=csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
                            if(nStlL>0){rData.Description +=csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
                            if(m_nSmCount>0) {rData.Description += csPrefix + GetFactorString(dStlFactor)    + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}  
                            if(nEANNL > 0) {rData.Description += csPrefix + GetFactorString(dEANNFactor) + _T("EANN"); csPrefix = _T("+");}
                            if(nEANCL > 0) {rData.Description += csPrefix + GetFactorString(dEANCFactor) + _T("EANC"); csPrefix = _T("+");}
                            if(nEAMNL > 0) {rData.Description += csPrefix + GetFactorString(dEAMNFactor) + _T("EAMN"); csPrefix = _T("+");}
                            if(nEAMCL > 0) {rData.Description += csPrefix + GetFactorString(dEAMCFactor) + _T("EAMC"); csPrefix = _T("+");}
                            if(nEPNNL > 0) {rData.Description += csPrefix + GetFactorString(dEPNNFactor) + _T("EPNN"); csPrefix = _T("+");}
                            if(nEPNCL > 0) {rData.Description += csPrefix + GetFactorString(dEPNCFactor) + _T("EPNC"); csPrefix = _T("+");}
                            if(nEPMNL > 0) {rData.Description += csPrefix + GetFactorString(dEPMNFactor) + _T("EPMN"); csPrefix = _T("+");}
                            if(nEPMCL > 0) {rData.Description += csPrefix + GetFactorString(dEPMCFactor) + _T("EPMC"); csPrefix = _T("+");}

                            if(m_nConstLoad!=0)
                            {
                                if(CheckCS_SgldK(D_SGLD_DL_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + _T("(cD)"); csPrefix = _T("+");}

                                CString strcEL;
                                int nErection = 0;

                                for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                                    if(CheckCSEL(nErection, _T("D")))
                                    {rData.Description += csPrefix + GetFactorString(dDFac[nD]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DC")))
                                    {rData.Description += csPrefix + GetFactorString(dDcFac[nDc]) + strcEL; csPrefix = _T("+");}
                                    if(CheckCSEL(nErection, _T("DW")))
                                    {rData.Description += csPrefix + GetFactorString(dDwFac[nDw]) + strcEL; csPrefix = _T("+");}
                                }
                                if(CheckCS_SgldK(D_SGLD_TP_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTP)"); csPrefix = _T("+");}

                                if(CheckCS_SgldK(D_SGLD_TS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dPsFac[nPs]) + _T("(cTS)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_CS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nCrL]) + _T("(cCR)"); csPrefix = _T("+");}
                                if(CheckCS_SgldK(D_SGLD_SS_CVL, nn))
                                {rData.Description += csPrefix + GetFactorString(dDFac[nShL]) + _T("(cCR)"); csPrefix = _T("+");}
                            }

                            if(LoadCaseNo > 0)  
                            {
                                // Service       
                                if(m_nLcomType == D_LCOMTYPE_GENERAL) rData.nActive = 0;
                                else                                  rData.nActive = 2;  
                                rData.nSubLcomType = 0; 
                                AddLcomBoth(BothD);
                                Set_LoadComb4CivilName_proxy(rData, D_SER);

                            }
                        }
                    }}}}}


}

